function test(name, fn) {
  if (process.env.SAGRO_TEST_FILTER && !new RegExp(process.env.SAGRO_TEST_FILTER, 'i').test(name)) return;
  try {
    fn();
    console.log(`OK ${name}`);
  } catch (error) {
    console.error(`FAIL ${name}`);
    console.error(error.stack || error.message);
    process.exitCode = 1;
  }
}

const asyncTests = [];

function testAsync(name, fn) {
  if (process.env.SAGRO_TEST_FILTER && !new RegExp(process.env.SAGRO_TEST_FILTER, 'i').test(name)) return;
  asyncTests.push({ name, fn });
}

