function sumRows(rows) {
  return rows.reduce((total, row) => total + row.amount, 0);
}

function formatLikeApp(value, currency) {
  const amount = new Intl.NumberFormat('es-AR', {
    minimumFractionDigits: 0,
    maximumFractionDigits: 2
  }).format(value || 0);
  return `${currency === 'USD' ? 'US$' : '$'} ${amount}`;
}

class FakeElement {
  constructor(id) {
    this.id = id || '';
    this.tagName = id || '';
    this.value = '';
    this.innerHTML = '';
    this.textContent = '';
    this.className = '';
    this.dataset = {};
    this.style = { setProperty(name, value) { this[name] = value; } };
    this.children = [];
    this.rowSpan = 1;
    this.colSpan = 1;
    this.eventListeners = {};
    this.classList = { add() {}, remove() {}, toggle() {}, contains() { return false; } };
  }

  setAttribute(name, value) { this[name] = value; }
  removeAttribute(name) { delete this[name]; }
  querySelectorAll() { return []; }
  querySelector() { return null; }
  reset() { this.resetCount = (this.resetCount || 0) + 1; }

  appendChild(child) {
    if (child && typeof child === 'object') child.parentElement = this;
    this.children.push(child);
    return child;
  }

  append(...children) {
    children.forEach((child) => this.appendChild(child));
  }

  replaceChildren(...children) {
    this.children = [];
    this.append(...children);
  }

  addEventListener(type, fn) {
    this.eventListeners[type] ||= [];
    this.eventListeners[type].push(fn);
  }

  click() {
    (this.eventListeners.click || []).forEach((fn) => fn({ currentTarget: this, preventDefault() {} }));
  }

  scrollIntoView() {}

  createTHead() {
    const head = new FakeElement(`${this.id}-thead`);
    head.insertRow = () => {
      const row = new FakeElement(`${this.id}-head-row`);
      head.appendChild(row);
      return row;
    };
    this.tHead = head;
    this.appendChild(head);
    return head;
  }

  createTBody() {
    const body = new FakeElement(`${this.id}-tbody`);
    body.insertRow = () => {
      const row = new FakeElement(`${this.id}-body-row`);
      row.insertCell = () => {
        const cell = new FakeElement(`${this.id}-cell`);
        row.appendChild(cell);
        return cell;
      };
      body.appendChild(row);
      return row;
    };
    this.tBody = body;
    this.appendChild(body);
    return body;
  }

  createTFoot() {
    const foot = new FakeElement(`${this.id}-tfoot`);
    foot.insertRow = () => {
      const row = new FakeElement(`${this.id}-foot-row`);
      row.insertCell = () => {
        const cell = new FakeElement(`${this.id}-foot-cell`);
        row.appendChild(cell);
        return cell;
      };
      foot.appendChild(row);
      return row;
    };
    this.tFoot = foot;
    this.appendChild(foot);
    return foot;
  }
}

function appVmWithPanelDom(overrides = {}) {
  const elements = new Map();
  const ids = [
    'panelExercise', 'panelCurrency', 'panelReading', 'panelDateFrom', 'panelDateTo',
    'panelPositionTable', 'panelUpcomingTable', 'panelExerciseResultTable',
    'panelAgricultureResultTable', 'panelGrainTable', 'panelLivestockResultTable',
    'panelLivestockTable', 'panelTaxTable', 'panelControlTable'
  ];
  ids.forEach((id) => elements.set(id, new FakeElement(id)));
  elements.get('panelExercise').value = '2026/27';
  elements.get('panelCurrency').value = '';
  elements.get('panelReading').value = 'total';
  elements.get('panelDateFrom').value = '2026-09-01';
  elements.get('panelDateTo').value = '2026-09-30';
  const documentStub = {
    getElementById(id) {
      if (!elements.has(id)) elements.set(id, new FakeElement(id));
      if (id === 'agriculturalProjectionForm' && elements.get(id).querySelector === FakeElement.prototype.querySelector) {
        elements.get(id).querySelector = (selector) => selector === '[role="alert"]' ? documentStub.getElementById('agriculturalProjectionError') : null;
      }
      return elements.get(id);
    },
    createElement(tag) {
      return new FakeElement(tag);
    },
    createTextNode(text) {
      const node = new FakeElement('text');
      node.textContent = text;
      return node;
    },
    querySelector() {
      return null;
    },
    querySelectorAll() {
      return [];
    },
    addEventListener() {},
    body: new FakeElement('body')
  };
  const context = {
    window: { SagroCore: Core, SAGRO_APP_TEST_HOOKS: true },
    document: documentStub,
    localStorage: { getItem() { return null; }, setItem() {} },
    Intl,
    Date,
    console,
    Node: FakeElement
  };
  context.window.window = context.window;
  Object.assign(context, overrides);
  vm.runInNewContext(fs.readFileSync(path.join(__dirname, 'app.js'), 'utf8'), context, { filename: 'app.js' });
  return { app: context.window.SagroApp, elements, document: context.document };
}

function appVmWithFlowDom(overrides = {}) {
  const vmApp = appVmWithPanelDom(overrides);
  const defaults = {
    flowActivityFilter: '',
    flowKindFilter: '',
    flowCurrencyFilter: '',
    flowChartFilter: '',
    flowEntityFilter: '',
    flowStartMonth: '2026-09',
    flowExercise: '',
    monthlyHorizon: '3',
    detailStatusFilter: '',
    detailActivityFilter: '',
    detailChartFilter: '',
    detailEntityFilter: '',
    detailCurrencyFilter: '',
    detailDateFrom: '',
    detailDateTo: '',
    grainCerealFilter: '',
    grainCampaignFilter: '',
    grainLocationFilter: '',
    grainCards: '',
    grainStockTable: '',
    grainForwardTable: '',
    grainHistoryTable: '',
    grainLiquidationTable: ''
  };
  Object.entries(defaults).forEach(([id, value]) => {
    if (!vmApp.elements.has(id)) vmApp.elements.set(id, new FakeElement(id));
    vmApp.elements.get(id).value = value;
  });
  return vmApp;
}

function textTree(node) {
  if (!node) return '';
  return `${node.textContent || ''}${(node.children || []).map(textTree).join('')}`;
}

function findNodes(node, predicate, acc = []) {
  if (!node) return acc;
  if (predicate(node)) acc.push(node);
  (node.children || []).forEach((child) => findNodes(child, predicate, acc));
  return acc;
}

