test('1. Pago simple por transferencia', () => {
  const state = fresh();
  const transfer = state.instruments.find((x) => x.id === 'INS-TR-2M');
  assert.equal(transfer.type, 'transfer');
  assert.equal(Core.instrumentIsBankRealized(transfer), true);
  const rows = Core.flowRows(state).filter((row) => row.instrumentId === transfer.id);
  assert.equal(rows[0].userStatus, 'Pagado');
  assert.equal(rows[0].amount, -2000000);
});

test('2. Pago parcial mantiene saldo pendiente', () => {
  const b = Core.documentBreakdown(fresh(), 'DOC-FACT-10M', '2026-09-01');
  assert.equal(b.cancelled, 8000000);
  assert.equal(b.committedPending, 0);
  assert.equal(b.instrumentedFinancialPending, 6000000);
  assert.equal(b.nonInstrumented, 2000000);
});

test('3. OP con varios instrumentos no duplica importe', () => {
  const state = fresh();
  const order = Core.orderBreakdown(state, 'OP-DEMO-001');
  assert.equal(order.applied, 8000000);
  assert.equal(order.paidOrCollected, 2000000);
  assert.equal(order.pending, 0);
  assert.equal(order.financialPending, 6000000);
  const rows = Core.flowRows(state).filter((row) => row.orderId === 'OP-DEMO-001');
  assert.equal(Math.abs(sumRows(rows)), 8000000);
});

