test('5. Cheque propio emitido/entregado/debitado', () => {
  let state = fresh();
  state.instruments.find((x) => x.id === 'INS-CH-30').status = 'issued';
  assert.equal(Core.instrumentIsBankRealized(state.instruments.find((x) => x.id === 'INS-CH-30')), false);
  state = Core.transitionInstrument(state, 'INS-CH-30', 'delivered', null, 'test');
  assert.equal(state.instruments.find((x) => x.id === 'INS-CH-30').status, 'delivered');
  state = Core.transitionInstrument(state, 'INS-CH-30', 'debited', '2026-10-01', 'test');
  assert.equal(Core.instrumentIsBankRealized(state.instruments.find((x) => x.id === 'INS-CH-30')), true);
});

