  state = Core.createOrderTransaction(state, { type: 'payment', documentId: state.documents.at(-1).id, amountApplied: 1000, financialAccountId: 'ACC-GALICIA-ARS', instruments: [{ type: 'vep', amount: 1000, status: 'executed', scheduledDate: '2026-09-20', reference: 'VEP-REAL' }] }, 'test');
