test('Saneamiento legacy completa vínculos técnicos activos de una OP ya anulada', () => {
  let state = fresh();
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', commercialSide: 'purchase', entityId: 'ENT-PROV-AGRI', number: 'DOC-LEGACY-VINCULOS', amount: 1000, currency: 'ARS', issueDate: '2026-09-01', dueDate: '2026-09-30', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS' }, 'test');
  const documentId = state.documents.at(-1).id;
  state = Core.createOrderTransaction(state, { type: 'payment', documentId, amountApplied: 1000, financialAccountId: 'ACC-GALICIA-ARS', instruments: [{ type: 'vep', amount: 1000, status: 'scheduled', scheduledDate: '2026-09-30', reference: 'VEP-LEGACY-VINCULOS' }] }, 'test');
  const orderId = state.orders.at(-1).id;
  const instrumentId = state.instruments.at(-1).id;
  const legacy = structuredClone(state);
  legacy.orders.at(-1).voidedAt = '2026-09-25T12:00:00.000Z';
  assert(legacy.orderInstruments.some((item) => item.orderId === orderId && !item.voidedAt));
  assert.equal(Core.instrumentLinkedOnlyToInactiveOrders(legacy, instrumentId), true);
  assert.equal(Core.flowRows(legacy).some((row) => row.instrumentId === instrumentId), false);
  assert.equal(Core.documentBreakdown(legacy, documentId).nonInstrumented, 1000);
  const repaired = Core.repairInactiveOrderInstrumentTransaction(legacy, instrumentId, 'Vínculos pendientes en OP anulada', 'test');
  assert(repaired.orderDocuments.filter((item) => item.orderId === orderId).every((item) => item.voidedAt));
  assert(repaired.orderInstruments.filter((item) => item.orderId === orderId).every((item) => item.voidedAt));
  assert(repaired.orderDocumentSettlements.filter((item) => state.orderInstruments.some((link) => link.orderId === orderId && link.id === item.orderInstrumentId)).every((item) => item.voidedAt));
  assert.equal(Core.validateState(repaired).length, 0);
  assert.deepEqual(Core.financialMovementRows(repaired), Core.financialMovementRows(legacy));
});

