test('59. Nucleo: compensacion cancela saldos comerciales sin mover Caja/Bancos ni Flujo', () => {
  let state = fresh();
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', entityId: 'ENT-PROV-AGRI', number: 'FAC-COMPRA-COMP', amount: 500000, currency: 'ARS', issueDate: '2026-09-01', dueDate: '2026-09-10', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS', description: 'Compra compensada' }, 'test');
  state = Core.createOrderTransaction(state, { type: 'payment', documentId: state.documents.at(-1).id, amountApplied: 500000, financialAccountId: 'ACC-GALICIA-ARS', instruments: [{ type: 'compensation', amount: 500000, scheduledDate: '2026-09-01', status: 'executed', reference: 'Compensacion comercial' }] }, 'test');
  const instrument = state.instruments.at(-1);
  const cc = Core.currentAccountRows(state, { entityId: 'ENT-PROV-AGRI', currency: 'ARS' });
  const breakdown = Core.documentBreakdown(state, state.documents.at(-1).id);
  assert.equal(Core.instrumentCancelsDocument(instrument), true);
  assert.equal(Core.instrumentIsBankRealized(instrument), false);
  assert.equal(Core.instrumentCommerciallyCancelsNow(instrument), true);
  assert.equal(breakdown.commercialCancelled, 500000);
  assert.equal(breakdown.financialRealized, 0);
  assert.equal(breakdown.committedPending, 0);
  assert.equal(breakdown.status, 'Pagado');
  assert.equal(Core.flowRows(state).some((row) => row.instrumentId === instrument.id), false);
  assert.equal(Core.accountBalances(state).find((account) => account.id === 'ACC-GALICIA-ARS').realBalance, 23000000);
  assert.equal(cc.at(-1).debtBalance, 3250000);
});

test('60. Nucleo: una OP puede cancelar documentos de distintas actividades sin perder imputacion', () => {
  let state = fresh();
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', entityId: 'ENT-PROV-AGRI', number: 'FAC-MIX-AGRI', amount: 700000, currency: 'ARS', issueDate: '2026-09-01', dueDate: '2026-09-10', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS', description: 'Insumos mixtos' }, 'test');
  const agriDocId = state.documents.at(-1).id;
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', entityId: 'ENT-PROV-AGRI', number: 'FAC-MIX-GAN', amount: 300000, currency: 'ARS', issueDate: '2026-09-01', dueDate: '2026-09-10', activity: 'Ganaderia', chartAccountId: 'CA-GAN', description: 'Gasto ganadero mixto' }, 'test');
  const ganDocId = state.documents.at(-1).id;
  state = Core.createOrderTransaction(state, {
    type: 'payment',
    documents: [{ documentId: agriDocId, amountApplied: 700000 }, { documentId: ganDocId, amountApplied: 300000 }],
    financialAccountId: 'ACC-GALICIA-ARS',
    instruments: [{ type: 'transfer', amount: 1000000, scheduledDate: '2026-09-01', status: 'executed', reference: 'TR-MIXTA' }]
  }, 'test');
  const instrument = state.instruments.at(-1);
  const rows = Core.flowRows(state).filter((row) => row.instrumentId === instrument.id);
  assert.equal(rows.length, 2);
  assert.equal(Math.abs(sumRows(rows)), 1000000);
  assert.equal(Math.abs(rows.find((row) => row.activity === 'Agricultura').amount), 700000);
  assert.equal(Math.abs(rows.find((row) => row.activity === 'Ganaderia').amount), 300000);
  assert.equal(rows.find((row) => row.activity === 'Agricultura').chartPath, 'Agricultura > Insumos');
  assert.equal(rows.find((row) => row.activity === 'Ganaderia').chartPath, 'Ganaderia');
  assert.equal(Core.validateState(state).length, 0);
});

test('61. Circuito: OP multiactividad con una transferencia conserva analitica y banco unico', () => {
  let state = fresh();
  addAgroTestAccounts(state);
  const ccBefore = Core.currentAccountRows(state, { entityId: 'ENT-PROV-AGRI', currency: 'ARS' }).at(-1).balance;
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', entityId: 'ENT-PROV-AGRI', number: 'FAC-AGRI-FERT-5M', amount: 5000000, currency: 'ARS', issueDate: '2026-09-02', dueDate: '2026-09-15', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS-FERT', description: 'Fertilizantes' }, 'test');
  const fert = state.documents.at(-1).id;
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', entityId: 'ENT-PROV-AGRI', number: 'FAC-AGRI-SERV-3M', amount: 3000000, currency: 'ARS', issueDate: '2026-09-02', dueDate: '2026-09-15', activity: 'Agricultura', chartAccountId: 'CA-AGRI-SERV-COSECHA', description: 'Servicio agricola' }, 'test');
  const serv = state.documents.at(-1).id;
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', entityId: 'ENT-PROV-AGRI', number: 'FAC-GAN-ALIM-4M', amount: 4000000, currency: 'ARS', issueDate: '2026-09-02', dueDate: '2026-09-15', activity: 'Ganaderia', chartAccountId: 'CA-GAN-ALIM', description: 'Alimento ganadero' }, 'test');
  const gan = state.documents.at(-1).id;
  state = Core.createOrderTransaction(state, {
    type: 'payment',
    documents: [{ documentId: fert, amountApplied: 5000000 }, { documentId: serv, amountApplied: 3000000 }, { documentId: gan, amountApplied: 4000000 }],
    financialAccountId: 'ACC-GALICIA-ARS',
    instruments: [{ type: 'transfer', amount: 12000000, scheduledDate: '2026-09-02', status: 'executed', reference: 'TR-MULTIACTIVIDAD-12M' }]
  }, 'test');
  const orderId = state.orders.at(-1).id;
  const instrument = state.instruments.find((item) => item.reference === 'TR-MULTIACTIVIDAD-12M');
  const rows = Core.flowRows(state).filter((row) => row.instrumentId === instrument.id);
  const bankMovements = state.instruments.filter((item) => item.reference === 'TR-MULTIACTIVIDAD-12M' && Core.instrumentIsBankRealized(item));
  assert.equal(Core.orderBreakdown(state, orderId).applied, 12000000);
  assert.equal(Core.documentBreakdown(state, fert).control, 5000000);
  assert.equal(Core.documentBreakdown(state, serv).control, 3000000);
  assert.equal(Core.documentBreakdown(state, gan).control, 4000000);
  assert.equal(Math.abs(rows.filter((row) => row.activity === 'Agricultura').reduce((sum, row) => sum + row.amount, 0)), 8000000);
  assert.equal(Math.abs(rows.filter((row) => row.activity === 'Ganaderia').reduce((sum, row) => sum + row.amount, 0)), 4000000);
  assert.equal(bankMovements.length, 1);
  assert.equal(bankMovements[0].amount, 12000000);
  assert.equal(Math.abs(sumRows(rows)), 12000000);
  assert.equal(Core.currentAccountRows(state, { entityId: 'ENT-PROV-AGRI', currency: 'ARS' }).at(-1).balance, ccBefore);
  assert.equal(state.orderInstruments.find((link) => link.instrumentId === instrument.id).orderId, orderId);
});

test('62. Circuito: cobro soja y pago posterior no mezclan imputaciones por usar el mismo banco', () => {
  let state = fresh();
  addAgroTestAccounts(state);
  state = Core.createDocumentTransaction(state, { type: 'sale_invoice', entityId: 'ENT-CLIENTE-DEMO', number: 'FAC-SOJA-20M', amount: 20000000, currency: 'ARS', issueDate: '2026-09-02', dueDate: '2026-09-02', activity: 'Agricultura', chartAccountId: 'CA-AGRI', description: 'Venta soja' }, 'test');
  const sale = state.documents.at(-1).id;
  state = Core.createOrderTransaction(state, { type: 'collection', documentId: sale, amountApplied: 20000000, financialAccountId: 'ACC-GALICIA-ARS', instruments: [{ type: 'transfer', amount: 20000000, scheduledDate: '2026-09-02', status: 'executed', reference: 'TR-COBRO-SOJA-20M' }] }, 'test');
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', entityId: 'ENT-PROV-AGRI', number: 'FAC-PAGO-AGRI-8M', amount: 8000000, currency: 'ARS', issueDate: '2026-09-03', dueDate: '2026-09-03', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS', description: 'Pago agricola' }, 'test');
  const agri = state.documents.at(-1).id;
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', entityId: 'ENT-PROV-AGRI', number: 'FAC-PAGO-GAN-4M', amount: 4000000, currency: 'ARS', issueDate: '2026-09-03', dueDate: '2026-09-03', activity: 'Ganaderia', chartAccountId: 'CA-GAN-ALIM', description: 'Pago ganadero' }, 'test');
  const gan = state.documents.at(-1).id;
  state = Core.createOrderTransaction(state, { type: 'payment', documents: [{ documentId: agri, amountApplied: 8000000 }, { documentId: gan, amountApplied: 4000000 }], financialAccountId: 'ACC-GALICIA-ARS', instruments: [{ type: 'transfer', amount: 12000000, scheduledDate: '2026-09-03', status: 'executed', reference: 'TR-PAGO-Z-12M' }] }, 'test');
  const rows = Core.flowRows(state).filter((row) => ['FAC-SOJA-20M', 'FAC-PAGO-AGRI-8M', 'FAC-PAGO-GAN-4M'].includes(state.documents.find((doc) => doc.id === row.documentId)?.number));
  assert.equal(rows.filter((row) => row.direction === 'in' && row.activity === 'Agricultura').reduce((sum, row) => sum + row.amount, 0), 20000000);
  assert.equal(Math.abs(rows.filter((row) => row.direction === 'out' && row.activity === 'Agricultura').reduce((sum, row) => sum + row.amount, 0)), 8000000);
  assert.equal(Math.abs(rows.filter((row) => row.direction === 'out' && row.activity === 'Ganaderia').reduce((sum, row) => sum + row.amount, 0)), 4000000);
  assert.equal(state.instruments.filter((item) => item.reference === 'TR-COBRO-SOJA-20M' && Core.instrumentIsBankRealized(item)).reduce((sum, item) => sum + item.amount, 0), 20000000);
  assert.equal(state.instruments.filter((item) => item.reference === 'TR-PAGO-Z-12M' && Core.instrumentIsBankRealized(item)).reduce((sum, item) => sum + item.amount, 0), 12000000);
});

test('63. Circuito: compensacion es trazable a venta y deuda sin movimiento bancario', () => {
  let state = fresh();
  state = Core.createDocumentTransaction(state, { type: 'sale_invoice', entityId: 'ENT-PROV-AGRI', number: 'FAC-VENTA-COMP-10M', amount: 10000000, currency: 'ARS', issueDate: '2026-09-02', dueDate: '2026-09-15', activity: 'Agricultura', chartAccountId: 'CA-AGRI', description: 'Venta soja compensable' }, 'test');
  const saleId = state.documents.at(-1).id;
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', entityId: 'ENT-PROV-AGRI', number: 'FAC-DEUDA-COMP-8M', amount: 8000000, currency: 'ARS', issueDate: '2026-09-02', dueDate: '2026-09-15', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS', description: 'Deuda insumos compensable' }, 'test');
  const debtId = state.documents.at(-1).id;
  const orderId = 'ORD-COMP-TEST';
  const orderDocumentSale = { id: 'OD-COMP-SALE', orderId, documentId: saleId, amountApplied: 8000000, currency: 'ARS', voidedAt: null };
  const orderDocumentDebt = { id: 'OD-COMP-DEBT', orderId, documentId: debtId, amountApplied: 8000000, currency: 'ARS', voidedAt: null };
  const instrument = { id: 'INS-COMP-8M', type: 'compensation', direction: 'in', entityId: 'ENT-PROV-AGRI', financialAccountId: 'ACC-GALICIA-ARS', amount: 8000000, currency: 'ARS', scheduledDate: '2026-09-02', executedDate: null, status: 'executed', reference: 'COMP-8M', notes: 'Compensacion comercial' };
  const orderInstrument = { id: 'OI-COMP-8M', orderId, instrumentId: instrument.id, amount: 8000000, currency: 'ARS', voidedAt: null };
  state.orders.push({ id: orderId, type: 'collection', entityId: 'ENT-PROV-AGRI', date: '2026-09-02', description: 'Compensacion soja-insumos', activity: 'Agricultura', currency: 'ARS', voidedAt: null });
  state.orderDocuments.push(orderDocumentSale, orderDocumentDebt);
  state.instruments.push(instrument);
  state.orderInstruments.push(orderInstrument);
  state.orderDocumentSettlements.push(
    { id: 'ODS-COMP-SALE', orderDocumentId: orderDocumentSale.id, orderInstrumentId: orderInstrument.id, amount: 8000000, currency: 'ARS', voidedAt: null },
    { id: 'ODS-COMP-DEBT', orderDocumentId: orderDocumentDebt.id, orderInstrumentId: orderInstrument.id, amount: 8000000, currency: 'ARS', voidedAt: null }
  );
  const cc = Core.currentAccountRows(state, { entityId: 'ENT-PROV-AGRI', currency: 'ARS' });
  const saleBreakdown = Core.documentBreakdown(state, saleId);
  const debtBreakdown = Core.documentBreakdown(state, debtId);
  assert.equal(saleBreakdown.commercialCancelled, 8000000);
  assert.equal(saleBreakdown.financialRealized, 0);
  assert.equal(saleBreakdown.nonInstrumented, 2000000);
  assert.equal(debtBreakdown.commercialCancelled, 8000000);
  assert.equal(debtBreakdown.financialRealized, 0);
  assert.equal(debtBreakdown.nonInstrumented, 0);
  assert.equal(debtBreakdown.status, 'Pagado');
  assert.equal(Core.orderBreakdown(state, orderId).commercialCancelled, 8000000);
  assert.equal(Core.validateState(state).length, 0);
  assert.equal(Core.flowRows(state).some((row) => row.instrumentId === instrument.id), false);
  assert.equal(Core.accountBalances(state).find((account) => account.id === 'ACC-GALICIA-ARS').realBalance, 23000000);
  assert.equal(cc.at(-1).debtBalance, 3250000);
  assert.equal(cc.at(-1).receivableBalance, 2000000);
  assert.equal(state.orderDocumentSettlements.filter((settlement) => settlement.orderInstrumentId === orderInstrument.id).length, 2);
});

