  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', entityId: 'ENT-PROV-AGRI', number: 'FAC-PROV-NC', amount: 1000000, currency: 'ARS', issueDate: '2026-09-01', dueDate: '2026-09-10', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS', description: 'Compra base' }, 'test');
  state = Core.createDocumentTransaction(state, { type: 'credit_note', commercialSide: 'supplier', entityId: 'ENT-PROV-AGRI', number: 'NC-PROV', amount: 200000, currency: 'ARS', issueDate: '2026-09-02', dueDate: '2026-09-02', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS', description: 'Credito proveedor' }, 'test');
