test('Economía etapa 1: cargos automáticos respetan actividad período moneda y lectura', () => {
  const state = emptyState();
  const charge = { autoGenerated: true, status: 'executed', currency: 'ARS', date: '2026-09-10', activity: 'Estructura/Admin', amount: 60 };
  state.bankCharges.push({ ...charge, id: 'BC-1' }, { ...charge, id: 'BC-OLD', date: '2026-04-30' },
    { ...charge, id: 'BC-FUTURE', date: '2026-12-01' }, { ...charge, id: 'BC-USD', currency: 'USD' },
    { ...charge, id: 'BC-NORECEIPT', fiscalStatus: 'no_receipt', amount: 10 },
    { ...charge, id: 'BC-AGRI', activity: 'Agricultura', amount: 20 },
    { ...charge, id: 'BC-NONE', activity: '', amount: 5 }, { ...charge, id: 'BC-VOID', voidedAt: '2026-09-11' });
  const f = { exercise: '2026/27', dateTo: '2026-09-30', currency: 'ARS' };
  const total = Core.economicSummary(state, f);
  assert.equal(total.expense, 95);
  assert.equal(Core.economicSummary(state, { ...f, activity: 'Agricultura' }).expense, 20);
  assert.equal(Core.economicSummary(state, { ...f, activity: 'Ganaderia' }).expense, 0);
  assert.equal(Core.economicSummary(state, { ...f, activity: 'Estructura/Admin' }).expense, 70);
  assert.equal(Core.economicSummary(state, { ...f, reading: 'documented' }).expense, 85);
  assert.equal(Core.economicSummary(state, { ...f, reading: 'no_receipt' }).expense, 10);
  assert.equal(total.byActivity.reduce((sum, row) => sum + row.expense, 0), 95);
  assert(total.warnings.some((message) => message.includes('BC-NONE')));
  assert.equal(Core.economicSummary(state, { exercise: '2026/27', currency: 'ARS' }).expense, 155);
});

