function assertIndicatorReconciles(detail) {
  assert(detail.reconciled, detail.limitation);
  assert.equal(detail.rows.reduce((sum, row) => sum + Math.round(row.amount * 100), 0), Math.round(detail.amount * 100));
  assert.equal(Math.round(detail.total * 100), Math.round(detail.amount * 100));
  assert(detail.rows.every((row) => row.currency === detail.currency));
}

test('Indicadores navegables: económicos por actividad moneda lectura período y resultado con signos', () => {
  let state = economicGrainFixture();
  for (const [side, activity, currency, fiscalStatus] of [['purchase', 'Agricultura', 'ARS', 'documented'], ['sale', 'Ganaderia', 'ARS', 'documented'], ['purchase', 'Ganaderia', 'USD', 'no_receipt']]) {
    state = Core.createDocumentTransaction(state, { type: 'credit_note', commercialSide: side, entityId: 'ENT-PROV-AGRI',
      number: `NC-${side}-${activity}`, amount: 100, currency, fiscalStatus, issueDate: '2026-09-12', activity, chartAccountId: 'CA-AGRI-INS' }, 'test');
  }
  state.bankCharges.push({ id: 'BC-TRACE', autoGenerated: true, status: 'executed', activity: 'Estructura/Admin', currency: 'ARS', amount: 3.5, date: '2026-09-12' });
  const before = JSON.stringify(state);
  for (const currency of ['ARS', 'USD']) for (const reading of ['total', 'documented', 'no_receipt']) for (const activity of ['', 'Agricultura', 'Ganaderia']) {
    const filters = { currency, reading, activity, exercise: '2026/27', dateFrom: '2026-09-01', dateTo: '2026-09-30' };
    const summary = Core.economicSummary(state, filters);
    for (const metric of ['income', 'expense', 'result']) assertIndicatorReconciles(Core.economicIndicatorDetail(state, summary, metric, filters));
  }
  const result = Core.economicIndicatorDetail(state, Core.economicSummary(state, { currency: 'ARS' }), 'result', { currency: 'ARS' });
  assert.equal(result.rows.find((row) => row.source === 'grain-commercial-cost').amount, -33130.15);
  assert.equal(result.rows.find((row) => row.number === 'NC-purchase-Agricultura').amount, 100);
  assert.equal(result.rows.find((row) => row.number === 'NC-sale-Ganaderia').amount, -100);
  assert.equal(result.rows.find((row) => row.id === 'BC-TRACE').amount, -3.5);
  assert.deepEqual(result.rows.find((row) => row.source === 'grain-commercial-cost').target, { type: 'document', id: 'DOC-GLIQ-ECON' });
  const old = Core.economicSummary(state, { dateTo: '2026-08-31', currency: 'ARS' });
  assert.equal(Core.economicIndicatorDetail(state, old, 'result', { currency: 'ARS', dateTo: '2026-08-31' }).rows.length, 0);
  assert.equal(JSON.stringify(state), before);
});

test('Indicadores navegables: Cierre saldos parciales solicitudes y confirmaciones sin duplicación', () => {
  const fixture = compensationRequestFixture();
  const filters = { exercise: '2026/27', currency: 'ARS', reading: 'total' };
  const original = Core.closingSummary(fixture.state, filters);
  const requested = Core.closingSummary(fixture.requested, filters);
  assert.deepEqual(requested.financial, original.financial);
  const confirmed = Core.transitionDocumentCompensationTransaction(fixture.requested, fixture.id, { status: 'confirmed', date: '2026-09-04', reason: 'Confirmación sintética' }, 'test');
  const paid = Core.createOrderTransaction(confirmed, { type: 'payment', documentId: 'REQUEST-DEBT', amountApplied: 100,
    financialAccountId: 'ACC-GALICIA-ARS', instruments: [{ type: 'transfer', amount: 100, status: 'executed', scheduledDate: '2026-09-05', reference: 'TR-TRACE' }] }, 'test');
  for (const state of [fixture.state, fixture.requested, confirmed, paid]) {
    const before = JSON.stringify(state);
    const summary = Core.closingSummary(state, filters);
    for (const metric of ['bankCash', 'receivable', 'payable', 'pendingValues', 'vatDifference', 'vatRelated']) assertIndicatorReconciles(Core.closingIndicatorDetail(state, summary, metric));
    assert.equal(JSON.stringify(state), before);
  }
  const payable = Core.closingIndicatorDetail(paid, Core.closingSummary(paid, filters), 'payable');
  assert.equal(payable.rows.find((row) => row.documentId === 'REQUEST-DEBT').amount, 100);
  const receivable = Core.closingIndicatorDetail(paid, Core.closingSummary(paid, filters), 'receivable');
  assert(!receivable.rows.some((row) => row.documentId === 'REQUEST-CREDIT'));
});

