test('81. Cheque recibido cancela cliente y al endosarlo cancela proveedor sin banco ficticio', () => {
  let state = emptyState();
  state = Core.createDocumentTransaction(state, { type: 'sale_invoice', commercialSide: 'sale', entityId: 'ENT-CLIENTE-DEMO', number: 'VENTA-CH-10M', amount: 10000000, economicAmount: 10000000, currency: 'ARS', issueDate: '2026-09-02', dueDate: '2026-09-02', activity: 'Agricultura', chartAccountId: 'CA-AGRI', description: 'Venta cliente con cheque recibido' }, 'test');
  const saleId = state.documents.at(-1).id;
  state = Core.createOrderTransaction(state, { type: 'collection', documentId: saleId, amountApplied: 10000000, financialAccountId: 'ACC-GALICIA-ARS', instruments: [{ type: 'received_check', amount: 10000000, scheduledDate: '2026-09-30', status: 'inPortfolio', reference: 'CH-REC-10M', checkNumber: 'R-10M' }] }, 'test');
  const check = state.instruments.at(-1);
  assert.equal(Core.documentBreakdown(state, saleId).commercialCancelled, 10000000);
  assert.equal(Core.documentBreakdown(state, saleId).financialRealized, 0);
  assert.equal(Core.currentAccountRows(state, { entityId: 'ENT-CLIENTE-DEMO', currency: 'ARS' }).at(-1).balance, 0);
  assert.equal(Core.receivedCheckPortfolioAmount(state, { currency: 'ARS' }), 10000000);
  assert.equal(Core.accountBalances(state).find((account) => account.id === 'ACC-GALICIA-ARS').realBalance, 25000000);
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', commercialSide: 'purchase', entityId: 'ENT-PROV-AGRI', number: 'COMPRA-ENDOSO-10M', amount: 10000000, economicAmount: 10000000, currency: 'ARS', issueDate: '2026-09-03', dueDate: '2026-09-03', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS', description: 'Compra proveedor pagada con endoso' }, 'test');
  const debtId = state.documents.at(-1).id;
  state.instruments.find((item) => item.id === check.id).status = 'endorsed';
  state.instruments.find((item) => item.id === check.id).deliveredToEntityId = 'ENT-PROV-AGRI';
  const orderId = 'OP-ENDOSO-10M';
  const orderDocument = { id: 'OD-ENDOSO-10M', orderId, documentId: debtId, amountApplied: 10000000, currency: 'ARS', voidedAt: null };
  const orderInstrument = { id: 'OI-ENDOSO-10M', orderId, instrumentId: check.id, amount: 10000000, currency: 'ARS', voidedAt: null };
  state.orders.push({ id: orderId, type: 'payment', entityId: 'ENT-PROV-AGRI', date: '2026-09-03', description: 'Endoso cheque recibido', activity: 'Agricultura', currency: 'ARS', voidedAt: null });
  state.orderDocuments.push(orderDocument);
  state.orderInstruments.push(orderInstrument);
  state.orderDocumentSettlements.push({ id: 'ODS-ENDOSO-10M', orderDocumentId: orderDocument.id, orderInstrumentId: orderInstrument.id, amount: 10000000, currency: 'ARS', voidedAt: null });
  assert.equal(Core.documentBreakdown(state, debtId).commercialCancelled, 10000000);
  assert.equal(Core.documentBreakdown(state, debtId).financialRealized, 0);
  assert.equal(Core.currentAccountRows(state, { entityId: 'ENT-PROV-AGRI', currency: 'ARS' }).at(-1).balance, 0);
  assert.equal(Core.receivedCheckPortfolioAmount(state, { currency: 'ARS' }), 0);
  assert.equal(Core.accountBalances(state).find((account) => account.id === 'ACC-GALICIA-ARS').realBalance, 25000000);
  assert.equal(Core.validateState(state).length, 0);
});

