test('96. Cereales: liquidacion compensada con factura de insumos no genera banco ficticio', () => {
  let state = grainStateWithStock();
  state = Core.createGrainLiquidationTransaction(state, { id: 'GLIQ-6', documentId: 'DOC-LIQ-6', date: '2026-09-10', cereal: 'Soja', campaign: '2026/27', locationId: 'GL-FIELD', counterpartyEntityId: 'ENT-PROV-AGRI', kg: 8000, price: 1000000, currency: 'ARS', chartAccountId: 'CA-AGRI-CEREALES-SOJA' }, 'test');
  state = Core.createDocumentTransaction(state, { id: 'DOC-INS-6', type: 'purchase_invoice', commercialSide: 'purchase', entityId: 'ENT-PROV-AGRI', number: 'FAC-INS-6', amount: 8000000, currency: 'ARS', issueDate: '2026-09-10', dueDate: '2026-09-15', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS', description: 'Insumos a compensar' }, 'test');
  const order = { id: 'ORD-COMP-GRAIN', type: 'payment', entityId: 'ENT-PROV-AGRI', date: '2026-09-10', description: 'Compensacion cereal insumos', activity: 'Agricultura', currency: 'ARS', voidedAt: null };
  const instrument = { id: 'INS-COMP-GRAIN', type: 'compensation', direction: 'in', entityId: 'ENT-PROV-AGRI', financialAccountId: 'ACC-GALICIA-ARS', amount: 8000000, currency: 'ARS', scheduledDate: '2026-09-10', executedDate: null, status: 'executed', reference: 'COMP-GRAIN', notes: 'Compensacion sin banco' };
  state.orders.push(order);
  state.instruments.push(instrument);
  state.orderDocuments.push({ id: 'OD-COMP-LIQ', orderId: order.id, documentId: 'DOC-LIQ-6', amountApplied: 8000000, currency: 'ARS', voidedAt: null });
  state.orderDocuments.push({ id: 'OD-COMP-INS', orderId: order.id, documentId: 'DOC-INS-6', amountApplied: 8000000, currency: 'ARS', voidedAt: null });
  state.orderInstruments.push({ id: 'OI-COMP-GRAIN', orderId: order.id, instrumentId: instrument.id, amount: 8000000, currency: 'ARS', voidedAt: null });
  state.orderDocumentSettlements.push({ id: 'ODS-COMP-LIQ', orderDocumentId: 'OD-COMP-LIQ', orderInstrumentId: 'OI-COMP-GRAIN', amount: 8000000, currency: 'ARS', voidedAt: null });
  state.orderDocumentSettlements.push({ id: 'ODS-COMP-INS', orderDocumentId: 'OD-COMP-INS', orderInstrumentId: 'OI-COMP-GRAIN', amount: 8000000, currency: 'ARS', voidedAt: null });
  assert.equal(Core.documentBreakdown(state, 'DOC-LIQ-6').commercialCancelled, 8000000);
  assert.equal(Core.documentBreakdown(state, 'DOC-INS-6').commercialCancelled, 8000000);
  assert.equal(Core.accountBalances(state).find((account) => account.id === 'ACC-GALICIA-ARS').realBalance, 25000000);
  assert.equal(Core.validateState(state).length, 0);
});

