  const debt = { ...state.documents[0], id: 'DOC-COMP-DEUDA', number: 'FACT-LAR', amount: 2294561.59, economicAmount: 2294561.59, taxComponents: [], description: 'Compra insumos' };
  state.documents.push(credit, debt);
  state = Core.createOrderTransaction(state, { type: 'collection', date: '2026-07-22', documentId: credit.id, amountApplied: credit.amount, financialAccountId: 'ACC-GALICIA-ARS', instruments: [] }, 'test');
  const orderId = state.orders.at(-1).id;
  const bank = Core.accountBalances(state);
  const counts = [state.documents.length, state.orders.length, state.instruments.length, state.grainMovements.length];
  const next = Core.createDocumentCompensationTransaction(state, { creditDocumentId: credit.id, debtDocumentId: debt.id, amount: 2294550.61, date: '2026-07-22', reference: 'LAR', reason: 'Aplicación comercial' }, 'usuario');
