test('Conciliación múltiple: solicitud a dos facturas no cancela ni reserva saldos', () => {
  const { state, payload } = grainReconciliationFixture();
  const before = JSON.stringify(state);
  const requested = Core.createGrainReconciliationTransaction(state, payload, 'test');
  assert.equal(JSON.stringify(state), before);
  assert.equal(requested.documentCompensations.length, 2);
  assert.equal(new Set(requested.documentCompensations.map((item) => item.reconciliationId)).size, 1);
  for (const id of ['DOC-REC-CREDIT', 'REC-DEBT-1', 'REC-DEBT-2']) assert.deepEqual(Core.documentBreakdown(requested, id), Core.documentBreakdown(state, id));
  assert.deepEqual(Core.currentAccountRows(requested), Core.currentAccountRows(state));
  assert.deepEqual(Core.validateState(requested), []);
});

test('Conciliación múltiple: confirmación total y parcial por factura sin fondos ni stock nuevo', () => {
  const { state, payload, transition } = grainReconciliationFixture();
  const requested = Core.createGrainReconciliationTransaction(state, payload, 'test');
  const id = requested.documentCompensations[0].reconciliationId;
  const confirmed = Core.transitionGrainReconciliationTransaction(requested, id, transition, 'test');
  assert.equal(Core.documentBreakdown(confirmed, 'DOC-REC-CREDIT').nonInstrumented, 0);
  assert.equal(Core.documentBreakdown(confirmed, 'REC-DEBT-1').nonInstrumented, 0);
  assert.equal(Core.documentBreakdown(confirmed, 'REC-DEBT-2').nonInstrumented, 100000);
  for (const key of ['documents', 'orders', 'instruments', 'orderDocuments', 'orderInstruments', 'orderDocumentSettlements', 'bankCharges', 'grainMovements', 'grainLiquidations']) assert.deepEqual(confirmed[key], state[key], key);
  assert.deepEqual(Core.accountBalances(confirmed), Core.accountBalances(state));
  assert.deepEqual(Core.financialMovementRows(confirmed), Core.financialMovementRows(state));
  const ledger = Core.generalMovementRows(confirmed).filter((row) => row.reconciliationId === id);
  assert.equal(ledger.length, 2);
  assert.equal(ledger.reduce((sum, row) => sum + row.amount, 0), 1000000);
  assert(ledger.every((row) => row.affectsFunds === false));
  const commercial = Core.currentAccountRows(confirmed).filter((row) => row.source === 'documentCompensation');
  assert.equal(commercial.reduce((sum, row) => sum + row.debtChange, 0), -1000000);
  assert.equal(commercial.reduce((sum, row) => sum + row.receivableChange, 0), -1000000);
  assert.equal(Core.flowRows(confirmed).filter((row) => row.source === 'document-balance').reduce((sum, row) => sum + Math.abs(row.amount), 0), 100000);
  assert(confirmed.auditLog.some((row) => row.entityId === id && row.action === 'confirm-grain-reconciliation'));
  assert.deepEqual(confirmed.documentCompensations.map((item) => item.id).sort(), requested.documentCompensations.map((item) => item.id).sort());
  assert.deepEqual(Core.validateState(confirmed), []);
});

