testAsync('Conciliación múltiple API: registra createGrainReconciliation pendiente y rechaza reenvío sin duplicar', async () => {
  let state = grainStateWithStock();
  state = Core.createGrainLiquidationTransaction(state, { id: 'LIQ-API', documentId: 'CREDIT-API', number: 'LIQ-TEST-USDARS-001',
    date: '2026-09-10', cereal: 'Soja', campaign: '2026/27', locationId: 'GL-FIELD', counterpartyEntityId: 'ENT-PROV-AGRI',
    kg: 1000, price: 1500000, currency: 'ARS', chartAccountId: 'CA-AGRI-CEREALES-SOJA' }, 'test');
  for (const [id, amount] of [['FAC-DEMO-10M', 900000], ['FAC-VENCIDA', 400000]]) {
    state = Core.createDocumentTransaction(state, { id, number: id, type: 'purchase_invoice', commercialSide: 'purchase',
      entityId: 'ENT-PROV-AGRI', amount, currency: 'ARS', issueDate: '2026-09-10', activity: 'Agricultura',
      chartAccountId: 'CA-AGRI-INS', description: 'Prueba sintética del endpoint' }, 'test');
  }
  const store = adapter(tempPersistenceRoot());
  store.writeValidated(state, 1, 'synthetic-api-fixture');
  const before = store.loadState();
  const body = { action: 'createGrainReconciliation', stateVersion: before.stateVersion, payload: {
    liquidationId: 'LIQ-API', date: '2026-09-12', reference: 'CONC-PRUEBA-001', reason: 'Prueba local',
    allocations: [{ debtDocumentId: 'FAC-DEMO-10M', amount: 900000 }, { debtDocumentId: 'FAC-VENCIDA', amount: 400000 }]
  } };
  const call = (request) => callApiForTest({ method: 'POST', url: '/api/transaction', body: request, persistence: store, auth: { required: false } });
  const response = await call(body);
  assert.equal(response.status, 200, response.payload.error);
  assert.equal(response.payload.ok, true);
  const requested = store.loadState();
  const items = requested.state.documentCompensations;
  assert.equal(items.length, 2);
  assert(items.every((item) => item.status === 'requested' && item.reference === 'CONC-PRUEBA-001'));
  assert.equal(items.reduce((sum, item) => sum + item.amount, 0), 1300000);
  assert.equal(Core.documentBreakdown(requested.state, 'CREDIT-API').nonInstrumented, 1500000);
  for (const id of ['CREDIT-API', 'FAC-DEMO-10M', 'FAC-VENCIDA']) assert.deepEqual(Core.documentBreakdown(requested.state, id), Core.documentBreakdown(before.state, id));
  assert.deepEqual(Core.financialMovementRows(requested.state), Core.financialMovementRows(before.state));
  assert.deepEqual(Core.currentAccountRows(requested.state), Core.currentAccountRows(before.state));
  assert.deepEqual(Core.generalMovementRows(requested.state), Core.generalMovementRows(before.state));
  const repeated = await call(body);
  assert.equal(repeated.status, 409);
  assert.deepEqual(store.loadState(), requested);
  // Check the second registered action too; confirmation remains explicit and grouped.
  const confirmation = { action: 'transitionGrainReconciliation', id: items[0].reconciliationId,
    stateVersion: requested.stateVersion, payload: { status: 'confirmed', date: '2026-09-13', reference: 'CONF-TEST', reason: 'Sólo prueba sintética' } };
  const confirmed = await call(confirmation);
  assert.equal(confirmed.status, 200, confirmed.payload.error);
  assert.equal(Core.documentBreakdown(confirmed.payload.state, 'CREDIT-API').nonInstrumented, 200000);
  assert.deepEqual(Core.financialMovementRows(confirmed.payload.state), Core.financialMovementRows(before.state));
  assert.equal((await call(confirmation)).status, 409);
  assert.equal(store.loadState().state.documentCompensations.length, 2);
  assert.deepEqual(Core.validateState(store.loadState().state), []);
});

