test('Estados compensación: confirmar conserva ID, cancela ambos saldos y no crea fondos', () => {
  const { requested, id } = compensationRequestFixture();
  const before = JSON.stringify(requested);
  const next = Core.transitionDocumentCompensationTransaction(requested, id, { status: 'confirmed', date: '2026-09-04', reference: 'Resumen proveedor', reason: 'Conciliado' }, 'conciliador');
  assert.equal(JSON.stringify(requested), before);
  assert.equal(next.documentCompensations.at(-1).id, id);
  assert.equal(next.documentCompensations.at(-1).requestedDate, '2026-09-02');
  assert.equal(next.documentCompensations.at(-1).requestedReference, 'Pedido al proveedor');
  assert.equal(next.documentCompensations.at(-1).reference, 'Resumen proveedor');
  assert.equal(Core.documentBreakdown(next, 'REQUEST-CREDIT').nonInstrumented, 0);
  assert.equal(Core.documentBreakdown(next, 'REQUEST-DEBT').nonInstrumented, 200);
  assert.equal(Core.documentBreakdown(next, 'REQUEST-CREDIT', '2026-09-03', true).nonInstrumented, 1000);
  assert.equal(Core.currentAccountRows(next).filter((row) => row.id === id).length, 2);
  assert.equal(Core.generalMovementRows(next).find((row) => row.sourceId === id).affectsFunds, false);
  assert.deepEqual(Core.accountBalances(next), Core.accountBalances(requested));
  for (const key of ['documents', 'orders', 'instruments', 'orderDocuments', 'orderDocumentSettlements']) assert.deepEqual(next[key], requested[key]);
  assert.equal(next.auditLog[0].user, 'conciliador');
  assert.equal(Core.validateState(next).length, 0);
  assert.throws(() => Core.transitionDocumentCompensationTransaction(next, id, { status: 'confirmed' }, 'test'), /Sólo una solicitud/);
  assert.throws(() => Core.transitionDocumentCompensationTransaction(next, id, { status: 'cancelled' }, 'test'), /Sólo una solicitud/);
});

