test('Compensación USD/ARS: parcial y total cancelan cada moneda sin duplicación bancaria', () => {
  const { state, credit, debt, payload } = crossCompensationFixture();
  const requested = Core.createDocumentCompensationTransaction(state, payload, 'test');
  const id = requested.documentCompensations.at(-1).id;
  const partial = Core.transitionDocumentCompensationTransaction(requested, id, { status: 'confirmed', date: '2026-09-04', reference: 'Resumen', reason: 'Conciliado' }, 'test');
  assert.equal(Core.documentBreakdown(partial, debt.id).nonInstrumented, 500);
  assert.equal(Core.documentBreakdown(partial, credit.id).nonInstrumented, 1250000);
  const cc = Core.currentAccountRows(partial).filter((row) => row.id === id);
  assert.equal(cc.find((row) => row.currency === 'USD').debtChange, -500);
  assert.equal(cc.find((row) => row.currency === 'ARS').receivableChange, -750000);
  const flow = Core.flowRows(partial);
  assert.equal(flow.find((row) => row.source === 'document-balance' && row.documentId === debt.id).amount, -500);
  assert.equal(flow.find((row) => row.source === 'document-balance' && row.documentId === credit.id).amount, 1250000);
  const ledger = Core.generalMovementRows(partial).find((row) => row.sourceId === id);
  assert.equal(ledger.amount, 750000); assert.equal(ledger.debtAmount, 500);
  assert.equal(ledger.currency, 'ARS'); assert.equal(ledger.debtCurrency, 'USD');
  assert.equal(ledger.affectsFunds, false);
  const full = Core.createDocumentCompensationTransaction(partial, { ...payload, status: 'confirmed' }, 'test');
  assert.equal(Core.documentBreakdown(full, debt.id).nonInstrumented, 0);
  assert.equal(Core.documentBreakdown(full, credit.id).nonInstrumented, 500000);
  assert.deepEqual(full.documents, state.documents);
  assert.deepEqual(Core.accountBalances(full), Core.accountBalances(state));
  assert.deepEqual(Core.financialMovementRows(full), Core.financialMovementRows(state));
  assert.equal(Core.validateState(full).length, 0);
  assert(partial.auditLog[0].changes.some((change) => change.field === 'conversionConfirmed' && change.to.exchangeRate === 1500));
  assert.throws(() => Core.transitionDocumentCompensationTransaction(partial, id, { status: 'confirmed' }, 'test'), /Sólo una solicitud/);
});

