test('Compensación USD/ARS: ND informativa conserva IVA y se cancela separada al TC base', () => {
  const { state, payload, debt, credit } = crossCompensationFixture();
  const ndState = Core.createDocumentTransaction(state, { type: 'debit_note', commercialSide: 'purchase', entityId: debt.entityId, activity: debt.activity, chartAccountId: debt.chartAccountId, number: 'ND-FX', currency: 'ARS', issueDate: '2026-09-01', amount: 121000, netTaxedAmount: 100000, vatRate: 21, vatAmount: 21000, reason: 'ND independiente' }, 'test');
  const nd = ndState.documents.at(-1), before = JSON.stringify(ndState);
  const linked = Core.updateDocumentTransaction(ndState, nd.id, { relatedInvoiceIds: [debt.id], reason: 'Referencia al original' }, 'test');
  assert.equal(JSON.stringify(ndState), before);
  assert.deepEqual(Core.currentAccountRows(linked), Core.currentAccountRows(ndState));
  assert.deepEqual(linked.documents.at(-1).taxComponents, nd.taxComponents);
  assert.equal(linked.documents.at(-1).amount, 121000);
  assert(Core.documentDeletionPreview(linked, debt.id).blockers.some((text) => /ND/.test(text)));
  const compensated = Core.createDocumentCompensationTransaction(linked, { ...payload, status: 'confirmed', amount: 1500000, debtAmount: 1000 }, 'test');
  assert.equal(Core.documentBreakdown(compensated, debt.id).nonInstrumented, 0);
  assert.equal(Core.documentBreakdown(compensated, nd.id).nonInstrumented, 121000);
  const both = Core.createDocumentCompensationTransaction(compensated, { creditDocumentId: credit.id, debtDocumentId: nd.id, amount: 121000, date: '2026-09-04', reason: 'ND por separado' }, 'test');
  assert.equal(Core.documentBreakdown(both, credit.id).nonInstrumented, 379000);
  assert.equal(Core.documentBreakdown(both, nd.id).nonInstrumented, 0);
  assert.equal(both.documents.length, ndState.documents.length);
  assert.deepEqual(Core.accountBalances(both), Core.accountBalances(state));
  assert.equal(Core.validateState(both).length, 0);
  assert.throws(() => Core.updateDocumentTransaction(ndState, nd.id, { relatedInvoiceIds: [credit.id], reason: 'Incorrecto' }, 'test'), /Factura origen/);
});

