function partialPaymentCompensationFixture(applied = 10000000, creditAmount = 500000) {
  const { state, payload } = compensationRequestFixture();
  const credit = state.documents.find((doc) => doc.id === payload.creditDocumentId);
  const debt = state.documents.find((doc) => doc.id === payload.debtDocumentId);
  Object.assign(credit, { type: 'settlement', number: 'LIQ-TEST-COMP-002', amount: creditAmount, economicAmount: creditAmount });
  Object.assign(debt, { number: 'FAC-DEMO-10M', amount: 10000000, economicAmount: 10000000 });
  const ordered = Core.createOrderTransaction(state, { type: 'payment', date: '2026-09-02', documentId: debt.id, amountApplied: applied, financialAccountId: 'ACC-GALICIA-ARS', instruments: [
    { type: 'transfer', amount: 3000000, scheduledDate: '2026-09-02', status: 'executed', reference: 'PAGO-ANTERIOR' },
    { type: 'own_check', amount: 5000000, scheduledDate: '2026-10-20', deliveredDate: '2026-09-02', status: 'delivered', checkNumber: 'TEST-PARCIAL-001', reference: 'CHEQUE-ANTERIOR' }
  ] }, 'test');
  const requestPayload = { ...payload, amount: 500000 };
  const requested = Core.createDocumentCompensationTransaction(ordered, requestPayload, 'test');
  return { ordered, requested, credit, debt, requestPayload, id: requested.documentCompensations.at(-1).id, orderId: ordered.orders.at(-1).id };
}

test('Compensación pagos parciales: FAC-DEMO-10M queda en 1,5 M y liquidación en cero sin modificar pagos', () => {
  const { ordered, requested, id, credit, debt, orderId } = partialPaymentCompensationFixture();
  const before = JSON.stringify(requested);
  assert.equal(Core.documentBreakdown(requested, debt.id).commercialCancelled, 8000000);
  assert.equal(Core.documentBreakdown(requested, debt.id).nonInstrumented, 2000000);
  assert.deepEqual(Core.currentAccountRows(requested), Core.currentAccountRows(ordered));
  const next = Core.transitionDocumentCompensationTransaction(requested, id, { status: 'confirmed', date: '2026-09-04', reference: 'RESUMEN-LOCAL', reason: 'Compensación de saldo libre' }, 'auditor');
  assert.equal(JSON.stringify(requested), before);
  assert.equal(Core.documentBreakdown(next, debt.id).nonInstrumented, 1500000);
  assert.equal(Core.documentBreakdown(next, credit.id).nonInstrumented, 0);
  assert.equal(Core.orderBreakdown(next, orderId).commercialCancelled, 8500000);
  assert.equal(Core.orderBreakdown(next, orderId).notCoveredByInstrument, 1500000);
  for (const key of ['documents', 'orders', 'instruments', 'orderDocuments', 'orderInstruments', 'orderDocumentSettlements', 'bankCharges', 'orderTaxWithholdings', 'orderPracticedWithholdings']) assert.deepEqual(next[key], ordered[key], key);
  assert.deepEqual(Core.financialMovementRows(next), Core.financialMovementRows(ordered));
  assert.deepEqual(Core.economicSummary(next), Core.economicSummary(ordered));
  assert.equal(Core.flowRows(next).find((row) => row.documentId === debt.id && row.source === 'document-balance').amount, -1500000);
  assert.equal(Core.validateState(next).length, 0);
  assert.throws(() => Core.transitionDocumentCompensationTransaction(next, id, { status: 'confirmed', date: '2026-09-04', reason: 'Duplicado' }, 'test'), /Sólo una solicitud/);
  assert.throws(() => Core.addOrderInstrumentsTransaction(next, orderId, { instruments: [{ type: 'transfer', currency: 'ARS', financialAccountId: 'ACC-GALICIA-ARS', amount: 1600000, scheduledDate: '2026-10-01', status: 'scheduled' }] }, 'test'), /saldo|super|exced/i);
});

