test('Edición de compensación conserva ID y vínculos, actualiza ambos saldos sin banco ni resultado nuevo', () => {
  let state = Core.minimalDemoState('2026-07-22');
  const credit = { ...state.documents[0], id: 'DOC-EDIT-CREDIT', type: 'sale_invoice', commercialSide: 'sale', number: 'VENTA-EDIT', amount: 1000, economicAmount: 1000, taxComponents: [] };
  const debt = { ...state.documents[0], id: 'DOC-EDIT-DEBT', number: 'COMPRA-EDIT', amount: 1200, economicAmount: 1200, taxComponents: [] };
  state.documents.push(credit, debt);
  state = Core.createDocumentCompensationTransaction(state, { creditDocumentId: credit.id, debtDocumentId: debt.id, amount: 500, date: '2026-07-22', reference: 'Original', reason: 'Alta local' }, 'test');
  const id = state.documentCompensations[0].id;
  const original = JSON.stringify(state);
  const bank = Core.accountBalances(state);
  const economic = Core.economicSummary(state, { currency: 'ARS' });
  const next = Core.editDocumentCompensationTransaction(state, id, { amount: 700, date: '2026-07-23', reference: 'Corregida', notes: 'Ajuste documental', reason: 'Error de carga' }, 'auditor');
  assert.equal(next.documentCompensations.length, 1);
  assert.equal(next.documentCompensations[0].id, id);
  assert.equal(next.documentCompensations[0].creditDocumentId, credit.id);
  assert.equal(next.documentCompensations[0].debtDocumentId, debt.id);
  assert.equal(Core.documentBreakdown(next, credit.id).nonInstrumented, 300);
  assert.equal(Core.documentBreakdown(next, debt.id).nonInstrumented, 500);
  assert.deepEqual(Core.accountBalances(next), bank);
  assert.deepEqual(Core.economicSummary(next, { currency: 'ARS' }), economic);
  assert.equal(Core.currentAccountRows(next, { entityId: credit.entityId }).filter((row) => row.source === 'documentCompensation' && row.id === id).length, 2);
  assert.equal(next.auditLog[0].action, 'edit-document-compensation');
  assert.equal(next.auditLog[0].reason, 'Error de carga');
  assert.equal(next.auditLog[0].user, 'auditor');
  assert(next.auditLog[0].changes.some((change) => change.field === 'amount' && change.from === 500 && change.to === 700));
  assert.equal(JSON.stringify(state), original);
  assert.equal(Core.validateState(next).length, 0);
  const gateway = new MemoryFirestoreGateway();
  firestoreAdapter(gateway).writeValidated(next, 1);
  const reloaded = firestoreAdapter(gateway).loadState().state;
  assert.deepEqual(reloaded.documentCompensations, next.documentCompensations);
  assert.equal(Core.validateState(reloaded).length, 0);
});

test('Edición de compensación bloquea exceso, distinta contraparte y reasignación con OP vinculada', () => {
  let state = Core.minimalDemoState('2026-07-22');
  const credit = { ...state.documents[0], id: 'DOC-EDIT-IN', type: 'sale_invoice', commercialSide: 'sale', number: 'VENTA-BLOCK', amount: 1000, economicAmount: 1000, taxComponents: [] };
  const debt = { ...state.documents[0], id: 'DOC-EDIT-OUT', number: 'COMPRA-BLOCK', amount: 1000, economicAmount: 1000, taxComponents: [] };
  const other = { ...debt, id: 'DOC-EDIT-OTHER', entityId: 'ENT-CLIENTE-DEMO' };
  state.documents.push(credit, debt, other);
  state = Core.createOrderTransaction(state, { type: 'collection', date: '2026-07-22', documentId: credit.id, amountApplied: 1000, financialAccountId: 'ACC-GALICIA-ARS', instruments: [] }, 'test');
  state = Core.createDocumentCompensationTransaction(state, { creditDocumentId: credit.id, debtDocumentId: debt.id, amount: 500, date: '2026-07-22', reason: 'Alta local' }, 'test');
  const id = state.documentCompensations[0].id;
  const original = JSON.stringify(state);
  assert.throws(() => Core.editDocumentCompensationTransaction(state, id, { amount: 1001, reason: 'Exceso' }, 'test'), /Saldo libre insuficiente/);
  assert.throws(() => Core.editDocumentCompensationTransaction(state, id, { debtDocumentId: other.id, reason: 'Contraparte' }, 'test'), /misma contraparte/);
  assert.throws(() => Core.editDocumentCompensationTransaction(state, id, { creditDocumentId: debt.id, reason: 'Reasignación' }, 'test'), /OP\/OC vinculada/);
  assert.throws(() => Core.editDocumentCompensationTransaction(state, id, { amount: 600 }, 'test'), /Motivo obligatorio/);
  assert.equal(JSON.stringify(state), original);
  assert.equal(Core.validateState(state).length, 0);
});

