test('Compensación bilateral conserva referencias en el round-trip local y bloquea pares incompatibles', () => {
  const state = Core.minimalDemoState('2026-07-22');
  const credit = { ...state.documents[0], id: 'DOC-COMP-RT-IN', type: 'sale_invoice', commercialSide: 'sale', number: 'CRED-RT', amount: 800, economicAmount: 800, taxComponents: [] };
  const debt = { ...state.documents[0], id: 'DOC-COMP-RT-OUT', number: 'DEBT-RT', amount: 1000, economicAmount: 1000, taxComponents: [] };
  const otherDebt = { ...debt, id: 'DOC-COMP-RT-OTHER', entityId: state.entities.find((item) => item.id !== credit.entityId).id };
  state.documents.push(credit, debt, otherDebt);
  const payload = { creditDocumentId: credit.id, debtDocumentId: debt.id, amount: 500, date: '2026-07-22', reason: 'Prueba local' };
  assert.throws(() => Core.createDocumentCompensationTransaction(state, { ...payload, debtDocumentId: otherDebt.id }, 'test'), /misma contraparte/);
  const next = Core.createDocumentCompensationTransaction(state, payload, 'test');
  const gateway = new MemoryFirestoreGateway();
  const store = firestoreAdapter(gateway);
  store.writeValidated(next, 1);
  const loaded = firestoreAdapter(gateway).loadState().state;
  assert.deepEqual(loaded.documentCompensations, next.documentCompensations);
  assert.equal(Core.documentBreakdown(loaded, credit.id).nonInstrumented, 300);
  assert.equal(Core.documentBreakdown(loaded, debt.id).nonInstrumented, 500);
  assert.equal(Core.validateState(loaded).length, 0);
  const target = loaded.entities.find((item) => item.id !== credit.entityId && item.active !== false);
  assert.equal(Core.entityMergePreview(loaded, credit.entityId, target.id).ambiguous.length, 0);
  const merged = Core.mergeEntitiesTransaction(loaded, credit.entityId, target.id, 'Unificación posterior', 'test');
  assert.equal(merged.documentCompensations[0].entityId, target.id);
  assert.equal(Core.validateState(merged).length, 0);
});

