test('Liquidacion historica: IVA 10,5% actualiza origen, documento y OC sin tocar stock ni banco', () => {
  const { state, documentId, liquidationId, orderId } = historicalGrainLiquidationFixture();
  const physicalBefore = cloneForTest(state.grainMovements);
  const stockBefore = Core.grainStockAt(state, { cereal: 'Maiz', campaign: '2025/26', locationId: 'GL-ACOPIO-DEMO' });
  const bankBefore = Core.accountBalances(state);
  const counts = { liquidations: state.grainLiquidations.length, documents: state.documents.length, orders: state.orders.length, instruments: state.instruments.length };
  const corrected = Core.correctHistoricalGrainLiquidationTransaction(state, liquidationId, { netTaxedAmount: 2107664.13, vatCondition: '10.5', vatAmount: 221304.73, totalAmount: 2328968.86, reason: 'IVA omitido en migracion' }, 'usuario-local');
  const liquidation = corrected.grainLiquidations.find((item) => item.id === liquidationId);
  const doc = corrected.documents.find((item) => item.id === documentId);
  const link = corrected.orderDocuments.find((item) => item.orderId === orderId && item.documentId === documentId);
  assert.equal(liquidation.kg, 8043);
  assert.equal(liquidation.netTaxedAmount, 2107664.13);
  assert.equal(liquidation.vatAmount, 221304.73);
  assert.equal(liquidation.totalAmount, 2328968.86);
  assert.equal(doc.amount, 2328968.86);
  assert.equal(doc.economicAmount, 2107664.13);
  assert.equal(doc.taxComponents.find((item) => item.taxType === 'vat').amount, 221304.73);
  assert.equal(link.id, state.orderDocuments.find((item) => item.orderId === orderId).id);
  assert.equal(link.amountApplied, 2328968.86);
  assert.equal(Core.orderBreakdown(corrected, orderId).applied, 2328968.86);
  assert.equal(Core.documentBreakdown(corrected, documentId).nonInstrumented, 2328968.86);
  assert.deepEqual(corrected.grainMovements, physicalBefore);
  assert.equal(Core.grainStockAt(corrected, { cereal: 'Maiz', campaign: '2025/26', locationId: 'GL-ACOPIO-DEMO' }), stockBefore);
  assert.deepEqual(Core.accountBalances(corrected), bankBefore);
  assert.deepEqual({ liquidations: corrected.grainLiquidations.length, documents: corrected.documents.length, orders: corrected.orders.length, instruments: corrected.instruments.length }, counts);
  assert.equal(state.documents.find((item) => item.id === documentId).amount, 2107664.13);
  assert.equal(corrected.auditLog[0].reason, 'IVA omitido en migracion');
  assert.equal(corrected.auditLog[0].user, 'usuario-local');
  assert.equal(Core.validateState(corrected).length, 0);
});

test('Liquidacion historica: bloquea instrumentos, desglose falso y motivo ausente sin mutar estado', () => {
  const { state, liquidationId } = historicalGrainLiquidationFixture(true);
  const before = cloneForTest(state);
  const changes = { netTaxedAmount: 2107664.13, vatCondition: '10.5', vatAmount: 221304.73, totalAmount: 2328968.86, reason: 'Correccion fiscal' };
  assert.throws(() => Core.correctHistoricalGrainLiquidationTransaction(state, liquidationId, changes, 'test'), /instrumentos/);
  assert.deepEqual(state, before);
  const clean = historicalGrainLiquidationFixture();
  const shared = historicalGrainLiquidationFixture();
  shared.state.documents.push({ ...shared.state.documents.find((item) => item.id === shared.documentId), id: 'DOC-LOCAL-EXTRA', grainLiquidationId: '', number: 'DOC-LOCAL-EXTRA', amount: 100, economicAmount: 100 });
  shared.state.orderDocuments.push({ id: 'OD-LOCAL-EXTRA', orderId: shared.orderId, documentId: 'DOC-LOCAL-EXTRA', amountApplied: 100, currency: 'ARS', voidedAt: null });
  assert.equal(Core.validateState(shared.state).length, 0);
  assert.throws(() => Core.correctHistoricalGrainLiquidationTransaction(shared.state, shared.liquidationId, changes, 'test'), /exclusivamente/);
  assert.throws(() => Core.correctHistoricalGrainLiquidationTransaction(clean.state, clean.liquidationId, { ...changes, totalAmount: 2107664.13 }, 'test'), /total indicado/);
  assert.throws(() => Core.correctHistoricalGrainLiquidationTransaction(clean.state, clean.liquidationId, { ...changes, reason: '' }, 'test'), /Motivo obligatorio/);
  assert.equal(Core.validateState(clean.state).length, 0);
});

