function firestoreAdapter(gateway = new MemoryFirestoreGateway(), environment = 'demo') {
  return new FirestorePersistenceAdapter({ environment, Core, gateway });
}

function authForApiTests() {
  return {
    required: true,
    allowedEmails: new Set(['admin@sagro.test']),
    allowedUids: new Set(['uid-admin']),
    webConfig: {
      apiKey: 'demo-web-key',
      projectId: 'sagro-admin-demo',
      authDomain: 'sagro-admin-demo.firebaseapp.com',
      authEmulatorHost: ''
    },
    verifier: {
      async verifyIdToken(token) {
        if (token === 'valid-admin') return { uid: 'uid-admin', email: 'admin@sagro.test' };
        if (token === 'valid-outsider') return { uid: 'uid-outsider', email: 'outsider@sagro.test' };
        throw new Error('bad token');
      }
    }
  };
}

function fakeHttpRequest(method, url, body = null, headers = {}) {
  const text = body == null ? '' : JSON.stringify(body);
  let sent = false;
  const req = new Readable({
    read() {
      if (!sent) {
        this.push(text);
        sent = true;
      }
      this.push(null);
    }
  });
  req.method = method;
  req.url = url;
  req.headers = headers;
  return req;
}

function callApiForTest({ method = 'GET', url = '/api/state', body = null, headers = {}, persistence, auth }) {
  return new Promise((resolve) => {
    const res = {
      statusCode: 0,
      headers: {},
      writeHead(status, responseHeaders) {
        this.statusCode = status;
        this.headers = responseHeaders || {};
      },
      end(text) {
        resolve({ status: this.statusCode, headers: this.headers, payload: JSON.parse(text || '{}') });
      }
    };
    handleApi(fakeHttpRequest(method, url, body, headers), res, persistence, auth);
  });
}

