test('257b. Firestore adapter: retenciones sobreviven save reload cache backup restore y bases anteriores', () => {
  const gateway = new MemoryFirestoreGateway();
  const store = firestoreAdapter(gateway);
  let state = emptyState();
  state = Core.createDocumentTransaction(state, { type: 'sale_invoice', commercialSide: 'sale', entityId: 'ENT-CLIENTE-DEMO', number: 'FS-RET-001', amount: 100, currency: 'ARS', issueDate: '2026-09-01', dueDate: '2026-09-20', activity: 'Agricultura', chartAccountId: 'CA-AGRI', description: 'Round trip retencion' }, 'test');
  state = Core.createOrderTransaction(state, { type: 'collection', documentId: state.documents.at(-1).id, amountApplied: 100, financialAccountId: 'ACC-GALICIA-ARS', instruments: [], withholdings: [{ taxType: 'withholding_income_tax', amount: 100, date: '2026-09-20', reference: 'RET-FS' }] }, 'test');
  const withholdingId = state.orderTaxWithholdings[0].id;
  store.writeValidated(state, 1);

  const reloadedStore = firestoreAdapter(gateway);
  const firstRead = reloadedStore.loadState();
  assert.equal(firstRead.state.orderTaxWithholdings[0].id, withholdingId);
  assert.equal(Core.validateState(firstRead.state).length, 0);
  const secondRead = reloadedStore.loadState();
  assert.equal(secondRead.state.orderTaxWithholdings[0].id, withholdingId);
  assert.equal(reloadedStore.lastReadStats.cacheHit, true);

  const backup = reloadedStore.createBackup('withholding-round-trip');
  assert.equal(backup.state.orderTaxWithholdings[0].id, withholdingId);
  const changed = JSON.parse(JSON.stringify(secondRead.state));
  changed.orderTaxWithholdings[0].reference = 'RET-FS-EDITADA';
  gateway.writeLog = [];
  const changedRecord = reloadedStore.saveState(changed, { expectedVersion: secondRead.stateVersion });
  assert(gateway.writeLog.some((entry) => entry.action === 'set' && entry.path.includes(`/collections/orderTaxWithholdings/records/${withholdingId}`)));
  const withoutRetention = JSON.parse(JSON.stringify(changedRecord.state));
  withoutRetention.orderTaxWithholdings = [];
  gateway.writeLog = [];
  reloadedStore.saveState(withoutRetention, { expectedVersion: changedRecord.stateVersion });
  assert(gateway.writeLog.some((entry) => entry.action === 'delete' && entry.path.includes(`/collections/orderTaxWithholdings/records/${withholdingId}`)));
  const restored = reloadedStore.restoreBackup(backup);
  assert.equal(restored.state.orderTaxWithholdings[0].id, withholdingId);
  assert.equal(Core.validateState(restored.state).length, 0);

  const legacyGateway = new MemoryFirestoreGateway();
  const legacyStore = firestoreAdapter(legacyGateway);
  const legacyState = Core.demoState();
  delete legacyState.orderTaxWithholdings;
  legacyStore.writeValidated(legacyState, 1);
  const legacyReload = firestoreAdapter(legacyGateway).loadState();
  assert.equal((legacyReload.state.orderTaxWithholdings || []).length, 0);
  assert.equal(Core.validateState(legacyReload.state).length, 0);
});

