test('288. Ordenes: recomposicion sensible recalcula relaciones solo si instrumentos no realizaron', () => {
  let state = emptyState();
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', commercialSide: 'purchase', entityId: 'ENT-PROV-AGRI', number: 'FAC-EDIT-A', amount: 1000, currency: 'ARS', issueDate: '2026-09-01', dueDate: '2026-09-30', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS', description: 'Factura A' }, 'test');
  const docA = state.documents.at(-1).id;
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', commercialSide: 'purchase', entityId: 'ENT-PROV-AGRI', number: 'FAC-EDIT-B', amount: 500, currency: 'ARS', issueDate: '2026-09-01', dueDate: '2026-09-30', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS', description: 'Factura B' }, 'test');
  const docB = state.documents.at(-1).id;
  state = Core.createOrderTransaction(state, { type: 'payment', documentId: docA, amountApplied: 1000, financialAccountId: 'ACC-GALICIA-ARS', instruments: [{ type: 'transfer', amount: 400, scheduledDate: '2026-09-20', status: 'scheduled', reference: 'TR-OLD' }] }, 'test');
  const orderId = state.orders.at(-1).id;
  state = Core.updateOrderTransaction(state, orderId, { documents: [{ documentId: docA, amountApplied: 800 }, { documentId: docB, amountApplied: 500 }], instruments: [{ type: 'transfer', amount: 700, scheduledDate: '2026-09-25', status: 'scheduled', reference: 'TR-NEW' }] }, 'test');
  const breakdown = Core.orderBreakdown(state, orderId);
  assert.equal(breakdown.applied, 1300);
  assert.equal(breakdown.pending, 700);
  assert.equal(state.orderDocuments.filter((item) => item.orderId === orderId && !item.voidedAt).length, 2);
  assert.equal(state.orderDocumentSettlements.filter((item) => !item.voidedAt).reduce((sum, item) => sum + item.amount, 0), 700);
  assert.equal(Core.validateState(state).length, 0);
});

test('289. Ordenes: no recomponer instrumentos realizados o comercialmente cancelatorios', () => {
  let state = emptyState();
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', commercialSide: 'purchase', entityId: 'ENT-PROV-AGRI', number: 'FAC-EDIT-REAL', amount: 1000, currency: 'ARS', issueDate: '2026-09-01', dueDate: '2026-09-30', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS', description: 'Factura realizada' }, 'test');
  const docId = state.documents.at(-1).id;
  state = Core.createOrderTransaction(state, { type: 'payment', documentId: docId, amountApplied: 1000, financialAccountId: 'ACC-GALICIA-ARS', instruments: [{ type: 'transfer', amount: 1000, scheduledDate: '2026-09-20', status: 'executed', reference: 'TR-REAL' }] }, 'test');
  const before = JSON.stringify(state);
  assert.throws(() => Core.updateOrderTransaction(state, state.orders.at(-1).id, { documents: [{ documentId: docId, amountApplied: 500 }], instruments: [] }, 'test'), /instrumentos realizados/);
  assert.equal(JSON.stringify(state), before);
});

