test('291. Migracion V3.1: Swift e IVA no caen como ingreso Agricultura', () => {
  const { buildMigration } = require('./scripts/migration-dry-run');
  const oldState = {
    entities: [{ id: 'ENT-SWIFT', name: 'Swift Argentina', cuit: '' }, { id: 'ENT-ARCA', name: 'ARCA', cuit: '' }],
    accounts: [{ id: 'CTA-AGRI', code: '1', name: 'Ventas', activity: 'Agricultura' }, { id: 'CTA-IMP', code: '2', name: 'IVA', activity: 'Impuestos' }],
    invoices: [],
    settlements: [],
    checks: [],
    stockMovements: [],
    ledger: [],
    orders: [
      { id: 'OLD-SWIFT-SALE', orderNumber: 'OC-2026-0032', type: 'cobro', entityId: 'ENT-SWIFT', accountId: 'CTA-AGRI', activity: 'Agricultura', concept: 'Venta hacienda Swift', amountArs: 66744630, currency: 'ARS', date: '2026-08-01', method: 'cuenta corriente' },
      { id: 'OLD-SWIFT-IVA', orderNumber: 'OC-2026-0033', type: 'cobro', entityId: 'ENT-SWIFT', accountId: 'CTA-IMP', activity: 'Impuestos', concept: 'IVA venta hacienda Swift', amountArs: 7008186.15, currency: 'ARS', date: '2026-08-01', method: 'cuenta corriente' },
      { id: 'OLD-SWIFT-RET', orderNumber: 'OP-2026-0169', type: 'pago', entityId: 'ENT-SWIFT', accountId: 'CTA-IMP', activity: 'Impuestos', concept: 'Retencion ganancias Swift', amountArs: 1330416.63, currency: 'ARS', date: '2026-08-01', method: 'cuenta corriente' },
      { id: 'OLD-IVA-DEV', orderNumber: 'OC-2026-0024', type: 'cobro', entityId: 'ENT-ARCA', accountId: 'CTA-IMP', activity: 'Impuestos', concept: 'Devolucion IVA', amountArs: 1367994.85, currency: 'ARS', date: '2026-07-01', method: 'transferencia', status: 'cobrado' }
    ]
  };
  const { state, report } = buildMigration(oldState);
  assert.equal(report.version, 'V3.1');
  assert(state.documents.some((doc) => doc.number === 'OC-2026-0032' && doc.activity === 'Ganaderia'));
  assert(!state.documents.some((doc) => doc.number === 'OC-2026-0033'));
  assert(!state.documents.some((doc) => doc.number === 'OP-2026-0169'));
  assert.equal(state.taxReimbursements.length, 1);
  assert(report.fiscalCorrections.some((item) => item.orderNumber === 'OC-2026-0033' && item.taxType === 'vat'));
  assert(report.fiscalCorrections.some((item) => item.orderNumber === 'OP-2026-0169' && item.taxType === 'withholding_income_tax'));
  assert.equal(Core.validateState(state).length, 0);
});

