test('302. UX/Flujo: clasificacion visual conserva importes base y drill-down por categoria', () => {
  const { app } = appVmWithFlowDom();
  const rows = [
    { activity: 'Ganaderia', chartPath: 'Ventas', concept: 'Venta hacienda Swift', amount: 66744630, direction: 'in' },
    { activity: 'Ganaderia', chartPath: 'Ventas', concept: 'Venta hacienda Swift sin IVA', amount: 1, direction: 'in' },
    { activity: 'Impuestos', chartPath: 'IVA', concept: 'IVA venta hacienda Swift', amount: 7008186.15, direction: 'in' },
    { activity: 'Impuestos', chartPath: 'Ganancias', concept: 'Retencion ganancias Swift', amount: -1330416.63, direction: 'out' },
    { activity: 'Impuestos', chartPath: 'IVA', concept: 'Devolucion IVA', amount: 1367994.85, direction: 'in' },
    { activity: 'Socios', chartPath: 'Aportes', concept: 'Aporte socios', amount: 2907383, direction: 'in' }
  ];
  const beforeIn = rows.filter((row) => row.amount > 0).reduce((sum, row) => sum + row.amount, 0);
  const beforeOut = rows.filter((row) => row.amount < 0).reduce((sum, row) => sum + Math.abs(row.amount), 0);
  const grouped = new Map();
  rows.forEach((row) => {
    const category = app.flowVisualCategory(row);
    grouped.set(category, [...(grouped.get(category) || []), row]);
  });
  const afterRows = [...grouped.values()].flat();
  const afterIn = afterRows.filter((row) => row.amount > 0).reduce((sum, row) => sum + row.amount, 0);
  const afterOut = afterRows.filter((row) => row.amount < 0).reduce((sum, row) => sum + Math.abs(row.amount), 0);
  assert.equal(afterRows.length, rows.length);
  assert.equal(afterIn, beforeIn);
  assert.equal(afterOut, beforeOut);
  assert.equal(app.flowVisualCategory(rows[0]), 'Ganaderia');
  assert.equal(app.flowVisualCategory(rows[1]), 'Ganaderia');
  assert.equal(app.flowVisualCategory(rows[2]), 'Fiscal');
  assert.equal(app.flowVisualCategory(rows[3]), 'Fiscal');
  assert.equal(app.flowVisualCategory(rows[4]), 'Fiscal');
  assert.equal(app.flowVisualCategory(rows[5]), 'Aportes / Financiamiento');
});

test('303. Hacienda: parser de pesadas calcula limpio y rechaza valores invalidos', () => {
  const { app } = appVmWithPanelDom();
  const weights = app.parseWeightList(' 210  220\n230;240 ');
  assert.deepEqual(weights, [210, 220, 230, 240]);
  assert.equal(weights.length, 4);
  assert.equal(weights.reduce((sum, value) => sum + value, 0), 900);
  assert.equal(Math.min(...weights), 210);
  assert.equal(Math.max(...weights), 240);
  assert.throws(() => app.parseWeightList('210 abc 230'), /Peso invalido/);
});

