testAsync('309. API: transaccion informa tiempos para diagnosticar performance sin cambiar datos', async () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'sagro-api-perf-'));
  const store = new JsonPersistenceAdapter({ root, environment: 'demo', Core });
  const loaded = store.loadState();
  const body = JSON.stringify({ action: 'createEntity', stateVersion: loaded.stateVersion, payload: { name: 'Performance Demo', role: 'Proveedor' } });
  const req = Readable.from([body]);
  req.method = 'POST';
  req.url = '/api/transaction';
  req.headers = {};
  const chunks = [];
  const res = {
    writeHead(status, headers) { this.status = status; this.headers = headers; },
    end(chunk) { if (chunk) chunks.push(Buffer.from(chunk)); }
  };
  await handleApi(req, res, store, { required: false });
  const response = JSON.parse(Buffer.concat(chunks).toString('utf8'));
  assert.equal(response.ok, true);
  assert.equal(response.performance.action, 'createEntity');
  assert(Number.isFinite(response.performance.transactionMs));
  assert(Number.isFinite(response.performance.persistMs));
  assert.equal(response.performance.modifiedCollections >= 1, true);
  assert.equal(response.performance.modifiedRecords >= 1, true);
});

testAsync('API local: devuelve el ID exacto creado, sin inferirlo por posición', async () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'sagro-created-id-'));
  const store = new JsonPersistenceAdapter({ root, environment: 'demo', Core });
  const initial = store.loadState();
  const result = await callApiForTest({ method: 'POST', url: '/api/transaction', persistence: store, auth: { required: false }, body: {
    action: 'createEntity', stateVersion: initial.stateVersion, payload: { name: 'Entidad ID exacto', role: 'Proveedor' }
  } });
  assert.equal(result.status, 200);
  assert.equal(result.payload.createdIds.entities.length, 1);
  const id = result.payload.createdIds.entities[0];
  assert(result.payload.state.entities.some((item) => item.id === id && item.name === 'Entidad ID exacto'));
  assert.equal(store.loadState().state.entities.filter((item) => item.id === id).length, 1);
});

