test('Debito en cuenta: usa cuenta bancaria, aparece en Flujo y afecta banco solo al realizarse', () => {
  let state = fresh();
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', commercialSide: 'purchase', fiscalStatus: 'documented', entityId: 'ENT-PROV-AGRI', number: 'DB-1', amount: 800, currency: 'ARS', issueDate: '2026-09-01', dueDate: '2026-09-20', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS', description: 'Debito automatico' }, 'test');
  const documentId = state.documents.at(-1).id;
  const opening = Core.accountBalances(state).find((item) => item.id === 'ACC-GALICIA-ARS').realBalance;
  state = Core.createOrderTransaction(state, { type: 'payment', documentId, amountApplied: 800, instruments: [{ type: 'account_debit', amount: 800, financialAccountId: 'ACC-GALICIA-ARS', scheduledDate: '2026-09-20', status: 'scheduled', reference: 'DEB-AUTO', notes: 'Servicio' }] }, 'test');
  const instrument = state.instruments.at(-1);
  assert.equal(Core.labelForType(instrument.type), 'Debito en cuenta');
  assert.equal(Core.accountBalances(state).find((item) => item.id === 'ACC-GALICIA-ARS').realBalance, opening);
  const pending = Core.flowRows(state).find((item) => item.instrumentId === instrument.id);
  assert.equal(pending.userStatus, 'Pendiente');
  state = Core.transitionInstrument(state, instrument.id, 'executed', '2026-09-20', 'test');
  assert.equal(Core.accountBalances(state).find((item) => item.id === 'ACC-GALICIA-ARS').realBalance, opening - 800);
  assert.equal(Core.flowRows(state).find((item) => item.instrumentId === instrument.id).userStatus, 'Pagado');
  assert.equal(Core.validateState(state).length, 0);
  let invalid = fresh();
  invalid = Core.createDocumentTransaction(invalid, { type: 'purchase_invoice', fiscalStatus: 'documented', entityId: 'ENT-PROV-AGRI', number: 'DB-CAJA', amount: 50, currency: 'ARS', issueDate: '2026-09-01', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS' }, 'test');
  const invalidDocumentId = invalid.documents.at(-1).id;
  assert.throws(() => Core.createOrderTransaction(invalid, { type: 'payment', documentId: invalidDocumentId, amountApplied: 50, instruments: [{ type: 'account_debit', amount: 50, financialAccountId: 'ACC-CAJA-ARS', scheduledDate: '2026-09-20', status: 'scheduled' }] }, 'test'), /requiere una cuenta bancaria/);
});

test('Contrapartes: preview y fusion reasignan referencias atomicamente y preservan operaciones', () => {
  let state = fresh();
  state = Core.createEntityTransaction(state, { id: 'ENT-DESTINO-MERGE', name: 'Destino Merge', role: 'Proveedor' }, 'test');
  const sourceId = 'ENT-PROV-AGRI';
  const targetId = 'ENT-DESTINO-MERGE';
  const preview = Core.entityMergePreview(state, sourceId, targetId);
  assert(preview.total > 0);
  assert.equal(preview.ambiguous.length, 0);
  const ids = {
    documents: state.documents.map((item) => item.id), orders: state.orders.map((item) => item.id),
    instruments: state.instruments.map((item) => item.id), settlements: state.orderDocumentSettlements.map((item) => item.id)
  };
  const amounts = state.documents.map((item) => item.amount);
  state = Core.mergeEntitiesTransaction(state, sourceId, targetId, 'Entidad duplicada', 'tester');
  assert.equal(state.entities.find((item) => item.id === sourceId).active, false);
  assert.equal(state.entities.find((item) => item.id === sourceId).mergedIntoEntityId, targetId);
  assert(!state.documents.some((item) => item.entityId === sourceId));
  assert(!state.orders.some((item) => item.entityId === sourceId));
  assert(!state.instruments.some((item) => item.entityId === sourceId));
  assert.deepEqual(state.documents.map((item) => item.id), ids.documents);
  assert.deepEqual(state.orders.map((item) => item.id), ids.orders);
  assert.deepEqual(state.instruments.map((item) => item.id), ids.instruments);
  assert.deepEqual(state.orderDocumentSettlements.map((item) => item.id), ids.settlements);
  assert.deepEqual(state.documents.map((item) => item.amount), amounts);
  const audit = state.auditLog.find((item) => item.action === 'merge-entities');
  assert.equal(audit.user, 'tester');
  assert.equal(audit.reason, 'Entidad duplicada');
  assert.equal(Core.validateState(state).length, 0);
});

