testAsync('318. API: metricas funcionan con Firestore adapter en memoria sin exponer payload', async () => {
  const gateway = new MemoryFirestoreGateway();
  const store = new FirestorePersistenceAdapter({ environment: 'demo', Core, gateway });
  const loaded = store.loadState();
  const body = JSON.stringify({ action: 'createEntity', stateVersion: loaded.stateVersion, payload: { name: 'Perf Firestore', role: 'Proveedor' } });
  const req = Readable.from([body]);
  req.method = 'POST';
  req.url = '/api/transaction';
  req.headers = {};
  const chunks = [];
  const res = {
    writeHead(status, headers) { this.status = status; this.headers = headers; },
    end(chunk) { if (chunk) chunks.push(Buffer.from(chunk)); }
  };
  await handleApi(req, res, store, { required: false });
  const response = JSON.parse(Buffer.concat(chunks).toString('utf8'));
  assert.equal(response.ok, true);
  assert.equal(response.performance.action, 'createEntity');
  assert(response.performance.writesFirestore >= 1);
  assert.equal(response.performance.deletesFirestore, 0);
  assert.equal(JSON.stringify(response.performance).includes('Perf Firestore'), false);
});

test('319. Firestore performance: una modificacion simple persiste solo registro y meta', () => {
  const gateway = new MemoryFirestoreGateway();
  const store = firestoreAdapter(gateway);
  const loaded = store.loadState();
  gateway.writeLog = [];
  const next = JSON.parse(JSON.stringify(loaded.state));
  next.orders[0] = { ...next.orders[0], notes: 'Solo orden modificada' };
  const saved = store.saveState(next, { expectedVersion: loaded.stateVersion, currentRecord: loaded, label: 'single-order' });
  const setPaths = gateway.writeLog.filter((entry) => entry.action === 'set').map((entry) => entry.path);
  assert.equal(saved.stateVersion, loaded.stateVersion + 1);
  assert.equal(setPaths.length, 2);
  assert(setPaths.some((path) => path.endsWith(`/collections/orders/records/${encodeURIComponent(next.orders[0].id)}`)));
  assert.equal(setPaths.filter((path) => path === 'sagroAdminStates/demo/meta/current').length, 1);
  assert.equal(store.lastWriteStats.writes, 2);
  assert.equal(store.lastWriteStats.deletes, 0);
  assert.equal(store.lastWriteStats.batches, 1);
  assert.equal(store.lastWriteStats.postPersistReadMs, 0);
});

