test('Firestore cache: primer acceso reconstruye y segundo acceso lee solo meta', () => {
  const gateway = new MemoryFirestoreGateway();
  firestoreAdapter(gateway).loadState();
  const store = firestoreAdapter(gateway);
  gateway.readLog = [];
  const first = store.loadState();
  const readsBefore = store.lastReadStats.docsRead;
  assert(readsBefore > 100);
  assert.equal(store.lastReadStats.cacheMiss, true);
  assert.equal(Core.validateState(first.state).length, 0);
  gateway.readLog = [];
  const second = store.loadState();
  assert.equal(second.stateVersion, first.stateVersion);
  assert.equal(store.lastReadStats.docsRead, 1);
  assert.equal(store.lastReadStats.cacheHit, true);
  assert.equal(store.lastReadStats.fullReadsAvoided, 1);
  assert.deepEqual(gateway.readLog.map((entry) => entry.action), ['get']);
});

test('Firestore cache: escritura exitosa actualiza cache y dos guardados no reconstruyen colecciones', () => {
  const gateway = new MemoryFirestoreGateway();
  const store = firestoreAdapter(gateway);
  const first = store.loadState();
  const next = cloneForTest(first.state);
  next.orders[0] = { ...next.orders[0], notes: 'Cache write 1' };
  const saved = store.saveState(next, { expectedVersion: first.stateVersion, currentRecord: first });
  gateway.readLog = [];
  const cached = store.loadState();
  assert.equal(cached.stateVersion, saved.stateVersion);
  assert.equal(store.lastReadStats.cacheHit, true);
  assert.equal(gateway.readLog.filter((entry) => entry.action === 'list').length, 0);
  const nextAgain = cloneForTest(cached.state);
  nextAgain.orders[0] = { ...nextAgain.orders[0], notes: 'Cache write 2' };
  gateway.readLog = [];
  const savedAgain = store.saveState(nextAgain, { expectedVersion: cached.stateVersion });
  assert.equal(savedAgain.stateVersion, saved.stateVersion + 1);
  assert.equal(gateway.readLog.filter((entry) => /list/.test(entry.action)).length, 0);
  assert.equal(gateway.readLog.filter((entry) => /get/.test(entry.action)).length, 2);
});

test('Firestore cache: otra instancia invalida y reconstruye el estado remoto', () => {
  const gateway = new MemoryFirestoreGateway();
  const firstStore = firestoreAdapter(gateway);
  const secondStore = firestoreAdapter(gateway);
  const first = firstStore.loadState();
  secondStore.loadState();
  const changed = cloneForTest(first.state);
  changed.orders[0] = { ...changed.orders[0], notes: 'Cambio de otra instancia' };
  const saved = firstStore.saveState(changed, { expectedVersion: first.stateVersion, currentRecord: first });
  const observed = secondStore.loadState();
  assert.equal(observed.stateVersion, saved.stateVersion);
  assert.equal(observed.state.orders[0].notes, 'Cambio de otra instancia');
  assert.equal(secondStore.lastReadStats.cacheInvalidated, true);
  assert(secondStore.lastReadStats.docsRead > 100);
});

test('Firestore cache: conflicto entre prelectura y commit invalida sin adelantar cache', () => {
  class RacingGateway extends MemoryFirestoreGateway {
    runTransaction(fn) {
      if (this.bumpVersionOnNextTransaction) {
        const path = 'sagroAdminStates/demo/meta/current';
        const meta = this.docs.get(path);
        this.docs.set(path, { ...meta, stateVersion: Number(meta.stateVersion) + 1 });
        this.bumpVersionOnNextTransaction = false;
      }
      return super.runTransaction(fn);
    }
  }
  const gateway = new RacingGateway();
  const store = firestoreAdapter(gateway);
  const loaded = store.loadState();
  const changed = cloneForTest(loaded.state);
  changed.orders[0] = { ...changed.orders[0], notes: 'No debe persistir' };
  gateway.bumpVersionOnNextTransaction = true;
  assert.throws(() => store.saveState(changed, { expectedVersion: loaded.stateVersion, currentRecord: loaded }), /base cambio/i);
  assert.equal(store.cachedRecord, null);
  assert.notEqual(gateway.getDoc(`sagroAdminStates/demo/collections/orders/records/${encodeURIComponent(changed.orders[0].id)}`).value.notes, 'No debe persistir');
});

test('Firestore cache: error de persistencia no adelanta version ni conserva cache', () => {
  const gateway = new MemoryFirestoreGateway();
  const store = firestoreAdapter(gateway);
  const loaded = store.loadState();
  const changed = cloneForTest(loaded.state);
  changed.entities.push({ id: 'ENT-CACHE-FAIL', name: 'Cache fail', type: 'supplier', role: 'Proveedor', cuit: '', active: true, suggestedActivity: '', suggestedChartAccountId: '' });
  gateway.failOnSetPath = 'ENT-CACHE-FAIL';
  assert.throws(() => store.saveState(changed, { expectedVersion: loaded.stateVersion, currentRecord: loaded }), /Firestore write simulado/);
  assert.equal(store.cachedRecord, null);
  gateway.failOnSetPath = '';
  const reread = store.loadState();
  assert.equal(reread.stateVersion, loaded.stateVersion);
  assert.equal(reread.state.entities.some((item) => item.id === 'ENT-CACHE-FAIL'), false);
});

test('Firestore cache: restore e import invalidan y reinicio sin cache reconstruye', () => {
  const gateway = new MemoryFirestoreGateway();
  const store = firestoreAdapter(gateway);
  const loaded = store.loadState();
  const backup = store.createBackup('cache-restore');
  const changed = cloneForTest(loaded.state);
  changed.entities.push({ id: 'ENT-CACHE-RESTORE', name: 'Cache restore', type: 'supplier', role: 'Proveedor', cuit: '', active: true, suggestedActivity: '', suggestedChartAccountId: '' });
  store.saveState(changed, { expectedVersion: loaded.stateVersion, currentRecord: loaded });
  const invalidationsBefore = store.cacheMetrics.invalidations;
  const restored = store.restoreBackup(backup);
  assert.equal(restored.state.entities.some((item) => item.id === 'ENT-CACHE-RESTORE'), false);
  assert(store.cacheMetrics.invalidations > invalidationsBefore);
  const restarted = firestoreAdapter(gateway);
  restarted.loadState();
  assert.equal(restarted.lastReadStats.cacheMiss, true);
  assert(restarted.lastReadStats.docsRead > 100);
  const importer = fs.readFileSync(path.join(__dirname, 'scripts', 'import-legacy-demo.js'), 'utf8');
  assert(importer.includes("invalidateCache('legacy-import')"));
});

testAsync('Firestore cache: API normal reduce lecturas completas y expone metricas', async () => {
  const gateway = new MemoryFirestoreGateway();
  const store = firestoreAdapter(gateway);
  const loaded = store.loadState();
  const beforeReads = store.lastReadStats.docsRead;
  const response = await callApiForTest({
    method: 'POST',
    url: '/api/transaction',
    body: { action: 'createEntity', stateVersion: loaded.stateVersion, payload: { name: 'Cache API', role: 'Proveedor' } },
    persistence: store,
    auth: { required: false }
  });
  assert.equal(response.status, 200);
  assert.equal(response.payload.performance.cacheHit, true);
  assert.equal(response.payload.performance.fullReadsAvoided, 1);
  assert.equal(response.payload.performance.docsRead, 2);
  assert(beforeReads > response.payload.performance.docsRead);
});

testAsync('Servidor resiliente: startup no lee Firestore y cuota responde 503 sin fallback ni escritura', async () => {
  let reads = 0;
  let writes = 0;
  let available = false;
  const real = fresh();
  const persistence = {
    environment: 'demo',
    sourceOfTruth: 'test/firestore/demo',
    async loadStateAsync() {
      reads += 1;
      if (!available) {
        const error = new Error('8 RESOURCE_EXHAUSTED: Quota exceeded.');
        error.code = 8;
        throw error;
      }
      return { schemaVersion: 1, stateVersion: 9, updatedAt: '', state: cloneForTest(real), environment: 'demo', sourceOfTruth: this.sourceOfTruth };
    },
    async saveStateAsync() { writes += 1; throw new Error('No deberia escribir'); }
  };
  const server = createServer(persistence);
  assert(server);
  assert.equal(reads, 0);
  const unavailableRead = await callApiForTest({ persistence, auth: { required: false } });
  assert.equal(unavailableRead.status, 503);
  assert.equal(unavailableRead.payload.unavailable, true);
  assert.equal('state' in unavailableRead.payload, false);
  assert.equal(reads, 1);
  const unavailableWrite = await callApiForTest({ method: 'POST', url: '/api/transaction', body: { action: 'createEntity', stateVersion: 9, payload: { name: 'No escribir', role: 'Proveedor' } }, persistence, auth: { required: false } });
  assert.equal(unavailableWrite.status, 503);
  assert.equal(writes, 0);
  assert.equal(reads, 2);
  available = true;
  const recovered = await callApiForTest({ persistence, auth: { required: false } });
  assert.equal(recovered.status, 200);
  assert.equal(recovered.payload.stateVersion, 9);
  assert.equal(reads, 3);
});

