test('Compra de hacienda suma cargos visibles y reconcilia documento OP y Flujo', () => {
  let state = livestockBaseState();
  const payload = {
    type: 'purchase', date: '2026-09-01', herdId: 'LH-TERNEROS', locationId: 'LL-CAMPO', category: 'Ternero',
    heads: 31, totalKg: 6219, pricePerKg: 6059.66, currency: 'ARS', counterpartyEntityId: 'ENT-PROV-AGRI',
    chartAccountId: 'CA-GAN', netTaxedAmount: 37685025.54, vatRate: 10.5, vatAmount: 3956927.68,
    commissionPercent: 4, commissions: 1507401.02, commissionVat: 316554.21, guides: 9760, totalAmount: 43475668.45
  };
  assert.equal(Core.calculateLivestockTradeBreakdown(payload).amount, 43475668.45);
  state = Core.createLivestockTradeTransaction(state, payload, 'test');
  const trade = state.livestockTrades.at(-1);
  const doc = state.documents.find((item) => item.id === trade.documentId);
  assert.equal(trade.amount, 43475668.45);
  assert.equal(trade.totalAmount, 43475668.45);
  assert.equal(doc.amount, 43475668.45);
  assert.equal(doc.economicAmount, 37685025.54);
  assert(doc.taxComponents.some((item) => item.taxType === 'commission' && item.effect === 'add'));
  assert(doc.taxComponents.some((item) => item.taxType === 'commission_vat' && item.effect === 'add'));
  assert(doc.taxComponents.some((item) => item.taxType === 'guide_fee' && item.effect === 'add'));
  assert.equal(Core.documentBreakdown(state, doc.id).nonInstrumented, 43475668.45);
  state = Core.createOrderTransaction(state, { type: 'payment', documentId: doc.id, amountApplied: doc.amount, financialAccountId: 'ACC-GALICIA-ARS', instruments: [{ type: 'transfer', amount: doc.amount, scheduledDate: '2026-09-30', status: 'scheduled' }] }, 'test');
  assert.equal(Core.orderBreakdown(state, state.orders.at(-1).id).applied, 43475668.45);
  assert.equal(Core.flowRows(state).find((row) => row.documentId === doc.id && row.instrumentId === state.instruments.at(-1).id).amount, -43475668.45);
  assert.equal(Core.validateState(state).length, 0);
});

test('Compra de hacienda diferencia gastos adicionales y retenciones y rechaza total inconciliable', () => {
  const payload = { type: 'purchase', totalKg: 100, pricePerKg: 100, netTaxedAmount: 10000, vatAmount: 1050,
    commissions: 400, commissionVat: 84, guides: 20, senasa: 30, controlDelivery: 40, bath: 10,
    adminExpenses: 50, otherExpenses: 60, withholdingVat: 100, withholdingIncomeTax: 200, withholdingIibb: 25, otherDeductions: 15 };
  const breakdown = Core.calculateLivestockTradeBreakdown(payload);
  assert.equal(breakdown.amount, 11404);
  assert(breakdown.taxComponents.some((item) => item.taxType === 'other' && item.effect === 'add'));
  assert(breakdown.taxComponents.some((item) => item.taxType === 'other' && item.effect === 'subtract'));
  assert(breakdown.taxComponents.some((item) => item.taxType === 'withholding_income_tax' && item.effect === 'subtract'));
  const state = livestockBaseState();
  const trade = { ...payload, date: '2026-09-01', herdId: 'LH-TERNEROS', locationId: 'LL-CAMPO', category: 'Ternero', heads: 2, currency: 'ARS', counterpartyEntityId: 'ENT-PROV-AGRI', chartAccountId: 'CA-GAN' };
  assert.throws(() => Core.createLivestockTradeTransaction(state, { ...trade, totalAmount: 11000 }, 'test'), /no reconcilia con sus componentes/);
  assert.equal(state.livestockTrades.length, 0);
  const created = Core.createLivestockTradeTransaction(state, { ...trade, totalAmount: breakdown.amount }, 'test');
  assert.equal(created.documents.at(-1).amount, breakdown.amount);
  assert.equal(created.livestockTrades.at(-1).otherExpenses, 60);
  assert.equal(created.livestockTrades.at(-1).otherDeductions, 15);
  assert.equal(Core.validateState(created).length, 0);
});

