test('341. Cartera de valores: cheque recibido entra a cartera y puede depositarse conservando identidad', () => {
  let state = fresh();
  const bankBefore = Core.accountBalances(state).find((account) => account.id === 'ACC-GALICIA-ARS').realBalance;
  state = Core.createDocumentTransaction(state, { type: 'sale_invoice', commercialSide: 'sale', entityId: 'ENT-CLIENTE-DEMO', number: 'VENTA-CARTERA-ID', amount: 2000, currency: 'ARS', issueDate: '2026-09-01', dueDate: '2026-09-10', activity: 'Agricultura', chartAccountId: 'CA-AGRI', description: 'Cheque recibido cartera' }, 'test');
  const docId = state.documents.at(-1).id;
  state = Core.createOrderTransaction(state, { type: 'collection', documentId: docId, amountApplied: 2000, financialAccountId: 'ACC-GALICIA-ARS', instruments: [{ type: 'received_check', amount: 2000, scheduledDate: '2026-09-20', status: 'inPortfolio', reference: 'RC-ID', checkNumber: 'RC-ID' }] }, 'test');
  const checkId = state.instruments.at(-1).id;
  assert.equal(Core.receivedCheckPortfolio(state, { currency: 'ARS' }).some((item) => item.id === checkId), true);
  state = Core.transitionInstrument(state, checkId, 'deposited', '2026-09-21', 'test');
  assert.equal(state.instruments.find((item) => item.id === checkId).status, 'deposited');
  assert.equal(Core.receivedCheckPortfolio(state, { currency: 'ARS' }).some((item) => item.id === checkId), true);
  state = Core.transitionInstrument(state, checkId, 'accredited', '2026-09-25', 'test');
  assert.equal(state.instruments.find((item) => item.id === checkId).id, checkId);
  assert.equal(Core.receivedCheckPortfolio(state, { currency: 'ARS' }).some((item) => item.id === checkId), false);
  assert.equal(Core.accountBalances(state).find((account) => account.id === 'ACC-GALICIA-ARS').realBalance, bankBefore + 2000);
});

test('342. Cartera de valores: entregar cheque recibido a proveedor conserva instrumento y no crea salida bancaria', () => {
  let state = emptyState();
  state = Core.createDocumentTransaction(state, { type: 'sale_invoice', commercialSide: 'sale', entityId: 'ENT-CLIENTE-DEMO', number: 'VENTA-ENDOSO-ID', amount: 3000, currency: 'ARS', issueDate: '2026-09-01', dueDate: '2026-09-01', activity: 'Agricultura', chartAccountId: 'CA-AGRI', description: 'Cobro con cheque' }, 'test');
  const saleId = state.documents.at(-1).id;
  state = Core.createOrderTransaction(state, { type: 'collection', documentId: saleId, amountApplied: 3000, financialAccountId: 'ACC-GALICIA-ARS', instruments: [{ type: 'received_check', amount: 3000, scheduledDate: '2026-09-30', status: 'inPortfolio', reference: 'RC-END', checkNumber: 'RC-END' }] }, 'test');
  const checkId = state.instruments.at(-1).id;
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', commercialSide: 'purchase', entityId: 'ENT-PROV-AGRI', number: 'COMPRA-ENDOSO-ID', amount: 3000, currency: 'ARS', issueDate: '2026-09-02', dueDate: '2026-09-02', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS', description: 'Pago con cheque de tercero' }, 'test');
  const debtId = state.documents.at(-1).id;
  state.instruments.find((item) => item.id === checkId).status = 'endorsed';
  state.instruments.find((item) => item.id === checkId).deliveredToEntityId = 'ENT-PROV-AGRI';
  const orderId = 'OP-ENDOSO-ID';
  const orderDocument = { id: 'OD-ENDOSO-ID', orderId, documentId: debtId, amountApplied: 3000, currency: 'ARS', voidedAt: null };
  const orderInstrument = { id: 'OI-ENDOSO-ID', orderId, instrumentId: checkId, amount: 3000, currency: 'ARS', voidedAt: null };
  state.orders.push({ id: orderId, type: 'payment', entityId: 'ENT-PROV-AGRI', date: '2026-09-02', description: 'Endoso cheque tercero', activity: 'Agricultura', currency: 'ARS', voidedAt: null });
  state.orderDocuments.push(orderDocument);
  state.orderInstruments.push(orderInstrument);
  state.orderDocumentSettlements.push({ id: 'ODS-ENDOSO-ID', orderDocumentId: orderDocument.id, orderInstrumentId: orderInstrument.id, amount: 3000, currency: 'ARS', voidedAt: null });
  assert.equal(state.instruments.filter((item) => item.id === checkId).length, 1);
  assert.equal(Core.currentAccountRows(state, { entityId: 'ENT-PROV-AGRI', currency: 'ARS' }).at(-1).balance, 0);
  assert.equal(Core.accountBalances(state).find((account) => account.id === 'ACC-GALICIA-ARS').realBalance, 25000000);
  assert.equal(Core.validateState(state).length, 0);
});

