test('Diagnostico documento: usa el estado cargado y coincide con documentBreakdown y flowRows sin modificarlo', () => {
  const state = financedLarDocumentState();
  const { app } = appVmWithFlowDom();
  app.setTestState(state, []);
  const before = JSON.stringify(state);
  const doc = state.documents[0];
  const data = app.documentFinancialDiagnostics(doc.id);
  const b = Core.documentBreakdown(state, doc.id, data.asOfDate);
  assert.equal(data.documentId, doc.id);
  assert.equal(data.total, 3671.52);
  assert.equal(data.currency, 'USD');
  assert.equal(data.commercialBalance, doc.amount - b.cancelled);
  assert.equal(data.applied, b.assigned);
  assert.equal(data.cancelled, b.cancelled);
  assert.equal(data.financialRealized, b.financialRealized);
  assert.equal(data.committedPending, b.committedPending);
  assert.equal(data.nonInstrumented, b.nonInstrumented);
  assert.equal(data.instrumented, 0);
  assert.equal(data.dueDate, '2026-12-20');
  assert.equal(data.issueDate, '2026-06-01');
  assert.equal(data.commercialSide, 'purchase');
  assert.equal(data.direction, 'out');
  assert.equal(data.status, b.status);
  assert(data.projectionIncluded);
  assert(data.projectionReason.includes('Core.flowRows() genera document-balance'));
  const expected = Core.flowRows(state, { asOfDate: data.asOfDate }).filter((row) => row.documentId === doc.id && row.source === 'document-balance');
  assert.deepEqual(cloneForTest(data.projections), expected.map(({ id, date, amount, currency, direction, userStatus, source }) => ({ id, date, amount, currency, direction, userStatus, source })));
  assert.deepEqual(cloneForTest(data.breakdownDetails), b.details);
  assert.equal(data.orderDocuments.length, 0);
  assert.equal(data.instruments.length, 0);
  assert.equal(app.documentFinancialDiagnostics('INEXISTENTE'), null);
  assert.equal(JSON.stringify(state), before);
  assert.equal(Core.validateState(state).length, 0);
});

