test('Diagnostico documento: muestra relaciones historicas anuladas y explica que Core no las cuenta', () => {
  for (const collection of ['orders', 'orderDocuments', 'orderInstruments', 'instruments', 'orderDocumentSettlements']) {
    let state = financedLarDocumentState();
    const doc = state.documents[0];
    state = Core.createOrderTransaction(state, { type: 'payment', documentId: doc.id, amountApplied: doc.amount, financialAccountId: 'ACC-TEST-USD', instruments: [{ type: 'transfer', amount: doc.amount, scheduledDate: doc.dueDate, status: 'scheduled', reference: 'TR-LEGACY' }] }, 'test');
    state[collection][0].voidedAt = '2026-09-28T12:00:00.000Z';
    if (collection === 'orderDocuments') {
      state.orders[0].voidedAt = '2026-09-28T12:00:00.000Z';
      state.orderInstruments[0].voidedAt = '2026-09-28T12:00:00.000Z';
    }
    const { app } = appVmWithFlowDom();
    app.setTestState(state, []);
    const before = JSON.stringify(state);
    const data = app.documentFinancialDiagnostics(doc.id);
    const b = Core.documentBreakdown(state, doc.id);
    assert(data.projectionIncluded, collection);
    assert.equal(data.nonInstrumented, b.nonInstrumented);
    assert.equal(data.nonInstrumented, doc.amount);
    assert.equal(data.instrumented, 0);
    assert.equal(data.orderDocuments[0].id, state.orderDocuments[0].id);
    assert.equal(data.orderDocuments[0].orderId, state.orders[0].id);
    assert.equal(data.orderDocuments[0].orderNumber, Core.orderDisplayCode(state, state.orders[0]));
    assert.equal(data.orderDocuments[0].countedInApplied, !['orders', 'orderDocuments'].includes(collection));
    assert.equal(data.settlements[0].id, state.orderDocumentSettlements[0].id);
    assert.equal(data.settlements[0].status, state.orderDocumentSettlements[0].status);
    assert.equal(data.settlements[0].linkStatus, collection === 'orderDocumentSettlements' ? 'Anulado' : 'No anulado');
    assert.equal(data.settlements[0].countedInBreakdown, false);
    assert.equal(data.instruments[0].id, state.instruments[0].id);
    assert.equal(data.instruments[0].status, 'scheduled');
    assert.equal(data.orderInstruments[0].id, state.orderInstruments[0].id);
    if (collection === 'orders') assert(data.orderDocuments[0].orderStatus.startsWith('Anulada'));
    assert.equal(JSON.stringify(state), before, collection);
    assert.equal(Core.validateState(state).length, 0, collection);
  }
});

