  state = Core.createOrderTransaction(state, { type: 'payment', documentId: doc.id, amountApplied: 1000, financialAccountId: 'ACC-TEST-USD', instruments: [{ type: 'transfer', amount: 900, scheduledDate: '2026-09-20', status: 'executed' }], practicedWithholdings: [{ taxType: 'withholding_income_tax', amount: 100, date: '2026-09-20', reference: 'RET-LOCAL' }] }, 'test');
