test('Flujo multimoneda: resumen y pie suman por moneda y respetan filtros de encabezado', () => {
  const state = mixedFlowCurrencyState();
  const { app, elements } = appVmWithFlowDom();
  app.setTestState(state, []);
  const totals = app.flowCurrencyTotals(Core.flowRows(state), '');
  assert.deepEqual(cloneForTest(totals), [
    { currency: 'ARS', incomes: 300000, expenses: 100000, net: 200000 },
    { currency: 'USD', incomes: 1000, expenses: 3671.52, net: -2671.52 }
  ]);
  app.renderFlow();
  const summary = elements.get('flowTotals');
  assert.equal(summary.children.length, 2);
  const ars = summary.children[0];
  const usd = summary.children[1];
  assert(textTree(ars).includes('Total ingresos ARS$ 300.000,00'));
  assert(textTree(ars).includes('Total egresos ARS$ 100.000,00'));
  assert(textTree(ars).includes('Saldo ARS$ 200.000,00'));
  assert(!textTree(ars).includes('US$'));
  assert(textTree(usd).includes('Saldo USDUS$ -2.671,52'));
  const footer = elements.get('flowTable').tFoot;
  assert.equal(footer.children.length, 2);
  assert(textTree(footer.children[0]).includes('TOTAL ARS'));
  assert(textTree(footer.children[1]).includes('TOTAL USD'));
  const filtered = appVmWithFlowDom();
  filtered.app.setTestState(state, []);
  filtered.app.tableFilters.flowTable = { 0: { from: '2026-12-01', to: '2026-12-31' } };
  filtered.app.renderFlow();
  assert.equal(filtered.elements.get('flowTable').tBody.children.length, 3);
  const arsFiltered = filtered.elements.get('flowTotals').children[0];
  assert(textTree(arsFiltered).includes('Total egresos ARS$ 0,00'));
  assert(textTree(arsFiltered).includes('Saldo ARS$ 300.000,00'));
});

test('Flujo multimoneda: matriz calcula cada moneda por separado con sus saldos bancarios y conserva datos', () => {
  const state = mixedFlowCurrencyState();
  const before = JSON.stringify(state);
  const { app } = appVmWithFlowDom();
  app.setTestState(state, []);
  const options = { currency: '', from: '2026-09-01', horizon: 6 };
  const groups = app.flowMonthlyCurrencyGroups(options);
  assert.deepEqual(cloneForTest(groups.map((group) => group.currency)), ['ARS', 'USD']);
  for (const group of groups) {
    assert.deepEqual(cloneForTest(group.months), Core.monthlyFlow(state, { ...options, currency: group.currency }));
    assert(group.months.every((month) => month.rows.every((row) => row.currency === group.currency)));
  }
  const ars = groups[0].months.find((month) => month.month === '2026-12');
  const usd = groups[1].months.find((month) => month.month === '2026-12');
  assert.equal(ars.incomes, 300000);
  assert.equal(ars.expenses, 0);
  assert.equal(usd.incomes, 1000);
  assert.equal(usd.expenses, 3671.52);
  assert.equal(usd.net, -2671.52);
  assert.equal(JSON.stringify(state), before);
});

