test('Matriz unica: ingresos, egresos, neto, acumulado y totales mantienen cifras independientes en la misma celda', () => {
  const state = mixedFlowCurrencyState();
  state.documents.find((doc) => doc.number === 'PRUEBA-ARS-COMPRA').dueDate = '2026-12-20';
  const { app, elements } = appVmWithFlowDom();
  app.setTestState(state, []);
  elements.get('monthlyHorizon').value = '6';
  const before = JSON.stringify(state);
  app.renderMonthly();
  const table = findNodes(elements.get('monthlyFlow'), (node) => node.className === 'monthly-matrix')[0];
  assert.equal(table.tHead.children[0].children.length, 8);
  for (const [label, field] of [['INGRESOS', 'incomes'], ['TOTAL INGRESOS', 'incomes'], ['EGRESOS', 'expenses'], ['TOTAL EGRESOS', 'expenses'], ['NETO DEL MES', 'net'], ['SALDO ACUMULADO', 'accumulated']]) {
    const row = table.tBody.children.find((item) => textTree(item.children[0]) === label);
    assert(row, label);
    const cell = row.children[4];
    assert.equal(cell.children.length, 2, label);
    for (const currency of ['ARS', 'USD']) {
      const expected = Core.monthlyFlow(state, { currency, from: '2026-09-01', horizon: 6 }).find((month) => month.month === '2026-12');
      const line = cell.children.find((item) => item.dataset.currency === currency);
      assert(line, `${label} ${currency}`);
      assert.equal(textTree(line), `${currency}${app.formatFlowMoney(expected[field], currency)}`);
    }
  }
  const arsOnlyNovember = table.tBody.children.find((item) => textTree(item.children[0]) === 'SALDO ACUMULADO').children[3];
  assert(arsOnlyNovember.children.every((line) => line.dataset.currency === 'ARS'));
  assert.equal(JSON.stringify(state), before);
  assert.equal(Core.validateState(state).length, 0);
});

