test('Flujo: documentos emitidos en junio se proyectan en diciembre, marzo y mayo segun vencimiento', () => {
  let state = fresh();
  for (const [number, dueDate] of [['FAC-DIC', '2026-12-20'], ['FAC-MAR', '2027-03-15'], ['FAC-MAY', '2027-05-10']]) {
    state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', commercialSide: 'purchase', entityId: 'ENT-PROV-AGRI', number, amount: 1000, currency: 'ARS', issueDate: '2026-06-01', dueDate, activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS', description: 'Compra financiada' }, 'test');
  }
  const ids = state.documents.slice(-3).map((doc) => doc.id);
  const rows = Core.flowRows(state, { asOfDate: '2026-09-25' });
  ids.forEach((id, index) => {
    const matching = rows.filter((row) => row.documentId === id);
    assert.equal(matching.length, 1);
    assert.equal(matching[0].source, 'document-balance');
    assert.equal(matching[0].date, ['2026-12-20', '2027-03-15', '2027-05-10'][index]);
  });
  const months = Core.monthlyFlow(state, { from: '2026-06-01', horizon: 12, currency: 'ARS' });
  for (const month of ['2026-12', '2027-03', '2027-05']) {
    assert.equal(months.find((item) => item.month === month).rows.filter((row) => ids.includes(row.documentId)).length, 1);
  }
  assert.equal(months.find((item) => item.month === '2026-06').rows.filter((row) => ids.includes(row.documentId)).length, 0);
  assert.equal(Core.validateState(state).length, 0);
});

