test('Planes: persistencia incremental en memoria, recarga, backup y restore', () => {
  const state=Core.taxPaymentPlanTransaction(arcaSyntheticState(),taxPlanSyntheticPayload(),'test');
  const gateway=new MemoryFirestoreGateway(), persistence=firestoreAdapter(gateway);
  persistence.writeValidated(state,1); const loaded=persistence.loadState().state;
  assert.deepEqual(loaded.taxPaymentPlans,state.taxPaymentPlans);
  const store=adapter(tempPersistenceRoot()),initial=store.loadState(); store.saveState(state,{expectedVersion:initial.stateVersion,label:'synthetic-plans'});
  const backup=store.createBackup('synthetic-plans'),restored=store.restoreBackup(backup.path).state;
  assert.deepEqual(restored.taxPaymentPlans,state.taxPaymentPlans); assert.deepEqual(Core.validateState(restored),[]);
});

testAsync('Planes: API local versionada rechaza concurrencia y no duplica una repeticion', async () => {
  const store=adapter(tempPersistenceRoot()), initial=store.loadState();
  store.saveState(arcaSyntheticState(),{expectedVersion:initial.stateVersion,label:'synthetic-plan-api'});
  const version=store.loadState().stateVersion;
  const request=(payload,stateVersion)=>callApiForTest({method:'POST',url:'/api/transaction',body:{action:'taxPaymentPlan',payload,stateVersion},persistence:store});
  let response=await request(taxPlanSyntheticPayload(),version);
  assert.equal(response.status,200);
  const saved=response.payload.state, nextVersion=response.payload.stateVersion;
  const conflict=await request({...arcaSyntheticPayload(),operation:'cancel',planId:saved.taxPaymentPlans[0].id},version);
  assert.equal(conflict.status,409); assert.deepEqual(store.loadState().state,saved);
  response=await request(taxPlanSyntheticPayload(),nextVersion);
  assert.equal(response.status,200); assert.deepEqual(response.payload.state,saved);
  assert.equal(response.payload.state.instruments.length,3);
});

