test('ARCA: Flujo proyecta solo cuotas y banco cambia unicamente al realizar un debito', () => {
  const state = Core.importArcaPlansTransaction(arcaSyntheticState(), arcaSyntheticPayload(), 'test');
  const rows = Core.flowRows(state);
  assert.equal(rows.length, 35); assert(!rows.some((r) => r.source === 'document-balance'));
  for (const instrument of state.instruments) {
    const projected = rows.filter((r) => r.instrumentId === instrument.id);
    assert.equal(projected.length, 1); assert.equal(projected[0].date, instrument.scheduledDate);
    assert.equal(Math.round(Math.abs(projected[0].amount) * 100), Math.round(instrument.amount * 100));
  }
  const id = state.instruments[0].id;
  const realized = Core.transitionInstrument(state, id, 'executed', '2026-11-16', 'test');
  const movements = Core.financialMovementRows(realized, {}).filter((r) => r.id === id && r.source === 'instrument');
  assert.equal(movements.length, 1);
  assert.equal(movements[0].expense, state.instruments[0].amount);
  assert.equal(Core.flowRows(realized).filter((r) => r.instrumentId === id).length, 1);
  assert.equal(Core.economicAmountForDocument(realized.documents[0]), 0);
  assert.deepEqual(Core.validateState(realized), []);
});

