test('ARCA: persistencia local, cache en memoria, backup y restore preservan la obligacion', () => {
  const state = Core.importArcaPlansTransaction(arcaSyntheticState(), arcaSyntheticPayload(), 'test');
  const gateway = new MemoryFirestoreGateway();
  const persistence = firestoreAdapter(gateway);
  persistence.writeValidated(state, 1);
  const reloaded = firestoreAdapter(gateway).loadState().state;
  assert.deepEqual(reloaded.documents, state.documents);
  assert.equal(Core.economicSummary(reloaded, { currency: 'ARS' }).expense, 0);
  const store = adapter(tempPersistenceRoot());
  const initial = store.loadState();
  store.saveState(state, { expectedVersion: initial.stateVersion, label: 'synthetic-arca' });
  const backup = store.createBackup('synthetic-arca');
  const restored = store.restoreBackup(backup.path).state;
  assert.deepEqual(restored.documents, state.documents);
  assert.deepEqual(Core.validateState(restored), []);
});

