test('Orden existente: instrumentacion completa conserva orden documentos y economia', () => {
  let state = fresh();
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', commercialSide: 'purchase', entityId: 'ENT-PROV-AGRI', number: 'OP-2026-0117', amount: 3204366.89, currency: 'ARS', issueDate: '2026-09-01', dueDate: '2026-09-20', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS', description: 'Vencimiento prestamo/tarjeta' }, 'test');
  const documentId = state.documents.at(-1).id;
  state = Core.createOrderTransaction(state, { type: 'payment', documentId, amountApplied: 3204366.89, financialAccountId: 'ACC-GALICIA-ARS', instruments: [] }, 'test');
  const orderId = state.orders.at(-1).id;
  const before = { orders: state.orders.length, documents: state.documents.length, instruments: state.instruments.length, orderDocuments: state.orderDocuments.map((item) => item.id), settlements: state.orderDocumentSettlements.length, economic: state.documents.reduce((sum, item) => sum + item.amount, 0) };
  state = Core.addOrderInstrumentsTransaction(state, orderId, { instruments: [{ type: 'transfer', amount: 3204366.89, financialAccountId: 'ACC-GALICIA-ARS', scheduledDate: '2026-09-30', status: 'scheduled', reference: 'TR-OP-00015', notes: 'Instrumentacion pendiente' }] }, 'test');
  const breakdown = Core.orderBreakdown(state, orderId);
  assert.equal(breakdown.applied, 3204366.89);
  assert.equal(breakdown.notCoveredByInstrument, 0);
  assert.equal(breakdown.pending, 3204366.89);
  assert.equal(state.orders.length, before.orders);
  assert.equal(state.documents.length, before.documents);
  assert.deepEqual(state.orderDocuments.map((item) => item.id), before.orderDocuments);
  assert.equal(state.instruments.length, before.instruments + 1);
  assert.equal(state.orderInstruments.filter((item) => item.orderId === orderId).length, 1);
  assert.equal(state.orderDocumentSettlements.length, before.settlements + 1);
  assert.equal(state.documents.reduce((sum, item) => sum + item.amount, 0), before.economic);
  const rows = Core.flowRows(state);
  assert.equal(rows.some((row) => row.documentId === documentId && row.source === 'document-balance'), false);
  const instrumentRow = rows.find((row) => row.instrumentId === state.instruments.at(-1).id);
  assert(instrumentRow);
  assert.equal(instrumentRow.userStatus, 'Pendiente');
  assert.equal(Core.validateState(state).length, 0);
});

