  state = Core.createOrderTransaction(state, { type: 'payment', documentId: state.documents.at(-1).id, amountApplied: 1000, financialAccountId: 'ACC-GALICIA-ARS', instruments: [] }, 'test');
  const orderId = state.orders.at(-1).id;
  const orderDocumentId = state.orderDocuments.at(-1).id;
  const beforeSettlements = state.orderDocumentSettlements.length;
  state = Core.addOrderInstrumentsTransaction(state, orderId, { instruments: [{ type: 'vep', amount: 400, financialAccountId: 'ACC-GALICIA-ARS', scheduledDate: '2026-09-25', status: 'scheduled', reference: 'VEP-1' }] }, 'test');
