  state = Core.addOrderInstrumentsTransaction(state, orderId, { instruments: [{ type: 'cash', amount: 600, financialAccountId: 'ACC-CAJA-ARS', scheduledDate: '2026-09-26', status: 'executed', reference: 'EF-1' }] }, 'test');
