test('Instrumentos: correccion historica de dos cheques conserva IDs, vinculos y saldo', () => {
  let state = fresh();
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', commercialSide: 'purchase', entityId: 'ENT-PROV-AGRI', number: 'REG-189', amount: 1572309, currency: 'ARS', issueDate: '2026-09-01', dueDate: '2026-09-20', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS' }, 'test');
  const documentId = state.documents.at(-1).id;
  state = Core.createOrderTransaction(state, { type: 'payment', documentId, amountApplied: 1572309, financialAccountId: 'ACC-GALICIA-ARS', instruments: [572309, 500, 500].map((amount, index) => ({ type: 'own_check', amount, status: 'delivered', scheduledDate: '2026-10-20', checkNumber: String(index + 1) })) }, 'test');
  const ids = state.instruments.slice(-3).map((item) => item.id);
  const before = JSON.stringify(state);
  const relations = state.orderDocumentSettlements.map((item) => [item.id, item.orderDocumentId, item.orderInstrumentId]);
  assert.equal(Core.documentBreakdown(state, documentId).nonInstrumented, 999000);
  state = Core.updateInstrumentTransaction(state, ids[1], { amount: 500000, checkNumber: '02664412' }, 'test');
  state = Core.updateInstrumentTransaction(state, ids[2], { amount: 500000, checkNumber: '02664410' }, 'test');
  assert.deepEqual(state.instruments.slice(-3).map((item) => item.id), ids);
  assert.deepEqual(state.orderDocumentSettlements.map((item) => [item.id, item.orderDocumentId, item.orderInstrumentId]), relations);
  assert.equal(Core.documentBreakdown(state, documentId).nonInstrumented, 0);
  assert.equal(state.orderInstruments.filter((item) => ids.includes(item.instrumentId)).reduce((sum, item) => sum + item.amount, 0), 1572309);
  assert.equal(Core.validateState(state).length, 0);
  const unchanged = JSON.stringify(state);
  assert.throws(() => Core.updateInstrumentTransaction(state, ids[2], { amount: 500001 }, 'test'));
  assert.equal(JSON.stringify(state), unchanged);
  assert.notEqual(before, unchanged);
  assert.throws(() => Core.updateInstrumentTransaction(state, ids[2], { currency: 'USD' }, 'test'));
  const realized = structuredClone(state);
  realized.instruments.find((item) => item.id === ids[2]).status = 'debited';
  assert.throws(() => Core.updateInstrumentTransaction(realized, ids[2], { amount: 400000 }, 'test'), /correccion/);
});

test('Navegacion: instrumento, documento, orden y trazabilidad conservan relaciones y contexto', () => {
  const { app, elements } = appVmWithFlowDom();
  const state = fresh();
  const before = JSON.stringify(state);
  app.setTestState(state, []);
  ['recordDetailPanel', 'orderDetailPanel', 'instrumentDetailPanel', 'monthDetailPanel'].forEach((id) => {
    app.openOrderDetail('OP-DEMO-001');
    const panel = elements.get(id) || new FakeElement(id);
    const classes = new Set(['hidden']);
    panel.classList = { add(value) { classes.add(value); }, remove(value) { classes.delete(value); }, toggle(value, force) { if (force === undefined ? !classes.has(value) : force) classes.add(value); else classes.delete(value); }, contains(value) { return classes.has(value); } };
    elements.set(id, panel);
  });
  const instrument = state.instruments.find((item) => item.type === 'own_check' && item.status === 'delivered');
  app.navigateTarget({ type: 'instrument', id: instrument.id });
  const body = elements.get('instrumentDetailBody');
  const relations = app.instrumentRelations(instrument.id);
  const doc = relations.documents[0];
  const order = relations.orders[0];
  findNodes(body, (node) => node.textContent === doc.number && node.eventListeners.click).at(-1).click();
  const panel = elements.get('recordDetailPanel');
  assert(!panel.classList.contains('hidden'));
  assert(textTree(panel).includes('DOCUMENTO'));
  assert(textTree(panel).includes('Saldo comercial pendiente'));
  findNodes(panel, (node) => node.textContent === Core.orderDisplayCode(state, order.id) && node.eventListeners.click).at(-1).click();
  assert.equal(elements.get('orderDetailTitle').textContent, `ORDEN DE PAGO — ${Core.orderDisplayCode(state, order.id)}`);
  app.backToMonthDetail();
  assert(!panel.classList.contains('hidden'));
  findNodes(panel, (node) => node.textContent === 'Volver' && node.eventListeners.click).at(-1).click();
  assert(!elements.get('instrumentDetailPanel').classList.contains('hidden'));
  findNodes(body, (node) => node.textContent === Core.orderDisplayCode(state, order.id) && node.eventListeners.click).at(-1).click();
  assert.equal(elements.get('orderDetailTitle').textContent, `ORDEN DE PAGO — ${Core.orderDisplayCode(state, order.id)}`);
  app.navigateTarget({ type: 'instrument', id: instrument.id });
  findNodes(elements.get('instrumentDetailBody'), (node) => node.textContent === 'Trazabilidad' && node.eventListeners.click).at(-1).click();
  assert(!panel.classList.contains('hidden'));
  assert(textTree(panel).includes('Documentos vinculados'));
  assert(textTree(panel).includes('Ordenes vinculadas'));
  assert.equal(JSON.stringify(state), before);
});

test('Operaciones: filtros combinables, paginacion y resumen de cuenta sin sumar ordenes', () => {
  const { app, elements } = appVmWithFlowDom();
  const state = fresh();
  const before = JSON.stringify(state);
  app.setTestState(state, []);
  const doc = state.documents.find((item) => !item.voidedAt);
  const rows = app.operationRows('documents', { number: doc.number, currency: doc.currency, entity: Core.entityName(state, doc.entityId), dateFrom: doc.issueDate, dateTo: doc.issueDate, type: doc.type, activity: doc.activity, chartAccountId: doc.chartAccountId });
  assert.equal(rows.length, 1);
  assert.equal(rows[0].id, doc.id);
  assert.equal(app.operationRows('documents', { number: doc.number, currency: 'USD' }).length, doc.currency === 'USD' ? 1 : 0);
  const order = state.orders[0];
  assert.equal(app.operationRows('orders', { number: Core.orderDisplayCode(state, order.id), type: order.type, currency: order.currency })[0].id, order.id);
  assert.equal(app.operationRows('orders', { search: 'inexistente-test' }).length, 0);
  const many = Array.from({ length: 63 }, (_, id) => ({ id }));
  assert.equal(app.operationPage(many, 0, 25).rows.length, 25);
  assert.equal(app.operationPage(many, 1, 25).rows[0].id, 25);
  assert.equal(app.operationPage(many, 99, 25).rows.length, 13);
  assert.equal(app.operationPage(many, 0, 50).rows.length, 50);
  const summaries = app.accountEconomicSummary(doc.chartAccountId);
  const summary = summaries.find((item) => item.currency === doc.currency);
  const originals = state.documents.filter((item) => item.chartAccountId === doc.chartAccountId && item.currency === doc.currency && !item.voidedAt).reduce((sum, item) => sum + item.amount, 0);
  assert.equal(summary.original, originals);
  assert.equal(summary.original, summary.cancelled + summary.pending);
  app.renderOperations();
  const button = findNodes(elements.get('documentsTable'), (node) => node.textContent === doc.number && node.eventListeners.click)[0];
  button.click();
  assert(textTree(elements.get('recordDetailPanel')).includes(doc.number));
  findNodes(elements.get('ordersTable'), (node) => node.textContent === Core.orderDisplayCode(state, order.id) && node.eventListeners.click)[0].click();
  assert.equal(elements.get('orderDetailTitle').textContent, `ORDEN DE PAGO — ${Core.orderDisplayCode(state, order.id)}`);
  assert.equal(JSON.stringify(state), before);
});

