  ['instruments', 'orderDocuments', 'orderInstruments', 'orderDocumentSettlements'].forEach((key) => assert.deepEqual(result[key], state[key]));
  assert.deepEqual(Core.validateState(result), []);
  const ambiguous = JSON.parse(JSON.stringify(state));
  ambiguous.orderDocuments.push({ ...ambiguous.orderDocuments.at(-1), id: 'OD-AMBIGUOUS', documentId: ambiguous.documents[0].id });
  const before = JSON.stringify(ambiguous);
