function callRawApiForTest({ method = 'GET', url = '/api/state', body = null, headers = {}, persistence, auth = { required: false } }) {
  return new Promise((resolve) => {
    const res = {
      writeHead(status, responseHeaders) { this.status = status; this.headers = responseHeaders; },
      end(data) { resolve({ status: this.status, headers: this.headers, bytes: Buffer.isBuffer(data) ? data : Buffer.from(data || '') }); }
    };
    handleApi(fakeHttpRequest(method, url, body, headers), res, persistence, auth);
  });
}

function responseTextForTest(response) {
  return (response.headers['Content-Encoding'] === 'gzip' ? zlib.gunzipSync(response.bytes) : response.bytes).toString('utf8');
}

