test('Recategorizacion: persistencia generica en memoria conserva par cache backup reload y anulacion', () => {
  const gateway = new MemoryFirestoreGateway(), store = firestoreAdapter(gateway);
  const original = livestockCategoryChangeFixture(); store.writeValidated(original, 1);
  const loaded = store.loadState();
  const candidate = Core.createLivestockCategoryChangeTransaction(loaded.state, categoryChangePayload(), 'test');
  const saved = store.saveState(candidate, { expectedVersion: loaded.stateVersion });
  const reader = firestoreAdapter(gateway), reloaded = reader.loadState();
  assert.deepEqual(reloaded.state, candidate);
  reader.loadState(); assert.equal(reader.lastReadStats.cacheHit, true);
  const backup = reader.createBackup('category-change-test');
  const corrected = Core.updateLivestockCategoryChangeTransaction(saved.state, 'LCAT-TEST', { heads: 30, reason: 'Correccion local' }, 'test');
  const updated = store.saveState(corrected, { expectedVersion: saved.stateVersion });
  const annulled = Core.voidLivestockCategoryChangeTransaction(updated.state, 'LCAT-TEST', 'Prueba', 'test');
  store.saveState(annulled, { expectedVersion: updated.stateVersion });
  assert.equal(Core.livestockStockAt(reader.loadState().state, { category: 'Novillo' }), 60);
  const restored = reader.restoreBackup(backup);
  assert.equal(Core.livestockStockAt(restored.state, { category: 'Novillito' }), 20);
  assert.equal(Core.validateState(restored.state).length, 0);
});

testAsync('Recategorizacion API: crear editar anular por Core y rechazo sin persistir ni adelantar version', async () => {
  const gateway = new MemoryFirestoreGateway(), persistence = firestoreAdapter(gateway);
  persistence.writeValidated(livestockCategoryChangeFixture(), 1);
  const auth = authForApiTests(), headers = { authorization: 'Bearer valid-admin' };
  const post = (body) => callApiForTest({ method: 'POST', url: '/api/transaction', persistence, auth, headers, body });
  const created = await post({ action: 'createLivestockCategoryChange', payload: categoryChangePayload(), expectedStateVersion: 1 });
  assert.equal(created.status, 200); assert.equal(created.payload.stateVersion, 2);
  assert.equal(Core.livestockStockAt(created.payload.state, { category: 'Novillito' }), 20);
  const before = JSON.stringify(persistence.loadState());
  const failed = await post({ action: 'updateLivestockCategoryChange', id: 'LCAT-TEST', changes: { heads: 61, reason: 'Exceso' }, expectedStateVersion: 2 });
  assert.equal(failed.status, 400); assert.equal(JSON.stringify(persistence.loadState()), before);
  const updated = await post({ action: 'updateLivestockCategoryChange', id: 'LCAT-TEST', changes: { heads: 30, reason: 'Correccion' }, expectedStateVersion: 2 });
  assert.equal(updated.status, 200); assert.equal(updated.payload.stateVersion, 3);
  const voided = await post({ action: 'voidLivestockCategoryChange', id: 'LCAT-TEST', reason: 'Prueba', expectedStateVersion: 3 });
  assert.equal(voided.status, 200); assert.equal(voided.payload.stateVersion, 4);
  assert.equal(Core.livestockStockAt(voided.payload.state, { category: 'Novillo' }), 60);
  assert.equal(Core.validateState(voided.payload.state).length, 0);
});

