function purchaseCategoryCorrectionFixture() {
  return Core.createLivestockTradeTransaction(livestockBaseState(), {
    id: 'LTR-CATEGORY-ERROR', documentId: 'DOC-CATEGORY-ERROR', movementId: 'LM-CATEGORY-ERROR',
    type: 'purchase', date: '2026-09-01', herdId: 'LH-TERNEROS', locationId: 'LL-CAMPO', category: 'Novillito',
    heads: 30, totalKg: 6000, pricePerKg: 2000, currency: 'ARS', counterpartyEntityId: 'ENT-PROV-AGRI',
    number: 'COMPRA-CATEGORIA', description: 'Compra de 30 animales'
  }, 'creador');
}

function correctPurchaseCategory(state, category = 'Ternero') {
  return Core.correctHistoricalLivestockPurchaseCategoryTransaction(state, 'LTR-CATEGORY-ERROR', {
    category, reason: 'Error de carga: se compraron Terneros'
  }, 'corrector');
}

test('Categoria compra historica: corrige 30 Novillitos a Terneros desde la fecha original sin nueva compra', () => {
  const state = purchaseCategoryCorrectionFixture(), snapshot = JSON.stringify(state);
  const corrected = correctPurchaseCategory(state);
  assert.equal(JSON.stringify(state), snapshot);
  assert.equal(Core.livestockStockAt(corrected, { category: 'Novillito' }), 0);
  assert.equal(Core.livestockStockAt(corrected, { category: 'Ternero', date: '2026-09-01' }), 30);
  assert.equal(Core.livestockStockAt(corrected, {}), 30);
  assert.equal(corrected.livestockTrades.length, 1);
  assert.equal(corrected.livestockTrades[0].id, state.livestockTrades[0].id);
  assert.equal(corrected.livestockMovements[0].id, state.livestockMovements[0].id);
  assert.equal(corrected.documents[0].id, state.documents[0].id);
  assert.equal(corrected.documents[0].livestockCategory, 'Ternero');
  assert(!corrected.livestockMovements.some((row) => row.movementType === 'category_change'));
  assert.deepEqual(Core.validateState(corrected), []);
});

test('Categoria compra historica: documento OP instrumentos realizados y pendientes settlements banco y resultado intactos', () => {
  let state = purchaseCategoryCorrectionFixture();
  state = Core.createOrderTransaction(state, { type: 'payment', documentId: 'DOC-CATEGORY-ERROR', amountApplied: 12000000,
    financialAccountId: 'ACC-GALICIA-ARS', instruments: [
      { type: 'transfer', amount: 1000000, status: 'executed', scheduledDate: '2026-09-02', reference: 'PAGO-REAL' },
      { type: 'transfer', amount: 2000000, status: 'scheduled', scheduledDate: '2026-10-01', reference: 'PAGO-PENDIENTE' }
    ] }, 'test');
  const corrected = correctPurchaseCategory(state);
  const permitted = new Set(['documents', 'livestockTrades', 'livestockMovements', 'auditLog']);
  Object.keys(state).filter((key) => !permitted.has(key)).forEach((key) => assert.deepEqual(corrected[key], state[key], key));
  const withoutCategory = (doc) => { const copy = { ...doc }; delete copy.livestockCategory; return copy; };
  assert.deepEqual(corrected.documents.map(withoutCategory), state.documents.map(withoutCategory));
  ['currentAccountRows', 'financialMovementRows', 'accountBalances', 'flowRows', 'taxTotals', 'economicDocumentRows', 'economicSummary'].forEach((fn) => assert.deepEqual(Core[fn](corrected), Core[fn](state), fn));
  const beforeBreakdown = Core.documentBreakdown(state, 'DOC-CATEGORY-ERROR');
  const afterBreakdown = Core.documentBreakdown(corrected, 'DOC-CATEGORY-ERROR');
  assert.deepEqual({ ...afterBreakdown, doc: withoutCategory(afterBreakdown.doc) }, { ...beforeBreakdown, doc: withoutCategory(beforeBreakdown.doc) });
  assert.equal(corrected.livestockTrades[0].amount, 12000000);
  assert.equal(corrected.livestockTrades[0].totalKg, 6000);
  assert.deepEqual(Core.validateState(corrected), []);
});

test('Categoria compra historica: audit registra cada ID categoria anterior nueva motivo usuario y fecha', () => {
  const corrected = correctPurchaseCategory(purchaseCategoryCorrectionFixture());
  const audit = corrected.auditLog[0];
  assert.equal(audit.action, 'correct-historical-livestock-purchase-category');
  assert.equal(audit.entityType, 'livestockTrade'); assert.equal(audit.entityId, 'LTR-CATEGORY-ERROR');
  assert.equal(audit.reason, 'Error de carga: se compraron Terneros'); assert.equal(audit.user, 'corrector');
  assert(Number.isFinite(Date.parse(audit.createdAt)));
  assert.deepEqual(audit.changes.map((change) => change.recordId), ['LTR-CATEGORY-ERROR', 'DOC-CATEGORY-ERROR', 'LM-CATEGORY-ERROR']);
  audit.changes.forEach((change) => { assert.equal(change.from, 'Novillito'); assert.equal(change.to, 'Ternero'); });
});

