    if (type === 'death') state = Core.createLivestockDeathTransaction(state, { id: 'LM-DEPENDENT-DEATH', date: '2026-09-02', herdId: 'LH-TERNEROS', locationId: 'LL-CAMPO', category: 'Novillito', heads: 3, cause: 'Accidente' }, 'test');
