test('Categoria compra historica: preview solo lectura y reconstruccion persistencia backup conserva IDs y auditoria', () => {
  const state = purchaseCategoryCorrectionFixture(), snapshot = JSON.stringify(state);
  const info = Core.livestockPurchaseCategoryCorrectionInfo(state, 'LTR-CATEGORY-ERROR');
  assert.equal(info.movements.length, 1); assert.equal(info.blockers.length, 0);
  assert.equal(JSON.stringify(state), snapshot);
  const gateway = new MemoryFirestoreGateway(), store = firestoreAdapter(gateway);
  store.writeValidated(state, 1);
  const backup = store.createBackup();
  const candidate = correctPurchaseCategory(store.loadState().state);
  const saved = store.saveState(candidate, { expectedVersion: 1 });
  const reload = firestoreAdapter(gateway).loadState();
  assert.equal(saved.stateVersion, 2); assert.equal(reload.state.livestockTrades[0].category, 'Ternero');
  assert.equal(reload.state.livestockMovements[0].id, 'LM-CATEGORY-ERROR');
  assert.equal(reload.state.auditLog[0].action, 'correct-historical-livestock-purchase-category');
  assert.deepEqual(Core.validateState(reload.state), []);
  const restored = store.restoreBackup(backup);
  assert.equal(restored.state.livestockTrades[0].category, 'Novillito');
});

testAsync('Categoria compra historica API: delegado Core versionado error sin persistir y conflicto de version', async () => {
  const gateway = new MemoryFirestoreGateway(), persistence = firestoreAdapter(gateway);
  persistence.writeValidated(purchaseCategoryCorrectionFixture(), 1);
  const post = (body) => callApiForTest({ method: 'POST', url: '/api/transaction', persistence,
    auth: authForApiTests(), headers: { authorization: 'Bearer valid-admin' }, body });
  const changes = { category: 'Ternero', reason: 'Error de categoria' };
  const before = JSON.stringify(persistence.loadState());
  const failed = await post({ action: 'correctHistoricalLivestockPurchaseCategory', id: 'LTR-CATEGORY-ERROR', changes: { ...changes, amount: 1 }, stateVersion: 1 });
  assert.equal(failed.status, 400); assert.equal(JSON.stringify(persistence.loadState()), before);
  const saved = await post({ action: 'correctHistoricalLivestockPurchaseCategory', id: 'LTR-CATEGORY-ERROR', changes, stateVersion: 1 });
  assert.equal(saved.status, 200); assert.equal(saved.payload.stateVersion, 2);
  assert.equal(saved.payload.state.livestockTrades[0].category, 'Ternero');
  const stale = await post({ action: 'correctHistoricalLivestockPurchaseCategory', id: 'LTR-CATEGORY-ERROR', changes: { ...changes, category: 'Novillo' }, stateVersion: 1 });
  assert.equal(stale.status, 409); assert.equal(persistence.loadState().stateVersion, 2);
});

