test('Historico: corrige centavo realizado preservando identidad, relaciones y estado', () => {
  const state = historicalCorrectionFixture();
  const instrument = state.instruments.at(-2);
  const snapshot = JSON.stringify(state);
  const result = Core.correctHistoricalInstrumentTransaction(state, instrument.id, { amount: 198758.68, reason: 'Centavo historico documentado' }, 'test');
  const order = result.orders.at(-1);
  const b = Core.orderBreakdown(result, order.id);
  assert(Math.abs(b.paidOrCollected - 397517.35) < 0.00001);
  assert(Math.abs(b.notCoveredByInstrument) < 0.00001);
  ['instruments', 'orders', 'documents', 'orderDocuments', 'orderInstruments', 'orderDocumentSettlements'].forEach((key) => assert.deepEqual(result[key].map((item) => item.id), state[key].map((item) => item.id)));
  assert.equal(result.instruments.find((item) => item.id === instrument.id).status, 'debited');
  assert.equal(result.instruments.find((item) => item.id === instrument.id).executedDate, instrument.executedDate);
  assert.equal(result.documents.at(-1).amount, 397517.35);
  assert(result.auditLog[0].changes.some((item) => item.from === 198758.67 && item.to === 198758.68));
  assert.equal(result.auditLog[0].action, 'correct-historical-instrument');
  assert.deepEqual(Core.validateState(result), []);
  assert.equal(JSON.stringify(state), snapshot);
  assert.throws(() => Core.updateInstrumentTransaction(state, instrument.id, { amount: 198758.68 }, 'test'), /correccion/);
});

test('Historico: transferencia realizada corrige importe y ambas fechas iguales sin recrear relaciones', () => {
  let state = emptyState();
  state = Core.createDocumentTransaction(state, { type: 'sale_invoice', commercialSide: 'sale', entityId: 'ENT-CLIENTE-DEMO', number: 'SWIFT-FECHAS', amount: 73752816.15, currency: 'ARS', issueDate: '2026-07-30', dueDate: '2026-08-20', activity: 'Ganaderia', chartAccountId: 'CA-GAN', description: 'Venta hacienda' }, 'test');
  const documentId = state.documents.at(-1).id;
  state = Core.createOrderTransaction(state, { type: 'collection', date: '2026-07-30', documentId, amountApplied: 73752816.15, financialAccountId: 'ACC-GALICIA-ARS', instruments: [{ type: 'transfer', amount: 72422403.54, scheduledDate: '2026-08-20', executedDate: '2026-07-30', status: 'executed', reference: '0197-00049226' }] }, 'test');
  const instrumentId = state.instruments.at(-1).id;
  const ids = Object.fromEntries(['documents', 'orders', 'instruments', 'orderDocuments', 'orderInstruments', 'orderDocumentSettlements'].map((key) => [key, state[key].map((item) => item.id)]));
  const original = JSON.stringify(state);
  const { app } = appVmWithPanelDom();
  assert.equal(app.historicalInstrumentEffectiveDate(state.instruments.at(-1)).value, '2026-08-20');
  assert.equal(app.historicalInstrumentEffectiveDate(state.instruments.at(-1)).stored, '2026-07-30');
  assert.equal(app.historicalInstrumentEffectiveDate(state.instruments.at(-1)).suggested, true);

  const corrected = Core.correctHistoricalInstrumentTransaction(state, instrumentId, { amount: 72422403.55, scheduledDate: '2026-08-20', executedDate: '2026-08-20', reference: '0197-00049226', reason: 'Comprobante bancario' }, 'test');
  const instrument = corrected.instruments.find((item) => item.id === instrumentId);
  assert.equal(instrument.amount, 72422403.55);
  assert.equal(instrument.scheduledDate, '2026-08-20');
  assert.equal(instrument.executedDate, '2026-08-20');
  assert.equal(instrument.status, 'executed');
  for (const key of Object.keys(ids)) assert.deepEqual(corrected[key].map((item) => item.id), ids[key]);
  assert.equal(corrected.orderInstruments.at(-1).amount, 72422403.55);
  assert.equal(corrected.orderDocumentSettlements.at(-1).amount, 72422403.55);
  assert.deepEqual(Core.validateState(corrected), []);
  assert.equal(JSON.stringify(state), original);
  assert.equal(app.historicalInstrumentEffectiveDate(instrument).suggested, false);

  assert.throws(() => Core.correctHistoricalInstrumentTransaction(state, instrumentId, { scheduledDate: '2026-08-21', executedDate: '2026-08-20', reason: 'Fecha incorrecta' }, 'test'), /Vencimiento posterior a la fecha realizada/);
  assert.equal(JSON.stringify(state), original);
});

test('Historico: ambiguedad, sobreinstrumentacion, identidad y motivo se bloquean sin mutar', () => {
  const state = historicalCorrectionFixture();
  const id = state.instruments.at(-2).id;
  const before = JSON.stringify(state);
  assert.throws(() => Core.correctHistoricalInstrumentTransaction(state, id, { amount: 200000, reason: 'Test' }), /sobreinstrumenta/);
  assert.throws(() => Core.correctHistoricalInstrumentTransaction(state, id, { amount: 198758.68 }), /Motivo/);
  assert.throws(() => Core.correctHistoricalInstrumentTransaction(state, id, { currency: 'USD', reason: 'Test' }), /no editable/);
  const ambiguous = JSON.parse(before);
  const link = ambiguous.orderInstruments.find((item) => item.instrumentId === id);
  ambiguous.orderDocumentSettlements.push({ ...ambiguous.orderDocumentSettlements.find((item) => item.orderInstrumentId === link.id), id: 'EXTRA' });
  assert.throws(() => Core.correctHistoricalInstrumentTransaction(ambiguous, id, { reference: 'Test', reason: 'Test' }), /ambigua/);
  const endorsed = JSON.parse(before);
  endorsed.instruments.find((item) => item.id === id).status = 'endorsed';
  assert.throws(() => Core.correctHistoricalInstrumentTransaction(endorsed, id, { reference: 'Test', reason: 'Test' }), /ambigua/);
  assert.throws(() => Core.correctHistoricalInstrumentTransaction(state, id, { scheduledDate: '2026-02-30', reason: 'Test' }), /Fecha invalida/);
  assert.equal(JSON.stringify(state), before);
});

