function snapshotEnv(names) {
  return Object.fromEntries(names.map((name) => [name, process.env[name]]));
}

function restoreEnv(snapshot) {
  Object.entries(snapshot).forEach(([name, value]) => {
    if (value == null) delete process.env[name];
    else process.env[name] = value;
  });
}

function emulatorEnabled() {
  return process.env.RUN_FIRESTORE_EMULATOR_TESTS === '1' && Boolean(process.env.FIRESTORE_EMULATOR_HOST);
}

function emulatorStore(environment = 'demo', rootCollection = `sagroAdminEmulatorTests${Date.now()}${Math.random().toString(36).slice(2)}`) {
  return new FirestorePersistenceAdapter({
    environment,
    Core,
    gateway: new FirebaseFirestoreGateway({ projectId: process.env.GCLOUD_PROJECT || 'sagro-admin-emulator-test' }),
    rootCollection
  });
}

if (emulatorEnabled()) {
  testAsync('277. Firestore Emulator: lectura y reconstruccion completa del state', async () => {
    const store = emulatorStore();
    const loaded = await store.loadStateAsync();
    assert.equal(Core.validateState(loaded.state).length, 0);
    assert(loaded.state.documents.length > 0);
    assert(loaded.state.orders.length > 0);
  });

  testAsync('278. Firestore Emulator: escritura y posterior lectura', async () => {
    const store = emulatorStore();
    const loaded = await store.loadStateAsync();
    const next = JSON.parse(JSON.stringify(loaded.state));
    next.entities.push({ id: 'ENT-EMU-CREATE', name: 'Emulator Create', type: 'supplier', role: 'Proveedor', cuit: '', active: true, suggestedActivity: '', suggestedChartAccountId: '' });
    const saved = await store.saveStateAsync(next, { expectedVersion: loaded.stateVersion, label: 'emulator-create' });
    const reread = await store.loadStateAsync();
    assert.equal(saved.stateVersion, loaded.stateVersion + 1);
    assert(reread.state.entities.some((entity) => entity.id === 'ENT-EMU-CREATE'));
  });

  testAsync('279. Firestore Emulator: expectedStateVersion rechaza conflicto', async () => {
    const store = emulatorStore();
    const loaded = await store.loadStateAsync();
    const newer = JSON.parse(JSON.stringify(loaded.state));
    newer.entities.push({ id: 'ENT-EMU-NEWER', name: 'Emulator Newer', type: 'supplier', role: 'Proveedor', cuit: '', active: true, suggestedActivity: '', suggestedChartAccountId: '' });
    await store.saveStateAsync(newer, { expectedVersion: loaded.stateVersion, label: 'newer' });
    const before = JSON.stringify(await store.loadStateAsync());
    const stale = JSON.parse(JSON.stringify(loaded.state));
    stale.entities.push({ id: 'ENT-EMU-STALE', name: 'Emulator Stale', type: 'supplier', role: 'Proveedor', cuit: '', active: true, suggestedActivity: '', suggestedChartAccountId: '' });
    await assert.rejects(() => store.saveStateAsync(stale, { expectedVersion: loaded.stateVersion, label: 'stale' }), /base cambio/i);
    assert.equal(JSON.stringify(await store.loadStateAsync()), before);
  });

  testAsync('280. Firestore Emulator: rollback ante error dentro de transaccion', async () => {
    class FailingGateway extends FirebaseFirestoreGateway {
      async runTransaction(fn) {
        await this.db.runTransaction(async (transaction) => {
          const tx = {
            get: async (docPath) => {
              const snapshot = await transaction.get(this.db.doc(docPath));
              return snapshot.exists ? snapshot.data() : null;
            },
            list: async (prefix) => {
              const snapshot = await transaction.get(this.db.collection(prefix));
              return snapshot.docs.map((doc) => ({ path: doc.ref.path, id: doc.id, data: doc.data() }));
            },
            set: async (docPath, data) => {
              if (docPath.includes('ENT-EMU-FAIL')) throw new Error('Emulator write simulado');
              return transaction.set(this.db.doc(docPath), data);
            },
            delete: async (docPath) => transaction.delete(this.db.doc(docPath))
          };
          await fn(tx);
        });
      }
    }
    const rootCollection = `sagroAdminEmulatorTests${Date.now()}${Math.random().toString(36).slice(2)}`;
    const gateway = new FailingGateway({ projectId: process.env.GCLOUD_PROJECT || 'sagro-admin-emulator-test' });
    const store = new FirestorePersistenceAdapter({ environment: 'demo', Core, gateway, rootCollection });
    const loaded = await store.loadStateAsync();
    const before = JSON.stringify(await store.loadStateAsync());
    const next = JSON.parse(JSON.stringify(loaded.state));
    next.entities.push({ id: 'ENT-EMU-FAIL', name: 'Emulator Fail', type: 'supplier', role: 'Proveedor', cuit: '', active: true, suggestedActivity: '', suggestedChartAccountId: '' });
    await assert.rejects(() => store.saveStateAsync(next, { expectedVersion: loaded.stateVersion, label: 'fail' }), /Emulator write simulado/);
    assert.equal(JSON.stringify(await store.loadStateAsync()), before);
  });

  testAsync('281. Firestore Emulator: creacion modificacion y eliminacion de registros', async () => {
    const store = emulatorStore();
    const loaded = await store.loadStateAsync();
    const created = JSON.parse(JSON.stringify(loaded.state));
    created.entities.push({ id: 'ENT-EMU-CRUD', name: 'Emulator CRUD', type: 'supplier', role: 'Proveedor', cuit: '', active: true, suggestedActivity: '', suggestedChartAccountId: '' });
    const afterCreate = await store.saveStateAsync(created, { expectedVersion: loaded.stateVersion, label: 'crud-create' });
    const modified = JSON.parse(JSON.stringify(afterCreate.state));
    modified.entities.find((entity) => entity.id === 'ENT-EMU-CRUD').name = 'Emulator CRUD Modificado';
    const afterModify = await store.saveStateAsync(modified, { expectedVersion: afterCreate.stateVersion, label: 'crud-modify' });
    const deleted = JSON.parse(JSON.stringify(afterModify.state));
    deleted.entities = deleted.entities.filter((entity) => entity.id !== 'ENT-EMU-CRUD');
    const afterDelete = await store.saveStateAsync(deleted, { expectedVersion: afterModify.stateVersion, label: 'crud-delete' });
    assert.equal(afterDelete.state.entities.some((entity) => entity.id === 'ENT-EMU-CRUD'), false);
  });

  testAsync('282. Firestore Emulator: aislamiento entre demo y production', async () => {
    const rootCollection = `sagroAdminEmulatorTests${Date.now()}${Math.random().toString(36).slice(2)}`;
    const demo = emulatorStore('demo', rootCollection);
    const production = emulatorStore('production', rootCollection);
    const demoLoaded = await demo.loadStateAsync();
    await assert.rejects(() => production.loadStateAsync(), /productiva no existe/i);
    const productionLoaded = await production.initializeProductionAsync();
    assert.notEqual(demoLoaded.environment, productionLoaded.environment);
    assert.equal(productionLoaded.state.documents.length, 0);
    assert.equal(/DEMO|Demo|FAC-DEMO/i.test(JSON.stringify(productionLoaded.state)), false);
  });
}

