test('Proyeccion agricola: Firestore generico altas cambios cache backup reload restore sin tocar adapter', () => {
  const gateway = new MemoryFirestoreGateway(); const store = firestoreAdapter(gateway);
  const state = agriculturalProjectionFixture(); store.writeValidated(state, 1);
  const reader = firestoreAdapter(gateway); const loaded = reader.loadState();
  assert.deepEqual(loaded.state.agriculturalIncomeProjections, state.agriculturalIncomeProjections);
  reader.loadState(); assert.equal(reader.lastReadStats.cacheHit, true);
  const backup = reader.createBackup('projection-round-trip');
  const updated = Core.updateAgriculturalIncomeProjectionTransaction(loaded.state, 'AIP-USD', { amount: 70000 });
  gateway.writeLog = []; const saved = reader.saveState(updated, { expectedVersion: loaded.stateVersion });
  assert(gateway.writeLog.some((entry) => entry.action === 'set' && entry.path.includes('/collections/agriculturalIncomeProjections/records/AIP-USD')));
  const removed = Core.deleteAgriculturalIncomeProjectionTransaction(saved.state, 'AIP-USD');
  reader.saveState(removed, { expectedVersion: saved.stateVersion });
  assert.equal(firestoreAdapter(gateway).loadState().state.agriculturalIncomeProjections[0].status, 'voided');
  const restored = reader.restoreBackup(backup);
  assert.equal(restored.state.agriculturalIncomeProjections[0].amount, 50000);
  assert.equal(Core.validateState(restored.state).length, 0);
  const noRecords = cloneForTest(restored.state); noRecords.agriculturalIncomeProjections = [];
  gateway.writeLog = []; reader.saveState(noRecords, { expectedVersion: restored.stateVersion });
  assert(gateway.writeLog.some((entry) => entry.action === 'delete' && entry.path.includes('/collections/agriculturalIncomeProjections/records/AIP-USD')));
});

