testAsync('Proyeccion agricola API: CRUD versionado autenticado con mismos registros sin efectos secundarios', async () => {
  const store = adapter(tempPersistenceRoot()); const loaded = store.loadState();
  const initial = loaded.state;
  const request = async (body, version) => callApiForTest({ method: 'POST', url: '/api/transaction', body: { ...body, stateVersion: version }, persistence: store });
  let response = await request({ action: 'createAgriculturalIncomeProjection', payload: agriculturalProjectionFixture().agriculturalIncomeProjections[0] }, loaded.stateVersion);
  assert.equal(response.status, 400); // API rejects technical/economic fields not editable in this entity.
  const item = agriculturalProjectionFixture().agriculturalIncomeProjections[0];
  const payload = Object.fromEntries(['id', 'campaign', 'crop', 'plannedDate', 'datePrecision', 'currency', 'amount', 'concept', 'notes'].map((key) => [key, item[key]]));
  response = await request({ action: 'createAgriculturalIncomeProjection', payload }, loaded.stateVersion);
  assert.equal(response.status, 200);
  const version = response.payload.stateVersion;
  response = await request({ action: 'updateAgriculturalIncomeProjection', id: 'AIP-USD', changes: { amount: 60000 } }, version);
  assert.equal(response.status, 200); assert.equal(response.payload.state.agriculturalIncomeProjections[0].amount, 60000);
  const snapshot = JSON.stringify(store.loadState().state);
  const conflict = await request({ action: 'deleteAgriculturalIncomeProjection', id: 'AIP-USD' }, version);
  assert.equal(conflict.status, 409); assert.equal(JSON.stringify(store.loadState().state), snapshot);
  response = await request({ action: 'replaceAgriculturalIncomeProjection', id: 'AIP-USD', payload: { replacementCircuit: 'sale' } }, response.payload.stateVersion);
  assert.equal(response.status, 200); assert.equal(response.payload.state.agriculturalIncomeProjections[0].status, 'replaced');
  for (const key of Object.keys(initial).filter((key) => !['auditLog', 'agriculturalIncomeProjections'].includes(key))) assert.deepEqual(response.payload.state[key], initial[key]);
  response = await request({ action: 'createAgriculturalIncomeProjection', payload: { ...payload, id: 'AIP-API-DELETE' } }, response.payload.stateVersion);
  assert.equal(response.status, 200);
  response = await request({ action: 'deleteAgriculturalIncomeProjection', id: 'AIP-API-DELETE' }, response.payload.stateVersion);
  assert.equal(response.status, 200); assert.equal(response.payload.state.agriculturalIncomeProjections.find((item) => item.id === 'AIP-API-DELETE').status, 'voided');
});

function savingUiFixture(overrides = {}) {
  const fixture = appVmWithPanelDom(overrides);
  const form = new FakeElement('form');
  const button = Object.assign(new FakeElement('button'), { textContent: 'Guardar', disabled: false });
  const cancel = Object.assign(new FakeElement('button'), { textContent: 'Cancelar', disabled: false });
  const blocked = Object.assign(new FakeElement('button'), { textContent: 'Accion no disponible', disabled: true });
  const error = new FakeElement('div');
  const classes = new Set(['hidden']);
  error.classList = { add: (name) => classes.add(name), remove: (name) => classes.delete(name), contains: (name) => classes.has(name) };
  form.querySelectorAll = () => [button, cancel, blocked];
  form.querySelector = (selector) => selector === '[role="alert"]' ? error : button;
  return { ...fixture, form, button, cancel, blocked, error };
}

testAsync('Guardado comun: boton ocupado inmediatamente y doble click/Enter ejecutan una sola vez', async () => {
  const { app, form, button, cancel, blocked } = savingUiFixture();
  let release; let calls = 0;
  const pending = app.runPersistentAction(form, async () => { calls++; await new Promise((resolve) => { release = resolve; }); });
  assert.equal(button.textContent, 'Guardando...'); assert.equal(button.disabled, true);
  assert.equal(cancel.disabled, true); assert.equal(form['aria-busy'], 'true');
  await app.runPersistentAction(form, () => { calls++; });
  assert.equal(calls, 1);
  release(); await pending;
  assert.equal(button.textContent, 'Guardar'); assert.equal(button.disabled, false);
  assert.equal(cancel.disabled, false); assert.equal(blocked.disabled, true);
  assert.equal(form['aria-busy'], undefined);
});

