// --- Seguridad de datos reales: respaldo, acciones destructivas y archivos servidos ---

class AsyncMemoryFirestoreGateway extends MemoryFirestoreGateway {
  // Como Firebase real: las lecturas devuelven promesas.
  async getDoc(docPath) { return super.getDoc(docPath); }
  async listDocs(prefix) { return super.listDocs(prefix); }
}

function seededFirestoreAdapter({ asyncReads = false } = {}) {
  const seedGateway = new MemoryFirestoreGateway();
  firestoreAdapter(seedGateway).writeValidated(Core.demoState('2026-09-01'), 1);
  if (!asyncReads) return firestoreAdapter(seedGateway);
  const gateway = new AsyncMemoryFirestoreGateway();
  gateway.docs = seedGateway.docs;
  return firestoreAdapter(gateway);
}

function malformedHttpRequest(method, url, text) {
  let sent = false;
  const req = new Readable({ read() { if (!sent) { this.push(text); sent = true; } this.push(null); } });
  req.method = method; req.url = url; req.headers = {};
  return req;
}

function callMalformedApiForTest(method, url, text, persistence) {
  return new Promise((resolve) => {
    const res = { statusCode: 0, writeHead(status) { this.statusCode = status; }, end(body) { resolve({ status: this.statusCode, payload: JSON.parse(body || '{}') }); } };
    handleApi(malformedHttpRequest(method, url, text), res, persistence, { required: false });
  });
}

function serveForTest(url, method = 'GET') {
  const { serveFile } = require('./server');
  return new Promise((resolve) => {
    const res = { statusCode: 0, writeHead(status) { this.statusCode = status; }, end(body) { resolve({ status: this.statusCode, body: String(body || '') }); } };
    serveFile({ url, method, headers: { host: 'localhost' } }, res);
  });
}

testAsync('Seguridad: el servidor entrega solo los archivos de la pagina, nunca datos ni codigo del servidor', async () => {
  for (const url of ['/', '/index.html', '/styles.css', '/core.js', '/corrections.js', '/app.js', '/app.js?v=2']) {
    assert.equal((await serveForTest(url)).status, 200, url);
  }
  for (const url of ['/data/demo-db.json', '/data/production-db.json', '/data/backups/x.json', '/server.js', '/persistence-firestore.js',
    '/package.json', '/.git/config', '/.env', '/tests-v11.js', '/scripts/migration-dry-run.js', '/..%2fserver.js', '/%2e%2e/server.js', '/index.html/../server.js']) {
    const response = await serveForTest(url);
    assert.equal(response.status, 404, url);
    assert(!response.body.includes('"state"'), url);
  }
  assert.equal((await serveForTest('/index.html', 'POST')).status, 404);
});

