test('Fecha de negocio: usa la hora de Argentina, no UTC (21 a 24 hs no salta al dia siguiente)', () => {
  assert.equal(Core.todayIso(new Date('2026-10-26T22:30:00-03:00')), '2026-10-26');
  assert.equal(Core.todayIso(new Date('2026-12-31T23:59:00-03:00')), '2026-12-31');
  assert.equal(Core.todayIso(new Date('2027-01-01T00:05:00-03:00')), '2027-01-01');
  assert.match(Core.todayIso(), /^\d{4}-\d{2}-\d{2}$/);
});

