test('Planes: Nuevo plan con cronograma ARCA da el mismo resultado que Preparar cuotas ARCA', () => {
  const base = Core.demoState('2026-10-13');
  base.entities.push({ id: 'ENT-ARCA-T', name: 'ARCA', type: 'supplier', role: 'Organismo', cuit: '33693450239', active: true });
  const preset = Core.ARCA_PLAN_SCHEDULES.find((plan) => plan.number === 'W761123');
  const installments = Array.from({ length: preset.count }, (_, index) => ({ date: new Date(Date.UTC(2026, 10 + index, 16)).toISOString().slice(0, 10), amount: preset.amount }));
  const viaNew = Core.taxPaymentPlanTransaction(base, { operation: 'create', confirmed: true, reason: 't', agency: 'ARCA', number: preset.number, concept: preset.description,
    entityId: 'ENT-ARCA-T', date: '2026-10-26', status: 'active', financialAccountId: 'ACC-GALICIA-ARS', installments, advance: { amount: preset.advance, date: '', mode: 'informational' } }, 't');
  const viaImport = Core.importArcaPlansTransaction(base, { entityId: 'ENT-ARCA-T', financialAccountId: 'ACC-GALICIA-ARS', date: '2026-10-26', planNumbers: ['W761123'], confirmed: true, reason: 't' }, 't');
  const shape = (state) => {
    const plan = state.taxPaymentPlans.find((item) => item.number === 'W761123');
    const doc = state.documents.find((item) => item.id === plan.documentId);
    const instruments = state.orderInstruments.filter((link) => link.orderId === plan.orderId).map((link) => state.instruments.find((item) => item.id === link.instrumentId));
    return { status: plan.status, docType: doc.type, treatment: doc.economicTreatment, amount: doc.amount, dates: instruments.map((item) => item.scheduledDate).sort(), total: instruments.reduce((sum, item) => sum + Math.round(item.amount * 100), 0) };
  };
  assert.deepEqual(shape(viaNew), shape(viaImport));
  assert.equal(Core.validateState(viaNew).length, 0);
  const again = Core.prepareArcaPlans(viaNew, { entityId: 'ENT-ARCA-T', financialAccountId: 'ACC-GALICIA-ARS', date: '2026-10-26', planNumbers: ['W761123'] });
  assert.equal(again.plans[0].missing.length, 0);
});

