test('Importes: con centavos siempre muestran dos decimales', () => {
  const app = fs.readFileSync(path.join(__dirname, 'app.js'), 'utf8');
  const start = app.indexOf('function formatMoney('); const end = app.indexOf('\n  }', start) + 4;
  const formatMoney = new Function(`${app.slice(start, end)}; return formatMoney;`)();
  assert.equal(formatMoney(1478518.4, 'ARS'), '$ 1.478.518,40');
  assert.equal(formatMoney(2308850.1, 'ARS'), '$ 2.308.850,10');
  assert.equal(formatMoney(2000.53, 'USD'), 'US$ 2.000,53');
  assert.equal(formatMoney(8000000, 'ARS'), '$ 8.000.000');
});

test('Contable: cargo bancario manual baja el banco y es gasto una sola vez', () => {
  const s0 = fresh();
  const s1 = Core.createBankChargeTransaction(s0, { instrumentId: 'INS-TR-2M', amount: 50000, description: 'Mantenimiento de cuenta', activity: 'Estructura/Admin', chartAccountId: 'CA-ADM' }, 'test');
  const bank = (s) => Core.accountBalances(s).find((a) => a.id === 'ACC-GALICIA-ARS').realBalance;
  const expense = (s) => Core.economicSummary(s, { exercise: '2026/27', currency: 'ARS' }).expense;
  assert.equal(bank(s0) - bank(s1), 50000);
  assert.equal(expense(s1) - expense(s0), 50000);
});

test('Contable: impuesto al cheque automatico aparece en Flujo y el Flujo realizado coincide con Banco/Caja', () => {
  let state = fresh();
  state = Core.updateFinancialAccountTransaction(state, 'ACC-GALICIA-ARS', { bankTaxTreatment: 'taxable', bankTaxDebitRate: 0.6, bankTaxCreditRate: 0.6, bankTaxEffectiveFrom: '2026-01-01', reason: 'test' }, 'test');
  const instrument = state.instruments.find((item) => item.id === 'INS-TR-2M');
  Object.assign(instrument, { bankTaxEligible: true, status: 'scheduled', executedDate: null });
  state = Core.transitionInstrument(state, 'INS-TR-2M', 'executed', '2026-09-01', 'test');
  const charge = state.bankCharges.find((item) => item.autoGenerated);
  assert.equal(charge.amount, 12000);
  const flow = Core.flowRows(state, { asOfDate: '2026-09-30' });
  assert.equal(flow.filter((row) => row.id === charge.id).length, 1);
  const realized = flow.filter((row) => row.realized && row.currency === 'ARS' && row.source !== 'financialAdjustment').reduce((sum, row) => sum + row.amount, 0);
  const movements = Core.financialMovementRows(state, { currency: 'ARS' }).filter((row) => row.source !== 'financialAdjustment').reduce((sum, row) => sum + row.amount, 0);
  assert.equal(Math.round(realized * 100), Math.round(movements * 100));
});

