test('Contable: Cierre separa cheques en cartera y cheques propios diferidos sin repetir cuentas a pagar', () => {
  const s = Core.minimalDemoState('2026-09-01');
  s.documents.push({ id: 'DOC-V', type: 'sale_invoice', commercialSide: 'sale', fiscalStatus: 'documented', taxComponents: [], entityId: 'ENT-CLIENTE-DEMO', issueDate: '2026-09-01', dueDate: '2026-09-20', number: 'V-1', amount: 1000000, economicAmount: 1000000, currency: 'ARS', activity: 'Agricultura', chartAccountId: 'CA-AGRI', description: 'venta', voidedAt: null });
  s.orders.push({ id: 'OC-1', type: 'collection', entityId: 'ENT-CLIENTE-DEMO', date: '2026-09-01', description: 'cobro', activity: 'Agricultura', currency: 'ARS', voidedAt: null });
  s.orderDocuments.push({ id: 'OD-V', orderId: 'OC-1', documentId: 'DOC-V', amountApplied: 1000000, currency: 'ARS', voidedAt: null });
  s.instruments.push({ id: 'CHK-R', type: 'received_check', direction: 'in', entityId: 'ENT-CLIENTE-DEMO', financialAccountId: 'ACC-GALICIA-ARS', amount: 1000000, currency: 'ARS', scheduledDate: '2026-10-15', executedDate: null, status: 'inPortfolio', reference: 'R1', checkNumber: '9', bankName: 'X', notes: '' });
  s.orderInstruments.push({ id: 'OI-R', orderId: 'OC-1', instrumentId: 'CHK-R', amount: 1000000, currency: 'ARS', voidedAt: null });
  s.orderDocumentSettlements.push({ id: 'ODS-R', orderDocumentId: 'OD-V', orderInstrumentId: 'OI-R', amount: 1000000, currency: 'ARS', voidedAt: null });
  s.orders.push({ id: 'OP-2', type: 'payment', entityId: 'ENT-PROV-AGRI', date: '2026-09-01', description: 'pago', activity: 'Agricultura', currency: 'ARS', voidedAt: null });
  s.orderDocuments.push({ id: 'OD-2', orderId: 'OP-2', documentId: 'DOC-VENCIDO', amountApplied: 1250000, currency: 'ARS', voidedAt: null });
  s.instruments.push({ id: 'TR-P', type: 'transfer', direction: 'out', entityId: 'ENT-PROV-AGRI', financialAccountId: 'ACC-GALICIA-ARS', amount: 1250000, currency: 'ARS', scheduledDate: '2026-10-10', executedDate: null, status: 'scheduled', reference: 'TP', notes: '' });
  s.orderInstruments.push({ id: 'OI-2', orderId: 'OP-2', instrumentId: 'TR-P', amount: 1250000, currency: 'ARS', voidedAt: null });
  s.orderDocumentSettlements.push({ id: 'ODS-2', orderDocumentId: 'OD-2', orderInstrumentId: 'OI-2', amount: 1250000, currency: 'ARS', voidedAt: null });
  assert.deepEqual(Core.validateState(s), []);
  const summary = Core.closingSummary(s, { exercise: '2026/27', currency: 'ARS' });
  assert.equal(summary.financial.pendingReceivableValues, 1000000);
  assert.equal(summary.financial.pendingValues, 6000000);
  assert(!summary.financialComponents.pendingValues.some((link) => link.instrumentId === 'TR-P'));
  assert(summary.financialComponents.payable.some((b) => b.doc.id === 'DOC-VENCIDO' && b.committedPending === 1250000));
  for (const metric of ['pendingValues', 'pendingReceivableValues']) assertIndicatorReconciles(Core.closingIndicatorDetail(s, summary, metric));
});

test('TC estimado: usa el del mes, si falta el ultimo anterior y valida importes', () => {
  let state = fresh();
  assert.equal(Core.fxRateForMonth(state, '2026-11'), null);
  state = Core.setFxEstimatesTransaction(state, { rates: [{ month: '2026-09', rate: 1400 }, { month: '2026-12', rate: 1550.555 }] }, 'test');
  assert.equal(Core.fxRateForMonth(state, '2026-09'), 1400);
  assert.equal(Core.fxRateForMonth(state, '2026-11'), 1400);
  assert.equal(Core.fxRateForMonth(state, '2027-03'), 1550.56);
  assert.equal(Core.fxRateForMonth(state, '2026-01'), 1400);
  assert.throws(() => Core.setFxEstimatesTransaction(state, { rates: [{ month: '2026-13', rate: 1 }] }, 'test'), /Mes invalido/);
  assert.throws(() => Core.setFxEstimatesTransaction(state, { rates: [{ month: '2026-10', rate: -5 }] }, 'test'), /invalido/);
  const removed = Core.setFxEstimatesTransaction(state, { rates: [{ month: '2026-09', rate: '' }] }, 'test');
  assert.equal(removed.fxEstimates.length, 1);
  assert.deepEqual(Core.validateState(removed), []);
});

test('Flujo todo en pesos: cada mes es pesos + dolares por el TC del mes, sin cambiar importes guardados', () => {
  let state = fresh();
  state.documents.push({ id: 'DOC-USD-FX', type: 'purchase_invoice', commercialSide: 'purchase', fiscalStatus: 'documented', taxComponents: [], entityId: 'ENT-PROV-AGRI', issueDate: '2026-09-01', dueDate: '2026-11-20', number: 'USD-FX', amount: 1000, economicAmount: 1000, currency: 'USD', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS', description: 'Insumos a cosecha', voidedAt: null });
  state = Core.setFxEstimatesTransaction(state, { rates: [{ month: '2026-09', rate: 1400 }, { month: '2026-11', rate: 1500 }] }, 'test');
  const before = JSON.stringify(state);
  const options = { from: '2026-09-01', horizon: 4 };
  const ars = Core.monthlyFlow(state, { ...options, currency: 'ARS' });
  const usd = Core.monthlyFlow(state, { ...options, currency: 'USD' });
  const total = Core.monthlyFlow(state, { ...options, currency: 'ARS_TOTAL' });
  total.forEach((month, index) => {
    const rate = Core.fxRateForMonth(state, month.month);
    assert.equal(Math.round(month.net * 100), Math.round((ars[index].net + usd[index].net * rate) * 100), month.month);
  });
  assert.equal(total.find((month) => month.month === '2026-11').expenses - ars.find((month) => month.month === '2026-11').expenses, 1500000);
  assert(total.find((month) => month.month === '2026-11').rows.some((row) => row.originalCurrency === 'USD' && row.originalAmount === -1000 && row.fxRate === 1500));
  assert.equal(JSON.stringify(state), before);
});

test('Notas: alta, edicion, tarea hecha, borrado y validacion sin efecto contable', () => {
  let state = fresh();
  const result = Core.economicSummary(state, { exercise: '2026/27', currency: 'ARS' }).result;
  state = Core.saveNoteTransaction(state, { kind: 'task', title: 'Llamar al contador', dueDate: '2026-11-05', body: 'Por W761122' }, 'ana');
  const id = state.notes[0].id;
  assert.equal(state.notes[0].createdBy, 'ana');
  state = Core.saveNoteTransaction(state, { id, kind: 'task', title: 'Llamar al contador por W761122', done: true }, 'ana');
  assert.equal(state.notes[0].done, true);
  assert(state.notes[0].doneAt);
  assert.throws(() => Core.saveNoteTransaction(state, { kind: 'note', title: '   ' }, 'ana'), /título/);
  assert.throws(() => Core.saveNoteTransaction(state, { id: 'NO-EXISTE', kind: 'note', title: 'x' }, 'ana'), /ya no existe/);
  state = Core.saveNoteTransaction(state, { kind: 'note', title: 'Precio pactado soja', body: 'US$ 300/tn' }, 'ana');
  assert.equal(state.notes.length, 2);
  assert.equal(Core.economicSummary(state, { exercise: '2026/27', currency: 'ARS' }).result, result);
  state = Core.deleteNoteTransaction(state, id, 'ana');
  assert.equal(state.notes.length, 1);
  assert(state.auditLog.some((item) => item.action === 'delete-note'));
  assert.deepEqual(Core.validateState(state), []);
});

testAsync('Notas y TC: se guardan por la API y sobreviven al reinicio', async () => {
  const persistence = adapter(tempPersistenceRoot());
  const version = persistence.loadState().stateVersion;
  const first = await callApiForTest({ method: 'POST', url: '/api/transaction', body: { action: 'saveNote', stateVersion: version, payload: { kind: 'task', title: 'Revisar extracto BNA' } }, persistence, auth: { required: false } });
  assert.equal(first.status, 200);
  const second = await callApiForTest({ method: 'POST', url: '/api/transaction', body: { action: 'setFxEstimates', stateVersion: first.payload.stateVersion, payload: { rates: [{ month: '2026-11', rate: 1480 }] } }, persistence, auth: { required: false } });
  assert.equal(second.status, 200);
  const reloaded = new JsonPersistenceAdapter({ root: persistence.root, environment: 'demo', Core }).loadState().state;
  assert.equal(reloaded.notes[0].title, 'Revisar extracto BNA');
  assert.equal(reloaded.fxEstimates[0].rate, 1480);
});

test('Libro: ingresos y egresos de fondos coinciden con los movimientos de Banco/Caja', () => {
  const state = agroFresh();
  const rows = Core.generalMovementRows(state).filter((row) => row.affectsFunds);
  for (const currency of ['ARS', 'USD']) {
    const book = rows.filter((row) => row.currency === currency).reduce((sum, row) => sum + Math.round(row.financialAmount * 100), 0);
    const bank = Core.financialMovementRows(state, { currency }).reduce((sum, row) => sum + Math.round(row.amount * 100), 0);
    assert.equal(book, bank, currency);
  }
});

test('Correcciones: la de LAR no se ofrece ni se aplica si los datos no son los previstos', () => {
  const Corrections = require('./corrections.js');
  const state = fresh();
  const before = JSON.stringify(state);
  const listed = Corrections.available(state);
  assert.equal(listed.length, 1);
  assert.equal(listed[0].ready, false);
  assert.match(listed[0].reason, /cambió|Falta|No se encontró/);
  assert.throws(() => Corrections.applyCorrectionTransaction(state, 'LAR-CC-PESOS-2026-10', 'test'));
  assert.throws(() => Corrections.applyCorrectionTransaction(state, 'NO-EXISTE', 'test'), /inexistente/);
  assert.equal(JSON.stringify(state), before);
});

testAsync('Correcciones: la API rechaza una corrección que no corresponde y no guarda nada', async () => {
  const persistence = adapter(tempPersistenceRoot());
  const loaded = persistence.loadState();
  const response = await callApiForTest({ method: 'POST', url: '/api/transaction', body: { action: 'applyCorrection', id: 'LAR-CC-PESOS-2026-10', stateVersion: loaded.stateVersion }, persistence, auth: { required: false } });
  assert.notEqual(response.status, 200);
  assert.equal(persistence.loadState().stateVersion, loaded.stateVersion);
});

async function runAsyncTests() {
  for (const { name, fn } of asyncTests) {
    try {
      await fn();
      console.log(`OK ${name}`);
    } catch (error) {
      console.error(`FAIL ${name}`);
      console.error(error.stack || error.message);
      process.exitCode = 1;
    }
  }
}

if (asyncTests.length) {
  runAsyncTests();
}
test('Reintegro IVA ARCA crea transferencia vinculada sin documento, OC ni resultado economico', () => {
  let state = emptyState();
  const beforeEconomic = Core.economicSummary(state, { currency: 'ARS' });
  const beforeBank = Core.accountBalances(state).find((item) => item.id === 'ACC-GALICIA-ARS').realBalance;
  state = Core.createTaxReimbursementTransaction(state, { entityId: 'ENT-CLIENTE-DEMO', date: '2026-09-22', amount: 1682513.44, currency: 'ARS', financialAccountId: 'ACC-GALICIA-ARS', reference: '9002218', notes: 'IVA retenido en liquidaciones' }, 'test');
  const reimbursement = state.taxReimbursements.at(-1);
  const instrument = state.instruments.find((item) => item.id === reimbursement.instrumentId);
  assert(instrument);
  assert.equal(instrument.type, 'transfer');
  assert.equal(instrument.direction, 'in');
  assert.equal(instrument.status, 'executed');
  assert.equal(instrument.amount, 1682513.44);
  assert.equal(state.documents.length, 0);
  assert.equal(state.orders.length, 0);
  assert.equal(state.orderDocumentSettlements.length, 0);
  assert(Math.abs((Core.accountBalances(state).find((item) => item.id === 'ACC-GALICIA-ARS').realBalance - beforeBank) - 1682513.44) < 0.001);
  assert.deepEqual(Core.economicSummary(state, { currency: 'ARS' }), beforeEconomic);
  const flow = Core.flowRows(state, {}).find((row) => row.instrumentId === instrument.id);
  assert.equal(flow.date, '2026-09-22');
  assert.equal(flow.direction, 'in');
  assert.equal(Core.taxTotals(state, { currency: 'ARS' }).vatReimbursements, 1682513.44);
  assert.equal(Core.validateState(state).length, 0);
});

