test('Swift cancela total fiscal con transferencia y retencion Ganancias sin movimiento bancario ficticio', () => {
  let state = emptyState();
  state = Core.createDocumentTransaction(state, { type: 'sale_invoice', commercialSide: 'sale', fiscalStatus: 'documented', entityId: 'ENT-CLIENTE-DEMO', number: 'SWIFT-REAL', amount: 73752816.15, economicAmount: 66744630, currency: 'ARS', issueDate: '2026-07-30', dueDate: '2026-08-20', activity: 'Ganaderia', chartAccountId: 'CA-GAN', description: 'Venta hacienda Swift', taxComponents: [{ taxType: 'net_taxed', taxableBase: 66744630, amount: 66744630, category: 'economic' }, { taxType: 'vat', rate: 10.5, taxableBase: 66744630, amount: 7008186.15 }] }, 'test');
  const documentId = state.documents.at(-1).id;
  const beforeBank = Core.accountBalances(state).find((item) => item.id === 'ACC-GALICIA-ARS').realBalance;
  state = Core.createOrderTransaction(state, { type: 'collection', date: '2026-08-20', documentId, amountApplied: 73752816.15, financialAccountId: 'ACC-GALICIA-ARS', instruments: [{ type: 'transfer', amount: 72422403.55, scheduledDate: '2026-08-20', executedDate: '2026-08-20', status: 'executed', reference: 'Swift' }], withholdings: [{ taxType: 'withholding_income_tax', amount: 1330412.60, date: '2026-08-20', reference: 'Retencion Swift' }] }, 'test');
  const order = state.orders.at(-1);
  const breakdown = Core.orderBreakdown(state, order.id);
  assert.equal(breakdown.applied, 73752816.15);
  assert(Math.abs(breakdown.commercialCancelled - 73752816.15) < 0.001);
  assert.equal(breakdown.taxWithheld, 1330412.6);
  assert(breakdown.notCoveredByInstrument < 0.001);
  assert(Core.documentBreakdown(state, documentId).nonInstrumented < 0.001);
  assert(Math.abs((Core.accountBalances(state).find((item) => item.id === 'ACC-GALICIA-ARS').realBalance - beforeBank) - 72422403.55) < 0.001);
  assert.equal(Core.economicSummary(state, { currency: 'ARS' }).income, 66744630);
  assert(Core.taxRows(state, {}).some((row) => row.source === 'orderTaxWithholding' && row.amount === 1330412.6));
  assert.equal(state.instruments.length, 1);
  assert.equal(Core.flowRows(state, {}).find((row) => row.instrumentId === state.instruments[0].id).date, '2026-08-20');
  assert.equal(Core.validateState(state).length, 0);
});

