test('VEP de retencion practicada conserva Arrendamiento y muestra concepto sin duplicar gasto', () => {
  let state = emptyState();
  state = Core.createEntityTransaction(state, { name: 'ARCA', role: 'Ambos' }, 'test');
  state = Core.createEntityTransaction(state, { name: 'Celia Muller', role: 'Proveedor' }, 'test');
  const arcaId = state.entities.find((item) => item.name === 'ARCA').id;
  const celiaId = state.entities.find((item) => item.name === 'Celia Muller').id;
  state.chartAccounts.push({ id: 'CA-AGRI-ARREND', name: 'Arrendamiento', parentId: 'CA-AGRI', activity: 'Agricultura', active: true });
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', entityId: celiaId, number: 'ARR-CELIA', amount: 1000000, currency: 'ARS', issueDate: '2026-09-01', dueDate: '2026-09-10', activity: 'Agricultura', chartAccountId: 'CA-AGRI-ARREND', description: 'Arrendamiento' }, 'test');
  const documentId = state.documents.at(-1).id;
  state = Core.createOrderTransaction(state, { type: 'payment', date: '2026-09-10', documentId, amountApplied: 1000000, financialAccountId: 'ACC-GALICIA-ARS', instruments: [{ type: 'transfer', amount: 706626.64, scheduledDate: '2026-09-10', status: 'executed' }], practicedWithholdings: [{ taxType: 'withholding_income_tax', amount: 293373.36, date: '2026-09-10' }] }, 'test');
  const orderId = state.orders.at(-1).id;
  const withholdingId = state.orderPracticedWithholdings.at(-1).id;
  const concept = 'Ret. Ganancias - Arrendamiento - Celia Muller';
  assert.equal(Core.taxPaymentSuggestedConcept(state, [withholdingId]), concept);
  const economicBefore = Core.economicSummary(state, { currency: 'ARS' });
  const bankBefore = Core.accountBalances(state).find((item) => item.id === 'ACC-GALICIA-ARS').realBalance;
  const movementsBefore = Core.financialMovementRows(state).length;
  const documentCount = state.documents.length;
  state = Core.createTaxPaymentTransaction(state, { entityId: arcaId, financialAccountId: 'ACC-GALICIA-ARS', date: '2026-09-20', concept, reference: '9002218', allocations: [{ withholdingId, amount: 293373.36 }] }, 'test');
  const instrument = state.instruments.at(-1);
  assert.equal(state.taxPayments.at(-1).concept, concept);
  assert.equal(state.taxPayments.at(-1).reference, '9002218');
  assert.equal(instrument.reference, '9002218');
  assert.equal(Core.practicedWithholdingBalance(state, withholdingId), 0);
  assert(Math.abs(Core.accountBalances(state).find((item) => item.id === 'ACC-GALICIA-ARS').realBalance - bankBefore + 293373.36) < 0.001);
  assert.equal(Core.financialMovementRows(state).length, movementsBefore + 1);
  assert.equal(state.documents.length, documentCount);
  assert.equal(Core.economicSummary(state, { currency: 'ARS' }).expense, economicBefore.expense);
  assert.equal(Core.documentBreakdown(state, documentId).nonInstrumented, 0);
  assert.equal(state.orders.at(-1).id, orderId);
  const flow = Core.flowRows(state).find((row) => row.instrumentId === instrument.id);
  assert.equal(flow.entityName, 'ARCA');
  assert.equal(flow.concept, concept);
  assert.equal(flow.amount, -293373.36);
  assert.equal(flow.userStatus, 'Pagado');
  const { app, elements } = appVmWithPanelDom();
  app.setTestState(state, []);
  app.openInstrumentDetail(instrument.id);
  const detail = textTree(elements.get('instrumentDetailBody'));
  for (const expected of ['Retención de origen', 'Celia Muller', 'ARR-CELIA', 'Agricultura', 'Arrendamiento', concept]) assert(detail.includes(expected), expected);
  assert.equal(Core.validateState(state).length, 0);
});

