test('Firestore particionado conserva colecciones fiscales e internas en round-trip local', () => {
  const gateway = new MemoryFirestoreGateway();
  const store = firestoreAdapter(gateway);
  let state = emptyState();
  state.orderPracticedWithholdings = [];
  state.taxPayments = [];
  state.internalTransfers = [];
  store.writeValidated(state, 0);
  const reloaded = store.loadState();
  assert.equal(Core.validateState(reloaded.state).length, 0);
  assert.deepEqual(reloaded.state.orderPracticedWithholdings, state.orderPracticedWithholdings);
  assert.deepEqual(reloaded.state.taxPayments, state.taxPayments);
  assert.deepEqual(reloaded.state.internalTransfers, state.internalTransfers);
  assert.equal(reloaded.stateVersion, 1);
});

test('Definir medio: OC y OP admiten solo retenciones, multiples fechas historicas y ninguna transferencia ficticia', () => {
  for (const [type, documentType, entityId, collection] of [
    ['collection', 'sale_invoice', 'ENT-CLIENTE-DEMO', 'orderTaxWithholdings'],
    ['payment', 'purchase_invoice', 'ENT-PROV-AGRI', 'orderPracticedWithholdings']
  ]) {
    let state = emptyState();
    state = Core.createDocumentTransaction(state, { type: documentType, entityId, number: `RET-${type}`, amount: 1000, currency: 'ARS', issueDate: '2026-07-30', dueDate: '2026-08-20', activity: 'Agricultura', chartAccountId: 'CA-AGRI', description: 'Retenciones' }, 'test');
    state = Core.createOrderTransaction(state, { type, documentId: state.documents.at(-1).id, amountApplied: 1000, financialAccountId: 'ACC-GALICIA-ARS', instruments: [] }, 'test');
    const orderId = state.orders.at(-1).id;
    const bankBefore = Core.accountBalances(state);
    const payload = { instruments: [], [type === 'collection' ? 'withholdings' : 'practicedWithholdings']: [
      { taxType: 'withholding_income_tax', amount: 600, date: '2026-08-20' },
      { taxType: 'withholding_vat', amount: 400, date: '2026-08-21' }
    ] };
    state = Core.addOrderInstrumentsTransaction(state, orderId, payload, 'test');
    assert.equal(state.instruments.length, 0);
    assert.equal(state[collection].length, 2);
    assert.deepEqual(state[collection].map((item) => item.date), ['2026-08-20', '2026-08-21']);
    assert.deepEqual(Core.accountBalances(state), bankBefore);
    assert.equal(Core.orderBreakdown(state, orderId).notCoveredByInstrument, 0);
    assert.deepEqual(Core.validateState(state), []);
    assert.throws(() => Core.addOrderInstrumentsTransaction(state, orderId, payload, 'test'), /mayor al saldo/);
    assert.throws(() => Core.addOrderInstrumentsTransaction(state, orderId, { instruments: [], [type === 'collection' ? 'withholdings' : 'practicedWithholdings']: [{ taxType: 'withholding_vat', amount: 1, date: '2026-02-30' }] }, 'test'), /Fecha invalida|mayor al saldo/);
  }
});

test('Saldo documental legacy: identifica settlement activo ligado a instrumento anulado antes de guardar', () => {
  let state = emptyState();
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', entityId: 'ENT-PROV-AGRI', number: '563-18196', amount: 97288.55, currency: 'ARS', issueDate: '2026-08-02', dueDate: '2026-08-24', activity: 'Agricultura', chartAccountId: 'CA-AGRI', description: 'Factura Agromovil' }, 'test');
  state = Core.createOrderTransaction(state, { type: 'payment', date: '2026-08-02', documentId: state.documents.at(-1).id, amountApplied: 97288.55, financialAccountId: 'ACC-GALICIA-ARS', instruments: [] }, 'test');
  const orderId = state.orders.at(-1).id;
  assert.equal(Core.orderInstrumentationCapacity(state, orderId).available, 97288.55);
  const valid = Core.addOrderInstrumentsTransaction(state, orderId, { instruments: [{ type: 'transfer', amount: 97288.55, financialAccountId: 'ACC-GALICIA-ARS', scheduledDate: '2026-08-24', status: 'scheduled' }] }, 'test');
  assert.equal(Core.orderBreakdown(valid, orderId).notCoveredByInstrument, 0);
  assert.deepEqual(Core.validateState(valid), []);
  const legacy = cloneForTest(valid);
  legacy.orderInstruments.at(-1).voidedAt = '2026-08-25T00:00:00.000Z';
  const capacity = Core.orderInstrumentationCapacity(legacy, orderId);
  assert(capacity.blockers.some((item) => item.includes('Settlement')));
  const before = JSON.stringify(legacy);
  assert.throws(() => Core.addOrderInstrumentsTransaction(legacy, orderId, { instruments: [{ type: 'transfer', amount: 97288.55, financialAccountId: 'ACC-GALICIA-ARS', scheduledDate: '2026-08-24', status: 'scheduled' }] }, 'test'), /settlement historico|Settlement/);
  assert.equal(JSON.stringify(legacy), before);
});

test('Instrumento programado: anular libera saldo sin banco, cargo ni relaciones huerfanas', () => {
  let state = emptyState();
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', entityId: 'ENT-PROV-AGRI', number: 'PROG-ANULAR', amount: 2612988.83, currency: 'ARS', issueDate: '2026-08-02', dueDate: '2026-08-24', activity: 'Agricultura', chartAccountId: 'CA-AGRI', description: 'Programada' }, 'test');
  const docId = state.documents.at(-1).id;
  state = Core.createOrderTransaction(state, { type: 'payment', documentId: docId, amountApplied: 2612988.83, financialAccountId: 'ACC-GALICIA-ARS', instruments: [{ type: 'transfer', amount: 2612988.83, scheduledDate: '2026-08-24', status: 'scheduled' }] }, 'test');
  const id = state.instruments.at(-1).id;
  const bank = Core.accountBalances(state);
  assert.throws(() => Core.voidScheduledInstrumentTransaction(state, id, ''), /Motivo/);
  const next = Core.voidScheduledInstrumentTransaction(state, id, 'Nunca realizada', 'auditor');
  assert.equal(next.instruments.find((item) => item.id === id).status, 'voided');
  assert(next.orderInstruments.at(-1).voidedAt);
  assert(next.orderDocumentSettlements.at(-1).voidedAt);
  assert.equal(Core.documentBreakdown(next, docId).nonInstrumented, 2612988.83);
  assert.deepEqual(Core.accountBalances(next).map((item) => [item.id, item.realBalance]), bank.map((item) => [item.id, item.realBalance]));
  assert(!Core.flowRows(next).some((row) => row.instrumentId === id));
  assert.equal(next.bankCharges.length, 0);
  assert.equal(next.auditLog[0].user, 'auditor');
  assert.deepEqual(Core.validateState(next), []);
  assert.throws(() => Core.voidScheduledInstrumentTransaction(next, id, 'Otra vez'), /anulado/);
  assert.throws(() => Core.voidScheduledInstrumentTransaction(Core.transitionInstrument(state, id, 'executed', '2026-08-24', 'test'), id, 'No'), /no realizados/);
});

test('Reversa de transferencia realizada conserva IDs y quita banco e impuesto derivado', () => {
  let state = emptyState();
  state = Core.updateFinancialAccountTransaction(state, 'ACC-GALICIA-ARS', { bankTaxTreatment: 'taxable', bankTaxDebitRate: 0.6, bankTaxCreditRate: 0.6, bankTaxEffectiveFrom: '2026-09-01', reason: 'Configurar' }, 'test');
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', entityId: 'ENT-PROV-AGRI', number: 'REVERSA', amount: 94535, currency: 'ARS', issueDate: '2026-09-01', dueDate: '2026-09-20', activity: 'Agricultura', chartAccountId: 'CA-AGRI', description: 'Proveedor' }, 'test');
  const docId = state.documents.at(-1).id;
  state = Core.createOrderTransaction(state, { type: 'payment', documentId: docId, amountApplied: 94535, financialAccountId: 'ACC-GALICIA-ARS', instruments: [{ type: 'transfer', amount: 94535, scheduledDate: '2026-09-20', status: 'scheduled' }] }, 'test');
  const pending = cloneForTest(state);
  const id = state.instruments.at(-1).id;
  const bankBefore = Core.accountBalances(state);
  state = Core.transitionInstrument(state, id, 'executed', '2026-09-20', 'test');
  assert.equal(state.bankCharges.at(-1).amount, 567.21);
  // The automatic bank tax leaves the bank, so it appears once in Flujo (kept equal to Banco/Caja).
  assert.equal(Core.flowRows(state).filter((row) => row.source === 'bankCharge').length, 1);
  assert(Core.financialMovementRows(state).some((row) => row.source === 'bankCharge'));
  assert(Core.taxRows(state, {}).some((row) => row.source === 'bankCharge'));
  assert(Core.economicSummary(state, { currency: 'ARS' }).expense >= Core.economicSummary(pending, { currency: 'ARS' }).expense);
  const reversed = Core.reverseRealizedInstrumentTransaction(state, id, 'Marcado por error', 'auditor');
  assert.equal(reversed.instruments.find((item) => item.id === id).status, 'scheduled');
  assert.equal(reversed.instruments.find((item) => item.id === id).executedDate, null);
  assert.equal(reversed.bankCharges.length, 0);
  assert(!Core.flowRows(reversed).some((row) => row.source === 'bankCharge'));
  assert.deepEqual(Core.accountBalances(reversed), bankBefore);
  assert.equal(reversed.orderDocumentSettlements.at(-1).id, state.orderDocumentSettlements.at(-1).id);
  assert.equal(reversed.orderInstruments.at(-1).id, state.orderInstruments.at(-1).id);
  assert.equal(Core.documentBreakdown(reversed, docId).committedPending, 94535);
  assert.deepEqual(Core.validateState(reversed), []);
  assert.throws(() => Core.reverseRealizedInstrumentTransaction(reversed, id, 'Otra vez'), /Solo se revierte/);
  const dependent = cloneForTest(state);
  dependent.taxPayments.push({ id: 'TXP-LINK', instrumentId: id });
  assert.throws(() => Core.reverseRealizedInstrumentTransaction(dependent, id, 'No'), /taxPayments/);
});

