test('Correccion historica de tipo documentado requiere factura compatible y conserva relaciones', () => {
  let state = emptyState();
  state = Core.createDocumentTransaction(state, { type: 'no_receipt', commercialSide: 'sale', fiscalStatus: 'no_receipt', entityId: 'ENT-CLIENTE-DEMO', number: '', amount: 100, currency: 'ARS', recordDate: '2026-08-01', activity: 'Agricultura', chartAccountId: 'CA-AGRI', description: 'Pendiente' }, 'test');
  const id = state.documents.at(-1).id;
  state = Core.createOrderTransaction(state, { type: 'collection', documentId: id, amountApplied: 100, financialAccountId: 'ACC-GALICIA-ARS', instruments: [] }, 'test');
  const before = JSON.stringify(state);
  assert.throws(() => Core.correctHistoricalDocumentTransaction(state, id, { type: 'purchase_invoice', fiscalStatus: 'documented', number: 'F-1', issueDate: '2026-08-02', reason: 'Test' }), /Tipo historico ambiguo/);
  const corrected = Core.correctHistoricalDocumentTransaction(state, id, { type: 'sale_invoice', fiscalStatus: 'documented', number: 'F-1', issueDate: '2026-08-02', reason: 'Factura recibida' }, 'auditor');
  assert.equal(corrected.documents.find((item) => item.id === id).type, 'sale_invoice');
  assert.equal(corrected.orderDocuments.at(-1).id, state.orderDocuments.at(-1).id);
  assert.equal(corrected.auditLog[0].user, 'auditor');
  assert.deepEqual(Core.validateState(corrected), []);
  assert.equal(JSON.stringify(state), before);
});

