function livestockCommissionFormFixture(mode = 'purchase') {
  const { app, elements } = appVmWithPanelDom();
  app.setTestState(livestockBaseState());
  app.setupEvents();
  const set = (id, value) => {
    if (!elements.has(id)) elements.set(id, new FakeElement(id));
    elements.get(id).value = String(value);
  };
  const get = (id) => app.parseLocaleNumber(elements.get(id).value) || 0;
  const input = (id, value, type = 'input') => {
    set(id, value);
    for (const handler of elements.get(id).eventListeners[type] || []) handler({ target: elements.get(id), currentTarget: elements.get(id) });
  };
  set('livestockOperationMode', mode);
  set('livestockOpCurrency', 'ARS');
  set('livestockOpHeads', 31);
  set('livestockOpTotalKg', 6219);
  set('livestockOpPriceKg', 37685000 / 6219);
  set('livestockOpCommissionVatRate', 21);
  input('livestockOpNetTaxed', 37685000);
  input('livestockOpVatRate', 10.5, 'change');
  return { app, elements, input, get };
}

