test('Campos fiscales: vacios cerrados, valores abren y toggle conserva valores y estado', () => {
  const { app } = appVmWithPanelDom();
  const values = [new FakeElement('withholdingVat'), new FakeElement('perceptionIibb'), new FakeElement('withholdingDate'), new FakeElement('withholdingReference')];
  values[2].value = '2026-09-28'; values[3].value = '9002218';
  const summary = new FakeElement('summary'); summary.textContent = 'Retenciones / percepciones';
  const panel = new FakeElement('details'); panel.open = false;
  panel.querySelector = () => summary;
  panel.querySelectorAll = () => values;
  const state = Core.demoState(); const before = JSON.stringify(state);
  app.setTestState(state);
  app.syncFiscalDisclosure(panel);
  assert.equal(panel.open, false);
  panel.open = true;
  app.syncFiscalDisclosure(panel);
  assert.equal(panel.open, true, 'Permite abrir un bloque vacio');
  app.syncFiscalDisclosure(panel, true);
  assert.equal(panel.open, false, 'Nueva carga restablece el bloque vacio');
  values[0].value = '293.373,36';
  app.syncFiscalDisclosure(panel);
  assert.equal(panel.open, true);
  assert.equal(summary.textContent, 'Retenciones / percepciones (1 con importe)');
  panel.open = false;
  assert.equal(values[0].value, '293.373,36');
  assert.equal(summary.textContent, 'Retenciones / percepciones (1 con importe)');
  assert.equal(JSON.stringify(state), before);
});

