test('Auditoria Documentos Flujo: todos los documentos por ID coinciden con Core y no mutan estado', () => {
  const state = agroFresh();
  const before = JSON.stringify(state);
  const { app } = appVmWithFlowDom(); app.setTestState(state);
  const audit = app.reconcileDocumentsFlow(state);
  const flow = Core.flowRows(state).filter((row) => row.source === 'document-balance');
  assert.equal(audit.documents.length, state.documents.filter((doc) => !doc.voidedAt).length);
  assert.equal(audit.inverse.length, flow.length);
  for (const row of audit.documents) {
    const b = Core.documentBreakdown(state, row.documentId);
    const diagnosis = app.documentFinancialDiagnostics(row.documentId);
    assert.equal(row.total, b.doc.amount);
    assert.equal(row.commercialBalance, b.doc.amount - b.cancelled);
    assert.equal(row.nonInstrumented, b.nonInstrumented);
    assert.equal(row.instrumented, diagnosis.instrumented);
    assert.equal(row.projectionCount, flow.filter((item) => item.documentId === row.documentId).length);
    assert.equal(row.hasDifference, false);
  }
  assert.equal(audit.summary.reviewed, audit.summary.ok + audit.summary.differences + audit.summary.noProjection);
  assert.equal(audit.summary.differences, 0);
  assert.equal(audit.summary.inverseDifferences, 0);
  assert.equal(JSON.stringify(state), before);
  assert.equal(Core.validateState(state).length, 0);
});

