function multicurrencyPaymentFixture(currency = 'USD', amount = 4598.04) {
  const base = emptyState();
  base.entities.find((item) => item.id === 'ENT-PROV-AGRI').name = 'Microvidas';
  base.financialAccounts.push({ id: 'ACC-FX-USD', name: 'Cuenta USD prueba', productType: 'bank_account', type: 'bank', currency: 'USD', openingBalance: 0, checkEnabled: true, active: true });
  return Core.createDocumentTransaction(base, { type: 'purchase_invoice', commercialSide: 'purchase', entityId: 'ENT-PROV-AGRI', number: '003-0005053', amount, currency, issueDate: '2026-07-31', dueDate: '2026-12-17', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS', description: 'Compra insumos financiados' }, 'test');
}

function multicurrencyPayment(state, overrides = {}) {
  const doc = state.documents.at(-1);
  return Core.createOrderTransaction(state, { type: 'payment', date: '2026-07-31', documentId: doc.id, amountApplied: doc.amount, financialAccountId: 'ACC-NACION-ARS', instruments: [{ type: 'own_check', amount: 6786707, currency: 'ARS', commercialAmount: 4598.04, exchangeRate: 1476, exchangeRateSource: 'exchangeRate', exchangeRateDate: '2026-07-31', exchangeRateReference: 'Acuerdo explicito de prueba', scheduledDate: '2026-12-17', checkNumber: '02664408', status: 'issued', financialAccountId: 'ACC-NACION-ARS', ...overrides }] }, 'test');
}

test('Multimoneda Microvidas: nominal historico y diferencia de 4 centavos no se corrigen', () => {
  const original = { invoice: { number: '003-0005053', currency: 'USD', amount: 4598.04, tcInvoice: 1476 }, order: { currency: 'ARS', amount: 6786707.04 }, check: { number: '02664408', currency: 'ARS', amount: 6786707 } };
  const before = JSON.stringify(original);
  const source = multicurrencyPaymentFixture(); source.documents[0].tcInvoice = original.invoice.tcInvoice;
  const state = multicurrencyPayment(source);
  const link = state.orderInstruments[0], settlement = state.orderDocumentSettlements[0];
  assert.equal(state.instruments[0].amount, 6786707);
  assert.equal(state.orders[0].currency, 'USD');
  assert.equal(state.orderDocuments[0].amountApplied, 4598.04);
  assert.equal(link.commercialAmount, 4598.04);
  assert.equal(link.roundingDifference, -0.04);
  assert.equal(settlement.amount, 4598.04);
  assert.equal(settlement.currency, 'USD');
  assert.equal(settlement.instrumentAmount, 6786707);
  assert.equal(settlement.instrumentCurrency, 'ARS');
  assert.equal(JSON.stringify(original), before);
  assert.equal(source.orders.length, 0);
  assert.equal(Core.validateState(state).length, 0);
});

