test('Multimoneda persistencia: incremental cache reload backup restore conservan nominales TC e IDs', () => {
  const gateway = new MemoryFirestoreGateway(), store = firestoreAdapter(gateway);
  const state = multicurrencyPayment(multicurrencyPaymentFixture()); store.writeValidated(state, 1);
  const reader = firestoreAdapter(gateway), loaded = reader.loadState(); reader.loadState();
  assert.equal(reader.lastReadStats.cacheHit, true);
  const backup = reader.createBackup('multicurrency-test');
  const changed = Core.updateInstrumentTransaction(loaded.state, state.instruments[0].id, { commercialAmount: 4500 }, 'test');
  const saved = reader.saveState(changed, { expectedVersion: loaded.stateVersion });
  const reloaded = firestoreAdapter(gateway).loadState();
  assert.deepEqual(reloaded.state.orderInstruments, saved.state.orderInstruments);
  assert.deepEqual(reloaded.state.orderDocumentSettlements, saved.state.orderDocumentSettlements);
  const restored = reader.restoreBackup(backup);
  assert.deepEqual(restored.state.orderInstruments, state.orderInstruments);
  assert.deepEqual(restored.state.orderDocumentSettlements, state.orderDocumentSettlements);
  assert.equal(Core.validateState(restored.state).length, 0);
});

