function instrumentCurrencyFormFixture(invoiceFields = {}) {
  const { app, elements, document } = appVmWithPanelDom();
  const state = multicurrencyPaymentFixture(); Object.assign(state.documents[0], invoiceFields); app.setTestState(state);
  const checkbox = new FakeElement('checkbox'); checkbox.dataset.docId = state.documents[0].id; checkbox.checked = true;
  const applied = new FakeElement('document-amount'); applied.value = '4598,04';
  document.querySelectorAll = (selector) => selector.startsWith('#orderDocumentsList [data-doc-id]') ? [checkbox] : [];
  document.querySelector = (selector) => selector.startsWith('[data-doc-amount=') ? applied : null;
  const row = new FakeElement('instrument-row'), fields = {}, summary = new FakeElement('exchange-summary');
  for (const key of ['type', 'amount', 'currency', 'commercialAmount', 'exchangeRate', 'exchangeRateDate', 'exchangeRateReference', 'financialAccountId', 'scheduledDate', 'status', 'reference', 'notes', 'checkNumber', 'bankName']) fields[key] = new FakeElement(key);
  fields.type.value = 'own_check'; fields.currency.value = 'ARS'; fields.financialAccountId.value = 'ACC-NACION-ARS';
  fields.exchangeRateDate.value = '2026-12-17'; fields.scheduledDate.value = '2026-12-17'; row.dataset.currencyTouched = 'true';
  row.querySelector = (selector) => selector === '[data-exchange-summary]' ? summary : fields[selector.match(/^\[data-field="(\w+)"\]$/)?.[1]] || null;
  row.querySelectorAll = () => Object.values(fields);
  app.wireInstrumentRow(row); app.syncInstrumentApplicationFields(row);
  const input = (key, value) => { fields[key].value = value; for (const listener of fields[key].eventListeners.input || []) listener({ currentTarget: fields[key] }); };
  return { app, elements, document, state, row, fields, summary, input };
}

