test('TC factura UI: visible solo en USD opcional y sin formateador que redondee el TC', () => {
  const { app, elements, document } = appVmWithPanelDom(); app.setTestState(emptyState()); app.setupEvents();
  const input = document.getElementById('docInvoiceRate'), field = document.getElementById('docInvoiceRateField');
  let hidden = true; field.classList.toggle = (name, value) => { if (name === 'hidden') hidden = value; };
  for (const currency of ['ARS', 'USD', 'ARS']) {
    elements.get('docCurrency').value = currency;
    for (const handler of elements.get('docCurrency').eventListeners.change) handler();
    assert.equal(hidden, currency !== 'USD'); assert.equal(input.disabled, currency !== 'USD');
  }
  assert.equal(JSON.stringify(app.documentInvoiceRatePayload('USD', '1.500,123456789')), JSON.stringify({ tcInvoice: 1500.123456789 }));
  assert.equal(JSON.stringify(app.documentInvoiceRatePayload('USD', '')), '{}');
  assert.equal(JSON.stringify(app.documentInvoiceRatePayload('ARS', '1500')), '{}');
  assert.throws(() => app.documentInvoiceRatePayload('USD', '-1'), /TC de factura invalido/);
  assert.throws(() => app.documentInvoiceRatePayload('USD', 'invalido'), /TC de factura invalido/);
  const html = fs.readFileSync(path.join(__dirname, 'index.html'), 'utf8');
  assert.match(html, /id="docInvoiceRateField" class="hidden">TC de factura \(ARS\/USD\)/);
  const tag = html.match(/<input id="docInvoiceRate"[^>]*>/)[0];
  assert(!tag.includes('required')); assert(!tag.includes('data-money-input'));
  const source = fs.readFileSync(path.join(__dirname, 'app.js'), 'utf8');
  assert(source.includes("Object.assign(payload, documentInvoiceRatePayload(payload.currency, document.getElementById('docInvoiceRate')?.value))"));
  assert(source.includes("if (form.elements.tcInvoice && changed('tcInvoice')) changes.tcInvoice = invoiceRateInputValue(form.elements.tcInvoice.value)"));
});

test('TC factura: Firestore en memoria guarda cambios y conserva TC en cache recarga backup restore', () => {
  const gateway = new MemoryFirestoreGateway(), writer = firestoreAdapter(gateway), state = invoiceRateFixture(), id = state.documents[0].id;
  writer.writeValidated(state, 1);
  const reader = firestoreAdapter(gateway), first = reader.loadState();
  assert.equal(first.state.documents[0].tcInvoice, 1500);
  assert.equal(reader.loadState().state.documents[0].tcInvoice, 1500); assert.equal(reader.lastReadStats.cacheHit, true);
  const backup = JSON.parse(JSON.stringify(reader.createBackup('invoice-rate-local-test')));
  assert.equal(backup.state.documents[0].tcInvoice, 1500);
  const edited = Core.editDocumentTransaction(first.state, id, { tcInvoice: 1510, reason: 'Dato de prueba' }, 'editor');
  reader.saveState(edited, { expectedVersion: first.stateVersion });
  assert.equal(reader.loadState().state.documents[0].tcInvoice, 1510);
  assert.equal(firestoreAdapter(gateway).loadState().state.documents[0].tcInvoice, 1510);
  const restored = reader.restoreBackup(backup);
  assert.equal(restored.state.documents[0].tcInvoice, 1500); assert.equal(restored.state.documents[0].id, id);
  assert.deepEqual(restored.state.documents, state.documents);
  assert.equal(Core.validateState(restored.state).length, 0);
});

