testAsync('TC factura API local: alta edicion recarga y error conservan documento sin segunda logica', async () => {
  const store = firestoreAdapter(new MemoryFirestoreGateway()); store.writeValidated(emptyState(), 1);
  const doc = invoiceRateFixture().documents[0];
  const created = await callApiForTest({ method: 'POST', url: '/api/transaction', persistence: store, auth: { required: false }, body: { action: 'createDocument', stateVersion: 1, payload: doc } });
  assert.equal(created.status, 200);
  const loaded = store.loadState(), id = loaded.state.documents[0].id;
  assert.equal(loaded.state.documents[0].tcInvoice, 1500);
  const edited = await callApiForTest({ method: 'POST', url: '/api/transaction', persistence: store, auth: { required: false }, body: { action: 'editDocument', id, stateVersion: loaded.stateVersion, changes: { tcInvoice: 1510, reason: 'TC del comprobante confirmado' } } });
  assert.equal(edited.status, 200); assert.equal(store.loadState().state.documents[0].tcInvoice, 1510);
  const before = store.loadState();
  const failed = await callApiForTest({ method: 'POST', url: '/api/transaction', persistence: store, auth: { required: false }, body: { action: 'editDocument', id, stateVersion: before.stateVersion, changes: { tcInvoice: -2, reason: 'Prueba rechazo' } } });
  assert(failed.status >= 400); assert.deepEqual(store.loadState().state, before.state);
  assert.equal(store.loadState().stateVersion, before.stateVersion);
});

function existingOrderLinkFixture(options = {}) {
  let state = emptyState();
  const currency = options.currency || 'ARS';
  const type = options.collection ? 'sale_invoice' : 'purchase_invoice';
  const makeDoc = (number, amount, docCurrency) => {
    state = Core.createDocumentTransaction(state, { type, commercialSide: options.collection ? 'sale' : 'purchase', entityId: 'ENT-PROV-AGRI', number, amount, currency: docCurrency, issueDate: '2026-06-01', dueDate: '2026-12-17', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS', description: 'Fixture de vinculos, no datos reales' }, 'test');
    return state.documents.at(-1).id;
  };
  const sourceId = makeDoc('ORIGEN-LOCAL', options.sourceAmount || 1000, currency);
  const targetId = makeDoc('DESTINO-LOCAL', options.targetAmount || 2000, options.targetCurrency || currency);
  if (currency === 'USD') state.financialAccounts.push({ id: 'ACC-LINK-USD', name: 'Banco USD local', type: 'bank', currency: 'USD', active: true, openingBalance: 0 });
  if (options.instrumentType === 'card_financing') state.financialAccounts.push({ id: 'ACC-LINK-CARD', name: 'Tarjeta local', type: 'card_financing', productType: 'card_financing', currency: 'ARS', active: true, openingBalance: 0 });
  const instrumentType = options.instrumentType || 'transfer';
  state = Core.createOrderTransaction(state, { type: options.collection ? 'collection' : 'payment', date: '2026-06-01', documentId: sourceId, amountApplied: options.sourceAmount || 1000, financialAccountId: currency === 'USD' ? 'ACC-LINK-USD' : 'ACC-NACION-ARS',
    instruments: options.noInstrument ? [] : [{ type: instrumentType, amount: options.instrumentAmount || options.sourceAmount || 1000, currency, status: instrumentType === 'own_check' ? 'issued' : options.realized ? 'executed' : 'scheduled', checkNumber: options.checkNumber || 'LOCAL-LINK', scheduledDate: '2026-12-17', executedDate: options.realized ? '2026-12-17' : null, financialAccountId: options.instrumentType === 'card_financing' ? 'ACC-LINK-CARD' : currency === 'USD' ? 'ACC-LINK-USD' : 'ACC-NACION-ARS' }] }, 'test');
  if (options.realized && instrumentType === 'own_check') state = Core.transitionInstrument(state, state.instruments[0].id, 'debited', '2026-12-17', 'test');
  assert.equal(Core.validateState(state).length, 0);
  return { state, sourceId, targetId };
}

function existingOrderLinkPayloadForTest(fixture, changes = {}) {
  const source = fixture.state.orderDocuments[0];
  return { orderId: source.orderId, sourceOrderDocumentId: source.id, documentId: fixture.targetId,
    expectedSourceDocumentId: source.documentId, expectedSourceAmount: source.amountApplied,
    amountApplied: source.amountApplied, reason: 'Vinculo historico confirmado en prueba local', ...changes };
}

function assertLinkPaymentsUnchanged(before, after) {
  assert.deepEqual(after.documents, before.documents);
  assert.deepEqual(after.instruments, before.instruments);
  assert.deepEqual(after.bankCharges, before.bankCharges);
  assert.deepEqual(Core.financialMovementRows(after), Core.financialMovementRows(before));
  assert.deepEqual(Core.accountBalances(after), Core.accountBalances(before));
  assert.deepEqual(Core.economicDocumentRows(after), Core.economicDocumentRows(before));
  assert.equal(after.orders.length, before.orders.length);
  assert.equal(Core.validateState(after).length, 0);
}

