testAsync('Vincular API local: commit unico, version vieja y fallo de validacion no dejan escritura parcial', async () => {
  const fixture = existingOrderLinkFixture(), store = new JsonPersistenceAdapter({ root: tempPersistenceRoot(), environment: 'demo', Core }); store.writeValidated(fixture.state, 1);
  const payload = existingOrderLinkPayloadForTest(fixture);
  const send = (body) => callApiForTest({ method: 'POST', url: '/api/transaction', persistence: store, auth: { required: false }, body });
  const rejected = await send({ action: 'linkExistingOrder', stateVersion: 1, payload: { ...payload, amountApplied: 2001 } });
  assert(rejected.status >= 400); assert.deepEqual(store.loadState().state, fixture.state); assert.equal(store.loadState().stateVersion, 1);
  const result = await send({ action: 'linkExistingOrder', stateVersion: 1, payload });
  assert.equal(result.status, 200); assert.equal(store.loadState().stateVersion, 2);
  const after = store.loadState(), stale = await send({ action: 'linkExistingOrder', stateVersion: 1, payload });
  assert.equal(stale.status, 409); assert.deepEqual(store.loadState().state, after.state); assert.equal(store.loadState().stateVersion, 2);
});

