function fourExistingOrdersFixture(targetAmount = 4000) {
  const fixture = existingOrderLinkFixture({ targetAmount });
  const links = [existingOrderLinkPayloadForTest(fixture)];
  for (let index = 2; index <= 4; index++) {
    fixture.state = Core.createDocumentTransaction(fixture.state, { type: 'purchase_invoice', commercialSide: 'purchase', entityId: 'ENT-PROV-AGRI', number: `ORIGEN-LOCAL-${index}`, amount: 1000, currency: 'ARS', issueDate: '2026-06-01', dueDate: '2026-12-17', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS', description: 'Origen local para prueba atomica' }, 'test');
    const sourceId = fixture.state.documents.at(-1).id;
    fixture.state = Core.createOrderTransaction(fixture.state, { type: 'payment', date: `2026-06-0${index}`, documentId: sourceId, amountApplied: 1000,
      instruments: [{ type: 'transfer', amount: 1000, currency: 'ARS', status: 'scheduled', scheduledDate: '2026-12-17', reference: `REF-LOCAL-${index}`, financialAccountId: 'ACC-NACION-ARS' }] }, 'test');
    const source = fixture.state.orderDocuments.at(-1);
    links.push({ orderId: source.orderId, sourceOrderDocumentId: source.id, documentId: fixture.targetId,
      expectedSourceDocumentId: source.documentId, expectedSourceAmount: source.amountApplied, amountApplied: 1000 });
  }
  assert.equal(Core.validateState(fixture.state).length, 0);
  return { ...fixture, payload: { links, reason: 'Conciliacion conjunta de prueba' } };
}

