function inferredDocumentCleanupFixture() {
  const fixture = deliveredMicrovidasLinkFixture();
  const source = fixture.state.documents.find((item) => item.id === fixture.sourceId);
  const target = fixture.state.documents.find((item) => item.id === fixture.targetId);
  source.type = 'no_receipt'; source.fiscalStatus = 'no_receipt'; source.taxComponents = [];
  source.migration = { inferred: true, sourceCollection: 'orders', sourceId: 'OLD-ORDER-LOCAL',
    sourceOrderNumber: 'OP-LOCAL', reason: 'Documento referido incompatible; se crea documento operativo inferido para dry-run V3.' };
  target.migration = { inferred: false, sourceCollection: 'invoices', sourceId: 'OLD-INVOICE-LOCAL' };
  fixture.state.orders[0].migration = { sourceCollection: 'orders', sourceId: 'OLD-ORDER-LOCAL' };
  fixture.state.auditLog = fixture.state.auditLog.filter((entry) => !(entry.entityType === 'document' && entry.entityId === fixture.sourceId && entry.action === 'create-document'));
  assert.equal(Core.validateState(fixture.state).length, 0);
  return fixture;
}

