test('Limpieza protegida Microvidas local: retira saldo artificial sin tocar factura, OP, cheque ni Banco', () => {
  const fixture = inferredDocumentCleanupFixture();
  const linked = Core.linkExistingOrderTransaction(fixture.state, fixture.payload, 'test');
  const before = cloneForTest(linked), bankBefore = Core.financialMovementRows(linked);
  assert.equal(Core.flowRows(linked).filter((item) => item.documentId === fixture.sourceId && item.source === 'document-balance').length, 1);
  const cleaned = Core.cleanupArtificialDocumentTransaction(linked, fixture.sourceId, 'Factura real localizada y pago reasignado', 'operador-local');
  assert.equal(cleaned.documents.length, before.documents.length);
  assert(cleaned.documents.find((item) => item.id === fixture.sourceId).voidedAt);
  assert.deepEqual(cleaned.documents.find((item) => item.id === fixture.targetId), before.documents.find((item) => item.id === fixture.targetId));
  assert.deepEqual(cleaned.orders, before.orders);
  assert.deepEqual(cleaned.instruments, before.instruments);
  assert.deepEqual(cleaned.orderDocuments, before.orderDocuments);
  assert.deepEqual(cleaned.orderInstruments, before.orderInstruments);
  assert.deepEqual(cleaned.orderDocumentSettlements, before.orderDocumentSettlements);
  assert.deepEqual(cleaned.bankCharges, before.bankCharges);
  assert.deepEqual(Core.financialMovementRows(cleaned), bankBefore);
  assert.equal(Core.flowRows(cleaned).filter((item) => item.documentId === fixture.sourceId).length, 0);
  assert.equal(Core.flowRows(cleaned).filter((item) => item.instrumentId === before.instruments[0].id).length, 1);
  assert.equal(Core.flowRows(cleaned).filter((item) => item.documentId === fixture.targetId && item.source === 'document-balance').length, 0);
  assert.equal(Core.documentBreakdown(cleaned, fixture.targetId).instrumentedFinancialPending, 4598.04);
  assert.equal(Core.documentBreakdown(cleaned, fixture.targetId).commercialCancelled, 4598.04);
  assert(!Core.economicDocumentRows(cleaned).some((item) => item.documentId === fixture.sourceId));
  const audit = cleaned.auditLog[0];
  assert.equal(audit.action, 'cleanup-inferred-document'); assert.equal(audit.user, 'operador-local'); assert(audit.createdAt);
  assert.equal(audit.changes[0].from.id, fixture.sourceId); assert.equal(audit.changes[0].from.voidedAt, null);
  assert.equal(audit.changes[1].to[0].targetDocumentId, fixture.targetId);
  assert.equal(cleaned.auditLog[1].action, 'link-existing-order');
  assert.equal(Core.validateState(cleaned).length, 0);
});

