testAsync('Eliminar documento C por API local es atómico, versionado y no toca medios', async () => {
  const fixture = etchevehereOriginCleanupFixture(), linked = Core.linkExistingOrderTransaction(fixture.state, fixture.payload, 'test');
  const store = new JsonPersistenceAdapter({ root: tempPersistenceRoot(), environment: 'demo', Core });
  store.writeValidated(linked, 1);
  const send = (id, version, reason) => callApiForTest({ method: 'POST', url: '/api/transaction', persistence: store, auth: { required: false },
    body: { action: 'deleteDocument', id, reason, stateVersion: version } });
  const rejected = await send(fixture.sourceId, 1, '');
  assert(rejected.status >= 400); assert.deepEqual(store.loadState().state, linked);
  const accepted = await send(fixture.sourceId, 1, 'Conciliación local auditada');
  assert.equal(accepted.status, 200); assert.equal(store.loadState().stateVersion, 2);
  const after = store.loadState().state;
  assert(after.documents.find((item) => item.id === fixture.sourceId).voidedAt);
  assert.deepEqual(after.orders, linked.orders); assert.deepEqual(after.instruments, linked.instruments);
  assert.deepEqual(Core.financialMovementRows(after), Core.financialMovementRows(linked));
  assert.equal(Core.validateState(after).length, 0);
  const stale = await send(fixture.sourceId, 1, 'Repetición'); assert.equal(stale.status, 409);
});

test('Panel: proximos horizontes son acumulativos, concilian con sus filas y no mezclan monedas', () => {
  const state = fresh(), baseDate = Core.todayIso();
  state.instruments[1].scheduledDate = Core.addDays(baseDate, 2);
  state.estimates.push({ id: 'EST-PANEL-ARS', active: true, date: Core.addDays(baseDate, 3), direction: 'in', amount: 123.45, currency: 'ARS', activity: 'Agricultura', description: 'Estimacion ARS' });
  state.estimates.push({ id: 'EST-PANEL-USD', active: true, date: Core.addDays(baseDate, 4), direction: 'in', amount: 90.12, currency: 'USD', activity: 'Agricultura', description: 'Estimacion USD' });
  const windows = Core.panelUpcomingWindows(state, { baseDate });
  for (const currency of ['ARS', 'USD']) {
    const periods = [7, 15, 30].map((days) => windows.find((item) => item.days === days && item.currency === currency));
    for (const period of periods) {
      assert(period.rows.every((row) => row.currency === currency && row.date <= period.dateTo && ['Pendiente', 'Estimado'].includes(row.userStatus)));
      assert(period.overdueRows.every((row) => row.date < baseDate));
      assert(period.horizonRows.every((row) => row.date >= baseDate && row.date <= period.dateTo));
      assert.equal(period.rows.length, period.overdueRows.length + period.horizonRows.length);
      assert.equal(period.income, period.overdueIncome + period.horizonIncome);
      assert.equal(period.expense, period.overdueExpense + period.horizonExpense);
      assert.equal(Core.flowTotals(period.rows).incomes, period.income);
      assert.equal(Core.flowTotals(period.rows).expenses, period.expense);
      assert.equal(new Set(period.rows.map((row) => row.id)).size, period.rows.length);
    }
    assert(periods[0].rows.every((row) => periods[1].rows.some((later) => later.id === row.id)));
    assert(periods[1].rows.every((row) => periods[2].rows.some((later) => later.id === row.id)));
  }
  assert(windows.find((item) => item.days === 7 && item.currency === 'ARS').rows.some((row) => row.id === 'EST-PANEL-ARS' && row.userStatus === 'Estimado'));
  assert(windows.find((item) => item.days === 7 && item.currency === 'USD').rows.some((row) => row.id === 'EST-PANEL-USD' && row.userStatus === 'Estimado'));
});

