function panelInstrumentActionFixture(direction, date = Core.addDays(Core.todayIso(), 2)) {
  const amount = direction === 'in' ? 1200 : 1000;
  const number = direction === 'in' ? 'PANEL-COBRO' : 'PANEL-PAGO';
  let state = fresh();
  state = Core.createDocumentTransaction(state, { type: direction === 'in' ? 'sale_invoice' : 'purchase_invoice', commercialSide: direction === 'in' ? 'sale' : 'purchase', entityId: direction === 'in' ? 'ENT-CLIENTE-DEMO' : 'ENT-PROV-AGRI', number, amount, currency: 'ARS', issueDate: date, dueDate: date, activity: 'Agricultura', chartAccountId: direction === 'in' ? 'CA-AGRI' : 'CA-AGRI-INS', description: number }, 'test');
  const documentId = state.documents.at(-1).id;
  state = Core.createOrderTransaction(state, { type: direction === 'in' ? 'collection' : 'payment', documentId, amountApplied: amount, financialAccountId: 'ACC-GALICIA-ARS', instruments: [{ type: 'transfer', amount, scheduledDate: date, status: 'scheduled', reference: number }] }, 'test');
  return { state, documentId, orderId: state.orders.at(-1).id, instrumentId: state.instruments.at(-1).id, amount, date, direction };
}

testAsync('Panel: pago y cobro usan la misma accion protegida de Flujo y actualizan horizonte sin duplicar', async () => {
  for (const direction of ['out', 'in']) {
    const fixture = panelInstrumentActionFixture(direction);
    const { state: before, instrumentId, date, amount } = fixture;
    const counts = { documents: before.documents.length, orders: before.orders.length, instruments: before.instruments.length, settlements: before.orderDocumentSettlements.length };
    let requests = 0, serverState = before, lastBody;
    const { app, elements, document } = appVmWithFlowDom({ fetch: async (url, options) => {
      requests++;
      lastBody = JSON.parse(options.body);
      serverState = Core.transitionInstrument(serverState, lastBody.instrumentId, lastBody.status, lastBody.date, 'panel-test');
      return { status: 200, text: async () => JSON.stringify({ ok: true, state: serverState, validation: [], stateVersion: requests + 1, environment: 'local' }) };
    } });
    document.getElementById('dateActionInput').focus = () => {};
    app.setTestState(before);
    app.renderPanel();
    app.openPanelUpcomingDetail({ days: 7, currency: 'ARS', direction });
    app.setupEvents();
    const mode = elements.get('panelUpcomingDetailMode');
    if (direction === 'in') {
      mode.value = 'all';
      mode.eventListeners.change[0]({ target: mode });
    }
    const target = { days: 7, currency: 'ARS', direction };
    const beforeRows = app.panelUpcomingDetailRows(target);
    const index = beforeRows.findIndex((row) => row.instrumentId === instrumentId);
    assert(index >= 0);
    const table = elements.get('panelUpcomingDetailTable');
    const actions = table.tBody.children[index].children[9].children[0].children;
    assert.equal(actions[0].textContent, direction === 'in' ? 'Marcar cobrado' : 'Marcar pagado');
    assert.equal(app.flowInstrumentAction(before.instruments.find((item) => item.id === instrumentId)).label, actions[0].textContent);
    const beforeTotal = Core.panelUpcomingWindows(before, { baseDate: Core.todayIso(), currency: 'ARS' }).find((row) => row.days === 7);
    const pending = actions[0].click();
    assert.equal(elements.get('dateActionInput').value, date);
    await app.submitDateAction({ currentTarget: document.getElementById('dateActionForm'), preventDefault() {} });
    await pending;
    assert.equal(requests, 1);
    assert.equal(lastBody.action, 'transitionInstrument');
    assert.equal(lastBody.instrumentId, instrumentId);
    assert.equal(lastBody.date, date);
    const current = app.getTestState();
    assert.equal(current.instruments.find((item) => item.id === instrumentId).status, 'executed');
    for (const [key, length] of Object.entries(counts)) assert.equal(current[key === 'settlements' ? 'orderDocumentSettlements' : key].length, length);
    assert(current.auditLog.length > before.auditLog.length);
    assert.equal(Core.validateState(current).length, 0);
    if (direction === 'out') assert(!app.panelUpcomingDetailRows(target).some((row) => row.instrumentId === instrumentId));
    else {
      assert.equal(mode.value, 'all');
      assert(app.panelUpcomingDetailRows(target).some((row) => row.instrumentId === instrumentId && row.userStatus === 'Cobrado'));
    }
    const afterTotal = Core.panelUpcomingWindows(current, { baseDate: Core.todayIso(), currency: 'ARS' }).find((row) => row.days === 7);
    assert.equal(direction === 'in' ? beforeTotal.income - afterTotal.income : beforeTotal.expense - afterTotal.expense, amount);
    for (const days of [7, 15, 30]) {
      const beforeWindow = Core.panelUpcomingWindows(before, { baseDate: Core.todayIso(), currency: 'ARS' }).find((row) => row.days === days);
      const afterWindow = Core.panelUpcomingWindows(current, { baseDate: Core.todayIso(), currency: 'ARS' }).find((row) => row.days === days);
      assert.equal(direction === 'in' ? beforeWindow.income - afterWindow.income : beforeWindow.expense - afterWindow.expense, amount);
    }
    assert.equal(elements.get('panelUpcomingDetailTitle').textContent.includes('7 dias · ARS'), true);
    mode.value = 'all';
    mode.eventListeners.change[0]({ target: mode });
    assert(app.panelUpcomingDetailRows(target).some((row) => row.instrumentId === instrumentId && row.userStatus === (direction === 'in' ? 'Cobrado' : 'Pagado')));
    assert.equal(elements.get('panelUpcomingDetailTotals').textContent.includes(formatLikeApp(afterTotal[direction === 'in' ? 'income' : 'expense'], 'ARS')), true);
    mode.value = 'pending';
    mode.eventListeners.change[0]({ target: mode });
    assert(!app.panelUpcomingDetailRows(target).some((row) => row.instrumentId === instrumentId));
  }
});

testAsync('Panel: pago vencido reduce Pendientes anteriores sin mover fecha ni afectar USD', async () => {
  const dueDate = Core.addDays(Core.todayIso(), -5);
  const fixture = panelInstrumentActionFixture('out', dueDate);
  let serverState = fixture.state, requests = 0;
  const { app, elements, document } = appVmWithFlowDom({ fetch: async (url, options) => {
    requests++;
    const body = JSON.parse(options.body);
    serverState = Core.transitionInstrument(serverState, body.instrumentId, body.status, body.date, 'panel-test');
    return { status: 200, text: async () => JSON.stringify({ ok: true, state: serverState, validation: [], stateVersion: 2, environment: 'local' }) };
  } });
  document.getElementById('dateActionInput').focus = () => {};
  app.setTestState(fixture.state);
  app.renderPanel();
  app.openPanelUpcomingDetail({ days: 15, currency: 'ARS', direction: 'out' });
  const target = { days: 15, currency: 'ARS', direction: 'out' };
  const before = Core.panelUpcomingWindows(fixture.state, { baseDate: Core.todayIso() });
  const index = app.panelUpcomingDetailRows(target).findIndex((row) => row.instrumentId === fixture.instrumentId);
  assert(index >= 0);
  const button = elements.get('panelUpcomingDetailTable').tBody.children[index].children[9].children[0].children[0];
  button.click();
  elements.get('dateActionInput').value = Core.todayIso();
  await app.submitDateAction({ currentTarget: document.getElementById('dateActionForm'), preventDefault() {} });
  assert.equal(requests, 1);
  const after = Core.panelUpcomingWindows(app.getTestState(), { baseDate: Core.todayIso() });
  for (const days of [7, 15, 30]) {
    const prior = before.find((row) => row.currency === 'ARS' && row.days === days);
    const current = after.find((row) => row.currency === 'ARS' && row.days === days);
    assert.equal(prior.overdueExpense - current.overdueExpense, fixture.amount);
    assert.equal(prior.expense - current.expense, fixture.amount);
    const usdPrior = before.find((row) => row.currency === 'USD' && row.days === days);
    const usdCurrent = after.find((row) => row.currency === 'USD' && row.days === days);
    assert.deepEqual({ income: usdPrior.income, expense: usdPrior.expense }, { income: usdCurrent.income, expense: usdCurrent.expense });
  }
  assert.equal(app.getTestState().instruments.find((item) => item.id === fixture.instrumentId).scheduledDate, dueDate);
  assert.equal(elements.get('panelUpcomingDetailTitle').textContent.includes('15 dias · ARS'), true);
  assert(!app.panelUpcomingDetailRows(target).some((row) => row.instrumentId === fixture.instrumentId));
  assert.equal(Core.validateState(app.getTestState()).length, 0);
});

