testAsync('Guardado HTTP: error confirmado permite corregir; respuesta perdida es incierta y no reenvia', async () => {
  let calls = 0;
  const { app } = appVmWithPanelDom({ fetch: async () => {
    calls++;
    if (calls === 1) return { status: 400, text: async () => JSON.stringify({ ok: false, error: 'Importe invalido' }) };
    return { status: 200, text: async () => { throw new Error('Conexion interrumpida después del commit'); } };
  } });
  await assert.rejects(() => app.postTransaction({ action: 'createDocument' }), /Importe invalido/);
  await assert.rejects(() => app.postTransaction({ action: 'createDocument' }), /No llegó la confirmación/);
  await assert.rejects(() => app.postTransaction({ action: 'createDocument' }), /Hay un guardado sin confirmación/);
  assert.equal(calls, 2);
});

