testAsync('Documento incierto: verificación de estado no reenvía escritura y reconoce el ID confirmado', async () => {
  const source = fresh(), id = 'DOC-VERIFY-LOCAL';
  const confirmed = cloneForTest(source);
  confirmed.documents.push({ ...source.documents[0], id, number: 'VERIFY-LOCAL', taxComponents: [] });
  const storage = new Map([['sagro-admin-v1-uncertain-document', id]]);
  let reads = 0, writes = 0;
  const { app, elements } = appVmWithPanelDom({
    sessionStorage: { getItem: (key) => storage.get(key), setItem: (key, value) => storage.set(key, value), removeItem: (key) => storage.delete(key) },
    fetch: async (url, options) => {
      if (options?.method === 'POST') writes++;
      else reads++;
      return { status: 200, text: async () => JSON.stringify({ ok: true, state: reads < 3 ? source : confirmed, validation: [], stateVersion: reads, environment: 'local' }) };
    }
  });
  await app.load();
  assert.match(elements.get('documentSaveFeedback').textContent, /Verificar guardado/);
  await assert.rejects(() => app.postTransaction({ action: 'createDocument' }), /sin confirmación/);
  await app.verifyUncertainDocumentSave();
  assert.match(elements.get('documentSaveFeedback').textContent, /aún no aparece/);
  assert.match(elements.get('documentSaveFeedback').textContent, /escrituras permanecen bloqueadas/);
  elements.get('docDescription').value = 'Conservar borrador';
  app.cleanDocumentForm();
  assert.equal(elements.get('docDescription').value, 'Conservar borrador');
  await assert.rejects(() => app.postTransaction({ action: 'createDocument' }), /sin confirmación/);
  await app.verifyUncertainDocumentSave();
  assert.equal(storage.has('sagro-admin-v1-uncertain-document'), false, elements.get('documentSaveFeedback').textContent);
  assert.equal(writes, 0);
  assert.equal(app.getTestState().documents.some((item) => item.id === id), true);
});

