testAsync('Flujo: transición local persiste una vez y expone etapas sin segunda lectura completa', async () => {
  const state = agroFresh(), gateway = new MemoryFirestoreGateway(), persistence = firestoreAdapter(gateway);
  persistence.writeValidated(state, 1);
  persistence.loadState();
  const instrument = state.instruments.find((item) => item.type === 'own_check' && item.status === 'delivered');
  const result = await callApiForTest({ method: 'POST', url: '/api/transaction', persistence, auth: { required: false },
    body: { action: 'transitionInstrument', instrumentId: instrument.id, status: 'debited', date: '2026-10-01', stateVersion: 1 } });
  assert.equal(result.status, 200);
  assert.equal(result.payload.stateVersion, 2);
  assert.equal(result.payload.performance.cacheHit, true);
  assert.equal(result.payload.performance.collectionsRead, 0);
  assert.equal(result.payload.performance.docsRead, 2);
  assert.equal(result.payload.performance.batchesFirestore, 1);
  assert.equal(result.payload.performance.writesFirestore, 3);
  assert.equal(result.payload.performance.persistMs,
    result.payload.performance.changeMetricsMs + result.payload.performance.saveRecordMs);
  assert(result.payload.performance.firestoreCommitMs <= result.payload.performance.saveRecordMs);
  assert(result.payload.performance.transactionMetaReadMs >= 0);
  assert(result.payload.performance.transactionFinalizeMs >= 0);
  assert(result.payload.performance.responseBytes > 0);
  assert(result.payload.performance.createdIdsMs >= 0);
  assert.equal(result.payload.performance.postPersistReadMs, 0);
  assert.equal(result.payload.state.instruments.find((item) => item.id === instrument.id).status, 'debited');
  assert.equal(result.payload.state.documents.length, state.documents.length);
  assert.equal(Core.validateState(result.payload.state).length, 0);
});

testAsync('Guardado HTTP: comprime respuesta grande sin cambiar estado ni repetir la transacción', async () => {
  const state = agroFresh(), gateway = new MemoryFirestoreGateway(), persistence = firestoreAdapter(gateway);
  persistence.writeValidated(state, 1);
  persistence.loadState();
  const instrument = state.instruments.find((item) => item.type === 'own_check' && item.status === 'delivered');
  const request = fakeHttpRequest('POST', '/api/transaction', {
    action: 'transitionInstrument', instrumentId: instrument.id, status: 'debited', date: '2026-10-01', stateVersion: 1
  }, { 'accept-encoding': 'gzip, deflate' });
  const response = await new Promise((resolve) => {
    const res = {
      writeHead(status, headers) { this.status = status; this.headers = headers; },
      end(body) { resolve({ status: this.status, headers: this.headers, body }); }
    };
    handleApi(request, res, persistence, { required: false });
  });
  assert.equal(response.status, 200);
  assert.equal(response.headers['Content-Encoding'], 'gzip');
  const uncompressed = zlib.gunzipSync(response.body);
  const payload = JSON.parse(uncompressed.toString('utf8'));
  assert.equal(uncompressed.toString('utf8'), JSON.stringify(payload));
  assert(response.body.length < uncompressed.length);
  assert.equal(payload.performance.docsRead, 2);
  assert.equal(payload.stateVersion, 2);
  assert.equal(payload.state.instruments.find((item) => item.id === instrument.id).status, 'debited');
  assert.equal(payload.state.auditLog.length, state.auditLog.length + 1);
  assert.equal(Core.validateState(payload.state).length, 0);
  assert.equal(gateway.writeLog.filter((entry) => entry.path.endsWith('/meta/current')).length, 2);
});

testAsync('API: gzip conserva contenido exacto en lectura, error y conflicto de version', async () => {
  const gateway = new MemoryFirestoreGateway(), persistence = firestoreAdapter(gateway);
  persistence.writeValidated(agroFresh(), 1);
  persistence.loadState();
  gateway.writeLog = [];
  const requestCases = [
    { name: 'lectura', method: 'GET', url: '/api/state', status: 200 },
    { name: 'error', method: 'POST', url: '/api/transaction', body: { action: 'accion-inexistente', stateVersion: 1 }, status: 400 },
    { name: 'conflicto', method: 'POST', url: '/api/transaction', body: { action: 'createEntity', stateVersion: 0 }, status: 409 }
  ];
  for (const item of requestCases) {
    const plain = await callRawApiForTest({ ...item, persistence });
    const zipped = await callRawApiForTest({ ...item, persistence, headers: { 'accept-encoding': 'gzip, deflate' } });
    assert.equal(plain.status, item.status, item.name);
    assert.equal(zipped.status, item.status, item.name);
    assert.equal(plain.headers['Content-Encoding'], undefined, item.name);
    assert.equal(zipped.headers['Content-Encoding'], 'gzip', item.name);
    assert.equal(zipped.headers.Vary, 'Accept-Encoding', item.name);
    assert.equal(responseTextForTest(zipped), responseTextForTest(plain), item.name);
  }
  const disabled = await callRawApiForTest({ persistence, headers: { 'accept-encoding': 'gzip;q=0, identity' } });
  const plainState = await callRawApiForTest({ persistence });
  assert.equal(disabled.headers['Content-Encoding'], undefined);
  assert.equal(responseTextForTest(disabled), responseTextForTest(plainState));
  assert.equal(gateway.writeLog.length, 0);
});

testAsync('Guardado incierto: verificacion gzip relee el mismo estado sin reenviar ni escribir', async () => {
  const state = agroFresh(), gateway = new MemoryFirestoreGateway(), persistence = firestoreAdapter(gateway);
  persistence.writeValidated(state, 1);
  persistence.loadState();
  const instrument = state.instruments.find((item) => item.type === 'own_check' && item.status === 'delivered');
  const saved = await callRawApiForTest({ method: 'POST', url: '/api/transaction', persistence,
    headers: { 'accept-encoding': 'gzip' }, body: {
      action: 'transitionInstrument', instrumentId: instrument.id, status: 'debited', date: '2026-10-01', stateVersion: 1
    } });
  assert.equal(saved.status, 200);
  assert.equal(saved.headers['Content-Encoding'], 'gzip');
  const confirmed = JSON.parse(responseTextForTest(saved));
  assert.equal(confirmed.stateVersion, 2);
  gateway.writeLog = [];
  const plain = await callRawApiForTest({ persistence });
  const zipped = await callRawApiForTest({ persistence, headers: { 'accept-encoding': 'gzip' } });
  assert.equal(zipped.headers['Content-Encoding'], 'gzip');
  assert.equal(responseTextForTest(zipped), responseTextForTest(plain));
  const verified = JSON.parse(responseTextForTest(zipped));
  assert.deepEqual(verified.state, confirmed.state);
  assert.equal(verified.stateVersion, 2);
  assert.equal(verified.state.instruments.find((item) => item.id === instrument.id).status, 'debited');
  assert.equal(gateway.writeLog.length, 0);
});

