testAsync('Guardado UI: informa tiempos de render por modulo sin otra petición', async () => {
  const state = agroFresh();
  let requests = 0, metrics;
  const { app } = appVmWithPanelDom({
    console: { ...console, info(tag, value) { if (tag === '[sagro-save-performance]') metrics = JSON.parse(value); } },
    fetch: async () => {
      requests += 1;
      return { status: 200, text: async () => JSON.stringify({ ok: true, state, validation: [], stateVersion: 2, environment: 'demo' }) };
    }
  });
  app.setTestState(state);
  await app.postTransaction({ action: 'transitionInstrument', instrumentId: 'INS-LOCAL' });
  assert.equal(requests, 1);
  assert(metrics.renderStagesMs.flow >= 0);
  assert(metrics.renderStagesMs.operations >= 0);
  assert(metrics.renderStagesMs.treasury >= 0);
  assert(metrics.responseChars > 0);
});

