test('Entrada decimal acepta punto o coma sin confundir agrupadores de miles', () => {
  const { app } = appVmWithPanelDom();
  const input = new FakeElement('docNetTaxed');
  input.type = 'number';
  app.wireMoneyInput(input);
  assert.equal(input.type, 'text');
  for (const raw of ['1250.50', '1250,50', '1.250,50', '1,250.50']) {
    input.value = raw;
    input.eventListeners.input[0]();
    assert.equal(input.value, raw);
    assert.equal(app.parseLocaleNumber(input.value), 1250.5);
    input.eventListeners.blur[0]();
    assert.equal(input.value, '1.250,50');
    input.eventListeners.focus[0]();
    assert.equal(input.value, '1250,50');
  }
  assert.equal(app.formatArgentineMoneyInput('1.250.'), '1.250,');
  assert.equal(app.parseLocaleNumber('1.250'), 1250);
  assert.equal(app.parseLocaleNumber('1250.50'), 1250.5);
  assert.equal(app.parseLocaleNumber('1250,50'), 1250.5);
  assert.equal(app.parseLocaleNumber('1476.125'), 1476.125);
  assert(Number.isNaN(app.parseLocaleNumber('1.2.3')));
  assert(Number.isNaN(app.parseLocaleNumber('1,2,3')));
  for (const id of ['grainOpPrice', 'livestockOpPriceKg', 'livestockOpCommissionPercent', 'exchangeRate']) {
    const decimal = new FakeElement(id);
    decimal.type = 'number';
    decimal.step = id === 'livestockOpPriceKg' ? 'any' : '0.01';
    app.wireDecimalNumberInput(decimal);
    assert.equal(decimal.type, 'text');
    decimal.value = '1476,125';
    decimal.eventListeners.input[0]();
    assert.equal(Number(decimal.value), 1476.125);
    decimal.value = '1476.125';
    decimal.eventListeners.input[0]();
    assert.equal(Number(decimal.value), 1476.125);
    decimal.value = '1.476,1250';
    decimal.eventListeners.input[0]();
    assert.equal(decimal.value, '1476.1250');
  }
  const heads = new FakeElement('livestockOpHeads');
  heads.type = 'number';
  heads.step = '1';
  app.wireDecimalNumberInput(heads);
  assert.equal(heads.type, 'number');
});

test('Importes: cada tecla conserva el entero antes de aplicar separadores de miles', () => {
  const { app } = appVmWithPanelDom();
  const cases = [
    ['30816,21', 30816.21, '30.816,21'], ['30816.21', 30816.21, '30.816,21'],
    ['3,08', 3.08, '3,08'], ['3.08', 3.08, '3,08'], ['30816', 30816, '30.816,00'],
    ['123456789,87', 123456789.87, '123.456.789,87']
  ];
  for (const id of ['docNetTaxed', 'docTotalAmount', 'editFiscalAmount', 'orderAmount', 'instrumentAmount', 'grainOpNetTaxed', 'livestockOpNetTaxed']) {
    const input = new FakeElement(id); input.type = 'number'; app.wireMoneyInput(input);
    for (const [typed, expected, displayed] of cases) {
      input.value = '';
      for (const [index, character] of [...typed].entries()) {
        input.value += character;
        input.eventListeners.input.forEach((handler) => handler({ target: input }));
        assert.equal(input.value, typed.slice(0, index + 1), `${id}: ${typed} debe conservar las teclas`);
      }
      assert.equal(input.value, typed, `${id}: texto completo`);
      assert.equal(app.parseLocaleNumber(input.value), expected, `${id}: valor antes de blur`);
      input.eventListeners.blur[0]();
      assert.equal(input.value, id.startsWith('doc') ? displayed : displayed.replace(/,00$/, ''), `${id}: valor presentado`);
      input.eventListeners.focus[0]();
      assert.equal(app.parseLocaleNumber(input.value), expected, `${id}: valor al reabrir`);
    }
  }
  for (const text of ['1.250,50', '1,250.50']) {
    const input = new FakeElement('docTotalAmount'); input.type = 'number'; app.wireMoneyInput(input);
    input.value = text; input.eventListeners.input[0]();
    assert.equal(app.parseLocaleNumber(input.value), 1250.5);
    input.eventListeners.blur[0](); assert.equal(input.value, '1.250,50');
  }
  const resumed = new FakeElement('docNetTaxed'); resumed.type = 'text'; app.wireMoneyInput(resumed);
  resumed.value = '3.081'; resumed.eventListeners.focus[0]();
  assert.equal(resumed.value, '3081');
  resumed.value += '6'; resumed.eventListeners.input[0]();
  assert.equal(resumed.value, '30816');
  assert.equal(app.parseLocaleNumber(resumed.value), 30816);
});

