function erroneousCollectionCompensationFixture() {
  let state = fresh();
  const entityId = 'ENT-PROV-AGRI';
  state = Core.createDocumentTransaction(state, { type: 'settlement', commercialSide: 'sale', entityId, number: 'LIQ-CEREAL-LOCAL', amount: 2294550.61, currency: 'ARS', issueDate: '2026-07-22', dueDate: '2026-07-22', activity: 'Agricultura', chartAccountId: 'CA-AGRI', description: 'Liquidación cereal' }, 'test');
  const creditDocumentId = state.documents.at(-1).id;
  state = Core.createDocumentTransaction(state, { type: 'purchase_invoice', entityId, number: '00561-00007734', amount: 2294561.59, currency: 'ARS', issueDate: '2026-07-22', dueDate: '2026-07-22', activity: 'Agricultura', chartAccountId: 'CA-AGRI-INS', description: 'Gasoil Diesel 500' }, 'test');
  const debtDocumentId = state.documents.at(-1).id;
  state = Core.createOrderTransaction(state, { type: 'collection', documentId: creditDocumentId, amountApplied: 2294550.61, date: '2026-07-22', financialAccountId: 'ACC-GALICIA-ARS', instruments: [{ type: 'transfer', amount: 2294550.61, scheduledDate: '2026-07-23', status: 'scheduled', reference: 'COBRO-ERRONEO-LOCAL' }] }, 'test');
  const orderId = state.orders.at(-1).id;
  const instrumentId = state.instruments.at(-1).id;
  state = Core.transitionInstrument(state, instrumentId, 'executed', '2026-07-23', 'test');
  const payload = { creditDocumentId, debtDocumentId, instrumentId, amount: 2294550.61, date: '2026-07-24', reference: 'COMP-LOCAL', reason: 'El cobro fue una compensación, no una transferencia' };
  assert.deepEqual(Core.validateState(state), []);
  return { state, payload, creditDocumentId, debtDocumentId, orderId, instrumentId };
}

test('Corregir cobro y compensar: caso cereal/gasoil deja $10,98, sin banco ni duplicados', () => {
  const fixture = erroneousCollectionCompensationFixture();
  const { state, payload, creditDocumentId, debtDocumentId, orderId, instrumentId } = fixture;
  const before = JSON.stringify(state);
  const bankBefore = Core.accountBalances(state).find((item) => item.id === 'ACC-GALICIA-ARS').realBalance;
  const economicBefore = Core.economicDocumentRows(state);
  const counts = { documents: state.documents.length, orders: state.orders.length, instruments: state.instruments.length, settlements: state.orderDocumentSettlements.length };
  const next = Core.correctCollectionAndCompensateTransaction(state, payload, 'auditor');
  assert.equal(JSON.stringify(state), before);
  assert.equal(Core.documentBreakdown(next, creditDocumentId).commercialCancelled, 2294550.61);
  assert.equal(Core.documentBreakdown(next, creditDocumentId).nonInstrumented, 0);
  assert.equal(Math.round(Core.documentBreakdown(next, debtDocumentId).nonInstrumented * 100), 1098);
  assert.equal(next.instruments.find((item) => item.id === instrumentId).status, 'voided');
  assert(next.instruments.find((item) => item.id === instrumentId).voidedAt);
  assert(next.orderInstruments.find((item) => item.instrumentId === instrumentId).voidedAt);
  assert(next.orderDocumentSettlements.find((item) => item.orderDocumentId === state.orderDocuments.at(-1).id).voidedAt);
  assert.equal(next.orders.find((item) => item.id === orderId).id, orderId);
  assert.equal(next.documentCompensations.length, state.documentCompensations.length + 1);
  assert.equal(Core.orderBreakdown(next, orderId).compensated, 2294550.61);
  assert.equal(Core.financialMovementRows(next).some((row) => row.id === instrumentId), false);
  assert.equal(Math.round((bankBefore - Core.accountBalances(next).find((item) => item.id === 'ACC-GALICIA-ARS').realBalance) * 100), 229455061);
  assert.equal(Core.flowRows(next).some((row) => row.instrumentId === instrumentId || row.documentId === creditDocumentId), false);
  assert(Core.flowRows(next).some((row) => row.documentId === debtDocumentId && Math.round(row.amount * 100) === -1098));
  assert.deepEqual(Core.economicDocumentRows(next), economicBefore);
  for (const [key, count] of Object.entries(counts)) assert.equal(next[key === 'settlements' ? 'orderDocumentSettlements' : key].length, count);
  const actions = next.auditLog.slice(0, 4).map((item) => item.action);
  assert.deepEqual(actions, ['correct-collection-and-compensate', 'compensate-documents', 'void-scheduled-instrument', 'reverse-realized-instrument']);
  assert(next.auditLog.slice(0, 4).every((item) => item.reason === payload.reason && item.user === 'auditor'));
  assert.deepEqual(Core.validateState(next), []);
});

test('Compensación muestra ambos documentos en Cuenta Corriente sin generar fondos ni resultado', () => {
  const { state, payload, creditDocumentId, debtDocumentId } = erroneousCollectionCompensationFixture();
  const next = Core.correctCollectionAndCompensateTransaction(state, payload, 'test');
  const rows = Core.currentAccountRows(next, { entityId: 'ENT-PROV-AGRI', currency: 'ARS' }).filter((row) => row.source === 'documentCompensation');
  assert.equal(rows.length, 2);
  assert(rows.every((row) => row.id === next.documentCompensations.at(-1).id && row.documentId && row.counterpartDocumentId));
  assert(rows.some((row) => row.documentId === creditDocumentId && row.counterpartDocumentId === debtDocumentId && row.debit === payload.amount && row.credit === 0));
  assert(rows.some((row) => row.documentId === debtDocumentId && row.counterpartDocumentId === creditDocumentId && row.credit === payload.amount && row.debit === 0));
  assert.equal(rows.reduce((total, row) => total + row.debit - row.credit, 0), 0);
  assert.equal(Core.financialMovementRows(next).filter((row) => row.source === 'documentCompensation').length, 0);
  assert.deepEqual(Core.validateState(next), []);
});

