test('Corregir cobro y compensar: dependencias y ambigüedades bloquean sin cambios parciales', () => {
  const { state, payload, debtDocumentId, instrumentId } = erroneousCollectionCompensationFixture();
  const cases = [];
  const dependent = cloneForTest(state);
  dependent.taxPayments.push({ id: 'TX-POST', instrumentId });
  cases.push([dependent, /relacion posterior/]);
  const charge = cloneForTest(state);
  charge.bankCharges.push({ id: 'BCH-MANUAL', instrumentId, autoGenerated: false });
  cases.push([charge, /cargo bancario manual/]);
  const multiple = cloneForTest(state);
  multiple.orderDocumentSettlements.push({ ...multiple.orderDocumentSettlements.at(-1), id: 'ODS-DUP' });
  cases.push([multiple, /imputación múltiple/]);
  const withholding = cloneForTest(state);
  withholding.instruments.find((item) => item.id === instrumentId).amount -= 1;
  withholding.orderInstruments.at(-1).amount -= 1;
  withholding.orderDocumentSettlements.at(-1).amount -= 1;
  withholding.orderTaxWithholdings.push({ id: 'OTW-POST', orderId: state.orders.at(-1).id, orderDocumentId: state.orderDocuments.at(-1).id, taxType: 'withholding_vat', amount: 1, currency: 'ARS', date: '2026-07-23', status: 'withheld', voidedAt: null });
  assert.deepEqual(Core.validateState(withholding), []);
  cases.push([withholding, /efectos o relaciones/, { ...payload, amount: payload.amount - 1 }]);
  const otherEntity = cloneForTest(state);
  otherEntity.documents.find((doc) => doc.id === debtDocumentId).entityId = 'ENT-CLIENTE-DEMO';
  cases.push([otherEntity, /misma contraparte/]);
  const otherCurrency = cloneForTest(state);
  otherCurrency.documents.find((doc) => doc.id === debtDocumentId).currency = 'USD';
  cases.push([otherCurrency, /misma contraparte y moneda/]);
  const sameDirection = cloneForTest(state);
  sameDirection.documents.find((doc) => doc.id === debtDocumentId).commercialSide = 'sale';
  sameDirection.documents.find((doc) => doc.id === debtDocumentId).type = 'sale_invoice';
  cases.push([sameDirection, /ingreso y un egreso/]);
  for (const [snapshot, error, casePayload = payload] of cases) {
    const unchanged = JSON.stringify(snapshot);
    assert.throws(() => Core.correctCollectionAndCompensateTransaction(snapshot, casePayload, 'test'), error);
    assert.equal(JSON.stringify(snapshot), unchanged);
  }
  const result = Core.correctCollectionAndCompensateTransaction(state, payload, 'test');
  assert.throws(() => Core.correctCollectionAndCompensateTransaction(result, payload, 'test'), /transferencia realizada/);
});

