test('Corregir cobro y compensar: elimina cargo bancario automático pero conserva auditoría', () => {
  const fixture = erroneousCollectionCompensationFixture();
  const pending = Core.reverseRealizedInstrumentTransaction(fixture.state, fixture.instrumentId, 'Preparar prueba local', 'test');
  const taxable = Core.updateFinancialAccountTransaction(pending, 'ACC-GALICIA-ARS', { bankTaxTreatment: 'taxable', bankTaxDebitRate: 0.6, bankTaxCreditRate: 0.6, bankTaxEffectiveFrom: '2026-07-01', reason: 'Prueba de cargo' }, 'test');
  const withCharge = Core.transitionInstrument(taxable, fixture.instrumentId, 'executed', '2026-07-23', 'test');
  assert(withCharge.bankCharges.some((charge) => charge.instrumentId === fixture.instrumentId && charge.autoGenerated));
  const next = Core.correctCollectionAndCompensateTransaction(withCharge, fixture.payload, 'auditor');
  assert(!next.bankCharges.some((charge) => charge.instrumentId === fixture.instrumentId));
  assert(next.auditLog.some((entry) => entry.action === 'reverse-realized-instrument' && entry.entityId === fixture.instrumentId));
  assert(next.auditLog[0].changes.find((change) => change.field === 'autoBankCharges').from.some((charge) => charge.id === withCharge.bankCharges.find((item) => item.instrumentId === fixture.instrumentId).id));
  assert(!Core.financialMovementRows(next).some((row) => row.id === fixture.instrumentId || row.source === 'bankCharge' && row.instrumentId === fixture.instrumentId));
  assert.deepEqual(Core.validateState(next), []);
});

test('Reversa bancaria: cargo automático coherente conserva todos sus datos en auditoría', () => {
  const fixture = erroneousCollectionCompensationFixture();
  const pending = Core.reverseRealizedInstrumentTransaction(fixture.state, fixture.instrumentId, 'Prueba local', 'test');
  const taxable = Core.updateFinancialAccountTransaction(pending, 'ACC-GALICIA-ARS', { bankTaxTreatment: 'taxable', bankTaxDebitRate: 0.6, bankTaxCreditRate: 0.6, bankTaxEffectiveFrom: '2026-07-01', reason: 'Prueba local' }, 'test');
  const state = Core.transitionInstrument(taxable, fixture.instrumentId, 'executed', '2026-07-23', 'test');
  const charge = state.bankCharges.find((item) => item.instrumentId === fixture.instrumentId);
  assert(charge);
  assert.equal(charge.date, '2026-07-23');
  assert.equal(Core.bankChargeReversalDetails(state, fixture.instrumentId).charges[0].id, charge.id);
  const beforeBalance = Core.accountBalances(state).find((item) => item.id === charge.financialAccountId).realBalance;
  const next = Core.correctCollectionAndCompensateTransaction(state, fixture.payload, 'auditor');
  const afterBalance = Core.accountBalances(next).find((item) => item.id === charge.financialAccountId).realBalance;
  assert.equal(Math.round((afterBalance - beforeBalance) * 100), Math.round((-state.instruments.find((item) => item.id === fixture.instrumentId).amount + charge.amount) * 100));
  for (const action of ['reverse-realized-instrument', 'correct-collection-and-compensate']) {
    const audit = next.auditLog.find((item) => item.action === action);
    assert.deepEqual(audit.changes.find((item) => item.field === 'autoBankCharges').from, [charge]);
  }
  assert.deepEqual(Core.validateState(next), []);
});

test('Reversa bancaria: fecha, importe y configuración no verificables bloquean sin cambios', () => {
  const fixture = erroneousCollectionCompensationFixture();
  const pending = Core.reverseRealizedInstrumentTransaction(fixture.state, fixture.instrumentId, 'Prueba local', 'test');
  const taxable = Core.updateFinancialAccountTransaction(pending, 'ACC-GALICIA-ARS', { bankTaxTreatment: 'taxable', bankTaxDebitRate: 0.6, bankTaxCreditRate: 0.6, bankTaxEffectiveFrom: '2026-07-01', reason: 'Prueba local' }, 'test');
  const base = Core.transitionInstrument(taxable, fixture.instrumentId, 'executed', '2026-07-23', 'test');
  const cases = [
    [(state) => { state.bankCharges[0].date = '2026-06-17'; }, /fecha.*distinta.*vínculo histórico no verificable/],
    [(state) => { state.bankCharges[0].amount += 1; }, /importe.*distinto.*alícuota/],
    [(state) => { state.bankCharges[0].financialAccountId = 'ACC-NACION-ARS'; }, /moneda, cuenta/],
    [(state) => { state.financialAccounts.find((item) => item.id === 'ACC-GALICIA-ARS').bankTaxCreditRate = 0.3; }, /importe.*distinto.*alícuota/],
    [(state) => { state.bankCharges[0].autoGenerated = 'true'; }, /manual o de origen no verificable/]
  ];
  for (const [mutate, error] of cases) {
    const state = cloneForTest(base);
    mutate(state);
    const unchanged = JSON.stringify(state);
    assert.throws(() => Core.correctCollectionAndCompensateTransaction(state, fixture.payload, 'test'), error);
    assert.equal(JSON.stringify(state), unchanged);
  }
});

test('Reversa bancaria: cargos manuales o de otro instrumento no se seleccionan por importe', () => {
  const fixture = erroneousCollectionCompensationFixture();
  const pending = Core.reverseRealizedInstrumentTransaction(fixture.state, fixture.instrumentId, 'Prueba local', 'test');
  const taxable = Core.updateFinancialAccountTransaction(pending, 'ACC-GALICIA-ARS', { bankTaxTreatment: 'taxable', bankTaxDebitRate: 0.6, bankTaxCreditRate: 0.6, bankTaxEffectiveFrom: '2026-07-01', reason: 'Prueba local' }, 'test');
  let state = Core.transitionInstrument(taxable, fixture.instrumentId, 'executed', '2026-07-23', 'test');
  const charge = state.bankCharges.find((item) => item.instrumentId === fixture.instrumentId);
  const manual = cloneForTest(state);
  manual.bankCharges.push({ ...charge, id: 'BCH-MANUAL-LOCAL', autoGenerated: false });
  assert.throws(() => Core.correctCollectionAndCompensateTransaction(manual, fixture.payload, 'test'), /manual o de origen no verificable/);
  state = Core.createDocumentTransaction(state, { type: 'settlement', commercialSide: 'sale', entityId: 'ENT-PROV-AGRI', number: 'LIQ-SEGUNDA-LOCAL', amount: charge.amount / 0.006, currency: 'ARS', issueDate: '2026-07-22', dueDate: '2026-07-22', activity: 'Agricultura', chartAccountId: 'CA-AGRI', description: 'Otra liquidación' }, 'test');
  const otherDocumentId = state.documents.at(-1).id;
  state = Core.createOrderTransaction(state, { type: 'collection', documentId: otherDocumentId, amountApplied: charge.amount / 0.006, date: '2026-07-22', financialAccountId: 'ACC-GALICIA-ARS', instruments: [{ type: 'transfer', amount: charge.amount / 0.006, scheduledDate: '2026-07-23', status: 'scheduled', reference: 'COBRO-AJENO-LOCAL' }] }, 'test');
  const otherInstrumentId = state.instruments.at(-1).id;
  state = Core.transitionInstrument(state, otherInstrumentId, 'executed', '2026-07-23', 'test');
  const otherCharge = state.bankCharges.find((item) => item.instrumentId === otherInstrumentId);
  assert.equal(otherCharge.amount, charge.amount);
  assert.equal(Core.bankChargeReversalDetails(state, fixture.instrumentId).charges.length, 1);
  const next = Core.correctCollectionAndCompensateTransaction(state, fixture.payload, 'test');
  assert(next.bankCharges.some((item) => item.id === otherCharge.id));
  assert(!next.bankCharges.some((item) => item.id === charge.id));
  assert.deepEqual(Core.validateState(next), []);
  assert.throws(() => Core.correctCollectionAndCompensateTransaction(next, fixture.payload, 'test'), /transferencia realizada/);
});

