testAsync('Corregir cobro y compensar: API versionada guarda todo o nada y rechaza reenvío', async () => {
  const { state, payload, instrumentId } = erroneousCollectionCompensationFixture();
  const store = new JsonPersistenceAdapter({ root: tempPersistenceRoot(), environment: 'demo', Core });
  store.writeValidated(state, 1);
  const send = (candidate, version) => callApiForTest({ method: 'POST', url: '/api/transaction', persistence: store, auth: { required: false }, body: { action: 'correctCollectionAndCompensate', payload: candidate, stateVersion: version } });
  const invalid = await send({ ...payload, amount: payload.amount + 0.01 }, 1);
  assert(invalid.status >= 400);
  assert.equal(store.loadState().stateVersion, 1);
  assert.deepEqual(store.loadState().state, state);
  const accepted = await send(payload, 1);
  assert.equal(accepted.status, 200);
  assert.equal(store.loadState().stateVersion, 2);
  assert.equal(store.loadState().state.documentCompensations.length, state.documentCompensations.length + 1);
  assert.equal(store.loadState().state.instruments.find((item) => item.id === instrumentId).status, 'voided');
  const duplicate = await send(payload, 2);
  assert(duplicate.status >= 400);
  assert.equal(store.loadState().stateVersion, 2);
  assert.equal(store.loadState().state.documentCompensations.length, state.documentCompensations.length + 1);
  assert.deepEqual(Core.validateState(store.loadState().state), []);
});

