test('Financiero: nuevas bases tienen cuentas y bases anteriores requieren alta explicita sin reclasificar', () => {
  assert.equal(Core.minimalDemoState().chartAccounts.filter((item) => item.activity === 'Financiero').length, 5);
  const old = fresh(); old.chartAccounts = old.chartAccounts.filter((item) => item.activity !== 'Financiero');
  old.chartAccounts.push({ id: 'INTERES-COBRADO-ANTERIOR', name: 'Intereses cobrados', activity: 'Estructura/Admin', active: true, parentId: null });
  const before = JSON.stringify(old), docs = cloneForTest(old.documents);
  const next = Core.ensureFinancialChartTransaction(old, 'test');
  assert.equal(JSON.stringify(old), before); assert.deepEqual(next.documents, docs);
  assert(!next.chartAccounts.some((item) => item.name === 'Intereses ganados'));
  assert(Core.chartAccountSupportsActivity(next.chartAccounts.find((item) => item.id === 'INTERES-COBRADO-ANTERIOR'), 'Financiero'));
  assert.equal(Core.ensureFinancialChartTransaction(next, 'test').auditLog.length, next.auditLog.length);
  assert.deepEqual(Core.validateState(next), []);
});

