testAsync('Debito desde Flujo: precarga vencimiento, permite fecha real y conserva emision y entrega', async () => {
  const before = fresh();
  const check = before.instruments.find((item) => item.id === 'INS-CH-30');
  check.issueDate = '2026-09-01'; check.deliveredDate = '2026-09-05';
  let writes = 0;
  const { app, elements, document } = appVmWithPanelDom({ fetch: async (url, options) => {
    assert.equal(options.method, 'POST'); writes++;
    const body = JSON.parse(options.body);
    assert.equal(body.date, '2026-10-03'); assert.equal(body.instrumentId, check.id);
    const state = Core.transitionInstrument(before, check.id, body.status, body.date, 'test');
    return { status: 200, text: async () => JSON.stringify({ ok: true, state, validation: [], stateVersion: 2, environment: 'local' }) };
  } });
  document.getElementById('dateActionInput').focus = () => {};
  app.setTestState(before);
  const pending = app.transitionInstrumentTo(check.id, 'debited');
  assert.equal(elements.get('dateActionInput').value, check.scheduledDate);
  elements.get('dateActionInput').value = '2026-10-03';
  await app.submitDateAction({ currentTarget: document.getElementById('dateActionForm'), preventDefault() {} });
  assert.equal(writes, 1);
  await pending;
  const updated = app.getTestState().instruments.find((item) => item.id === check.id);
  assert.equal(updated.issueDate, check.issueDate); assert.equal(updated.scheduledDate, check.scheduledDate);
  assert.equal(updated.deliveredDate, check.deliveredDate); assert.equal(updated.executedDate, '2026-10-03');
});
